import{f as i,n as u}from"./shared-CAKwAg2C.js";const l={"LEARN HOW THE INTERNET WORKS":"COMMENT FONCTIONNE INTERNET","NOW LEARNING":"LEÇON EN COURS","OSI LAYER":"COUCHE OSI","LEARNING PROGRESS":"VOTRE PROGRESSION",COMPLETE:"TERMINÉES","IN PROGRESS":"EN COURS","{pct}% complete":"{pct} % terminé","DESIGNED BY":"CONÇU PAR","Dilum Sanjaya on X":"Dilum Sanjaya sur X","Layer {n}: {name}":"Couche {n} : {name}",Physical:"Physique","Data Link":"Liaison de données",Network:"Réseau",Transport:"Transport",Session:"Session",Presentation:"Présentation",Application:"Application","OVERVIEW · {n} STEPS":"VUE D’ENSEMBLE · {n} ÉTAPES","STEP {n}/{total} · {title}":"ÉTAPE {n}/{total} · {title}","LESSON COMPLETE":"LEÇON TERMINÉE",PROTOCOLS:"PROTOCOLES",Protocols:"Protocoles",Language:"Langue",Theme:"Thème","Light mode":"Mode clair","Dark mode":"Mode sombre","INTERNET PROTOCOLS":"PROTOCOLES INTERNET",More:"Plus","Close the protocol list":"Fermer la liste des protocoles","Close (Esc)":"Fermer (Échap)",ALL:"TOUS",CORE:"BASE",APPLICATION:"APPLICATION",SECURITY:"SÉCURITÉ",NETWORK:"RÉSEAU",SEQUENCE:"SÉQUENCE",View:"Vue","Switch view (V)":"Changer de vue (V)","Network diagram":"Schéma du réseau","Sequence diagram":"Diagramme de séquence","STEP {n}":"ÉTAPE {n}","PROTOCOL OVERVIEW":"VUE D’ENSEMBLE","STEP DETAILS":"ÉTAPE EN COURS","LESSON SUMMARY":"RÉSUMÉ",OVERVIEW:"DÉBUT",ACTIVE:"ACTIF","STEP {n} OF {total}":"ÉTAPE {n} SUR {total}","PACKET {n} OF {total}":"PAQUET {n} SUR {total}","PACKETS {from}–{to} OF {total}":"PAQUETS {from}–{to} SUR {total}","{n} LOST":"{n} PERDUS","1 LOST":"1 PERDU",ENCRYPTED:"CHIFFRÉ","LOST ON THE WAY":"PERDU EN ROUTE","PACKET FLOW":"FLUX DE PAQUETS","Colour key":"Légende des couleurs","Playback speed":"Vitesse de lecture","Previous step (←)":"Étape précédente (←)","Previous step":"Étape précédente","Play / pause (Space)":"Lecture / pause (Espace)",PLAY:"LECTURE",PAUSE:"PAUSE",REPLAY:"REVOIR",STEP:"AVANCER","One packet at a time":"Un paquet à la fois",RESET:"RÉINITIALISER",Reset:"Réinitialiser","Back to the overview (Esc)":"Retour à la vue d’ensemble (Échap)","NO.":"N°",TIME:"TEMPS",SOURCE:"SOURCE",DESTINATION:"DESTINATION",PROTOCOL:"PROTOCOLE",INFO:"INFO",SIZE:"TAILLE","No packets on the wire yet.":"Aucun paquet sur le réseau pour l’instant.",LOST:"PERDU","Packet inspector":"Inspecteur de paquets","Previous packet":"Paquet précédent","Previous packet (←)":"Paquet précédent (←)","Next packet":"Paquet suivant","Next packet (→)":"Paquet suivant (→)",Close:"Fermer","E.G.":"EX.","an example value: it differs in every real capture":"une valeur d’exemple : elle change à chaque capture réelle","bytes the lesson can’t show: encrypted, random, or a file’s contents":"octets que la leçon ne peut pas montrer : chiffrés, aléatoires ou contenu d’un fichier",BYTES:"OCTETS","{n} in this frame":"{n} dans cette trame","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Cette ligne représente {n} segments TCP portant un message de {size} octets ; le premier segment est affiché","This packet was lost on the way":"Ce paquet s’est perdu en route",Padding:"Bourrage","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · BAIL 24 H","2 SEGMENTS":"2 SEGMENTS","3 SEGMENTS":"3 SEGMENTS","3 DATAGRAMS":"3 DATAGRAMMES","4 DATAGRAMS":"4 DATAGRAMMES","203.0.113.10 IS NOT LOCAL":"203.0.113.10 N’EST PAS LOCALE","250 QUEUED":"250 EN FILE",ANSWER:"RÉPONSE","APP COVERS THE 20 MS GAP":"L’APPLI COMBLE LE TROU DE 20 MS","APP DATA":"DONNÉES APPLI","ARP REPLY":"RÉPONSE ARP","ARP REQUEST":"REQUÊTE ARP","ARRIVED WITH TTL 116":"ARRIVÉ AVEC TTL 116","AUTH FAILURE":"ÉCHEC AUTH","At QUIT":"Au QUIT","CACHED · TTL 3600 S":"EN CACHE · TTL 3600 S","CERTIFICATE VALID":"CERTIFICAT VALIDE","CHAIN LEADS TO A TRUSTED ROOT":"LA CHAÎNE MÈNE À UNE RACINE DE CONFIANCE","CHANNEL OPEN":"OUVRIR UN CANAL",CONFIRMED:"CONFIRMÉ","DNS QUERY":"REQUÊTE DNS","DNS REPLY":"RÉPONSE DNS","DUP ACK":"ACK DUPLIQUÉ","EACH KEY IS ITS OWN PACKET":"CHAQUE TOUCHE, SON PAQUET",ECHO:"ÉCHO","ECHO REPLY":"RÉPONSE ÉCHO","ECHO REQUEST":"REQUÊTE ÉCHO",ENTER:"ENTRÉE","FRAME 7 LOST · NOT RESENT":"TRAME 7 PERDUE · PAS RENVOYÉE","HOP 2 · 198.51.100.1":"SAUT 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"LA CLÉ D’HÔTE CORRESPOND À KNOWN_HOSTS","IN BOB’S MAILBOX":"DANS LA BOÎTE DE BOB","IP PACKET":"PAQUET IP",MESSAGE:"MESSAGE","MESSAGE 1 DELETED":"MESSAGE 1 SUPPRIMÉ","NEW MAIL ARRIVED":"NOUVEAU COURRIER ARRIVÉ","NO IP ADDRESS YET":"PAS ENCORE D’ADRESSE IP","NOT IN CACHE":"PAS EN CACHE","OFFER KEY":"PROPOSE UNE CLÉ",OUTPUT:"SORTIE","PASSWORD IN PLAIN TEXT":"MOT DE PASSE EN CLAIR",REFERRAL:"RÉFÉRENCE",REPLY:"RÉPONSE",RESEND:"RENVOI","SEGMENT 1 LOST":"SEGMENT 1 PERDU","SFTP or FTPS":"SFTP ou FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP, ou FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"SECRET PARTAGÉ CALCULÉ",SIGNED:"SIGNÉ","STILL ON SERVER · \\SEEN":"TOUJOURS SUR LE SERVEUR · \\SEEN",SUCCESS:"SUCCÈS","TIME EXCEEDED":"TEMPS DÉPASSÉ","TIME=34MS TTL=52":"TEMPS=34 MS TTL=52",UNREACHABLE:"INACCESSIBLE",VERSION:"VERSION","VOICE 1":"VOIX 1","+OK or -ERR":"+OK ou -ERR",".com Server":"Serveur .com",Authoritative:"Faisant autorité","Log In":"Connexion",Key:"Clé",Why:"Pourquoi",End:"Fin","MACs, in":"MAC, entrée",Internet:"Internet",Router:"Routeur","Router 192.168.1.1":"Routeur 192.168.1.1","Router: 192.168.1.1":"Routeur : 192.168.1.1",Routers:"Routeurs",Hardware:"Matériel",Audio:"Audio",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic cookie",Visible:"Visible",Tickets:"Tickets","4, 20 bytes":"4, 20 octets","20–60 bytes":"20–60 octets","20–60 bytes (IPv4)":"20–60 octets (IPv4)","8 bytes (TCP: 20+)":"8 octets (TCP : 20+)","32 bytes (Windows)":"32 octets (Windows)","1,460 bytes (MSS)":"1,460 octets (MSS)","78 bytes (seq 1–78)":"78 octets (seq 1–78)","bytes 1461–2920":"octets 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 octets)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 octets)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 octets), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 octets)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 octets)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 octets)',"32 bits (IPv4), 128 (IPv6)":"32 bits (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 → 52 (12 routeurs)","52 (64 − 12 routers)":"52 (64 − 12 routeurs)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 octets","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 octets (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + audio","One packet at a time (S)":"Un paquet à la fois (S)","KEYBOARD SHORTCUTS":"RACCOURCIS CLAVIER","Press {key} any time to see these again.":"Appuyez sur {key} à tout moment pour les revoir.","Search protocols":"Rechercher","Search protocols and steps":"Rechercher protocoles et étapes","Nothing matches.":"Aucun résultat.","to move":"pour se déplacer","to open":"pour ouvrir","Protocol list":"Liste des protocoles","Diagram only":"Schéma seul",Fullscreen:"Plein écran","Keyboard shortcuts":"Raccourcis clavier",Playback:"Lecture","Hide the protocol list (L)":"Masquer la liste des protocoles (L)","Diagram only (D)":"Schéma seul (D)","Fullscreen (F)":"Plein écran (F)","Keyboard shortcuts (?)":"Raccourcis clavier (?)","Show the protocol list (L)":"Afficher la liste des protocoles (L)","Show all panels (D)":"Afficher tous les panneaux (D)","Exit fullscreen (F)":"Quitter le plein écran (F)","Play or pause":"Lecture ou pause","Next step":"Étape suivante","Go to step 1 to 9":"Aller aux étapes 1 à 9","Slower, faster":"Plus lent, plus rapide","Back to the overview":"Retour à la vue d’ensemble","Network or sequence view":"Vue réseau ou séquence","Show or hide the protocol list":"Afficher ou masquer la liste des protocoles","Light or dark theme":"Thème clair ou sombre",Find:"Rechercher","Next or previous protocol":"Protocole suivant ou précédent","These shortcuts":"Ces raccourcis","Previous or next packet":"Paquet précédent ou suivant","Close it":"Le fermer"},d={"Hypertext Transfer Protocol":"Transfert hypertexte","HTTP Secure":"HTTP sécurisé","Transmission Control Protocol":"Contrôle de transmission","User Datagram Protocol":"Datagrammes utilisateur","Internet Protocol":"Protocole Internet","Domain Name System":"Système de noms de domaine","Dynamic Host Configuration":"Configuration dynamique d’hôte","Internet Control Message":"Messages de contrôle Internet","Simple Mail Transfer Protocol":"Transfert simple de courrier","Post Office Protocol v3":"Protocole de bureau de poste v3","Internet Message Access":"Accès aux messages Internet","File Transfer Protocol":"Transfert de fichiers","Secure Shell":"Shell sécurisé","Transport Layer Security":"Sécurité de la couche transport",Internet:"Internet",Client:"Client",Router:"Routeur","DNS Resolver":"Résolveur DNS","Web Server":"Serveur web","Root Server":"Serveur racine",".com TLD Server":"Serveur TLD .com","Authoritative Server":"Serveur faisant autorité","Mail Server":"Serveur de messagerie","Web Communication":"Communication web",Request:"Requête",Response:"Réponse","Data ACKs not shown":"ACK de données non affichés","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP est le protocole du web : un client demande une ressource, comme une page HTML, et le serveur répond par un code d’état, des en-têtes et généralement un corps. Chaque échange se compose d’une requête et d’une réponse, écrites en texte lisible en HTTP/1.1.",Layer:"Couche","Application (Layer 7)":"Application (couche 7)","Default Port":"Port par défaut",Transport:"Transport","Data Format":"Format des données","Text (headers + optional body)":"Texte (en-têtes + corps facultatif)","Common Methods":"Méthodes courantes","Defined In":"Défini dans","Page delivered":"Page livrée","One request, one response":"Une requête, une réponse","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"En moins d’un dixième de seconde, l’ordinateur a cherché une adresse, ouvert une connexion TCP et échangé une requête et une réponse HTTP, le tout lisible par n’importe qui sur le trajet. Appuyez sur REVOIR pour tout revoir.","Round trips":"Allers-retours","Total time":"Durée totale","Page size":"Taille de la page","Sent as 9 TCP segments":"Envoyée en 9 segments TCP","Client Request":"Requête du client","Browser prepares the request":"Le navigateur prépare la requête","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Vous ouvrez http://www.example.com. Le navigateur va envoyer une requête GET, mais les paquets voyagent vers des adresses IP, pas vers des noms : il lui faut donc d’abord l’adresse du serveur. (Les navigateurs essaient désormais https:// en premier ; ceci est la version non chiffrée.)",Method:"Méthode","Next hop":"Prochain saut","Router 192.168.1.1":"Routeur 192.168.1.1","DNS Resolution":"Résolution DNS","Finds the server’s IP address":"Trouve l’adresse IP du serveur","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"L’ordinateur demande au serveur DNS que DHCP lui a attribué, 8.8.8.8, l’adresse de www.example.com. La requête passe par le port UDP 53 et la réponse est un enregistrement A contenant l’adresse IPv4. (Sur un réseau IPv6, il demanderait aussi un enregistrement AAAA.)",Resolver:"Résolveur","8.8.8.8 (had it cached)":"8.8.8.8 (l’avait en cache)","UDP, port 53":"UDP, port 53",Answer:"Réponse","TCP Connection":"Connexion TCP","Establishes a reliable link":"Établit un lien fiable","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP fonctionne au-dessus de TCP. Avant que la moindre donnée de la page circule, l’ordinateur et le serveur ouvrent une connexion vers le port 80 par une poignée de main en trois temps : SYN, SYN-ACK, ACK.","Server port":"Port du serveur","Client port":"Port du client",Handshake:"Poignée de main","HTTP Exchange":"Échange HTTP","Request and response messages":"Messages de requête et de réponse","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Le navigateur envoie une requête GET avec un en-tête Host. Le serveur répond 200 OK avec le HTML dans le corps : 12.2 KB, trop gros pour un seul paquet, donc TCP le découpe en 9 segments d’au plus 1460 octets (dessinés ici comme un seul).",Status:"Statut",Body:"Corps","Sent as":"Envoyée en","12.2 KB in 9 segments":"12.2 KB en 9 segments","Page Rendering":"Affichage de la page","Browser displays the content":"Le navigateur affiche le contenu","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Le navigateur analyse le HTML et dessine la page. Chaque CSS, image ou script lié lancerait d’autres requêtes comme celle-ci, en réutilisant la connexion ouverte quand c’est possible.",Document:"Document",Connection:"Connexion","Kept open for reuse":"Gardée ouverte pour être réutilisée","Seen on the laptop’s home network":"Vu sur le réseau domestique de l’ordinateur",Destination:"Destination","The router: anything beyond the home network goes to it first.":"Le routeur : tout ce qui sort du réseau domestique passe d’abord par lui.",Source:"Source","The laptop’s network card.":"La carte réseau de l’ordinateur.",Type:"Type","What the frame carries.":"Ce que transporte la trame.","Version, header length":"Version, longueur d’en-tête","IPv4, with no options.":"IPv4, sans options.","Priority and congestion marks; 0 means ordinary traffic.":"Marques de priorité et de congestion ; 0 signifie un trafic ordinaire.","Total length":"Longueur totale","This header and everything inside it.":"Cet en-tête et tout ce qu’il contient.",Identification:"Identification","Lets the receiver reassemble the pieces if the packet gets split.":"Permet au destinataire de réassembler les morceaux si le paquet est fragmenté.",Flags:"Drapeaux",none:"aucun","Routers may split it if a link is too small.":"Les routeurs peuvent le fragmenter si un lien est trop petit.","Time to live":"Durée de vie","Windows starts at 128.":"Windows commence à 128.",Protocol:"Protocole","Header checksum":"Somme de contrôle de l’en-tête","Covers this header only; every router recomputes it after lowering the TTL.":"Ne couvre que cet en-tête ; chaque routeur la recalcule après avoir diminué le TTL.","Source port":"Port source","Destination port":"Port de destination",Length:"Longueur","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"En-tête UDP et données. C’est tout UDP : ni numérotation, ni accusés de réception.",Checksum:"Somme de contrôle","Covers the header, the data and the IP addresses.":"Couvre l’en-tête, les données et les adresses IP.","Transaction ID":"ID de transaction","Picked at random; the answer must carry the same one.":"Choisi au hasard ; la réponse doit porter le même.","0x0100: query, RD (recursion desired)":"0x0100 : requête, RD (récursion souhaitée)",Questions:"Questions",Answers:"Réponses","Authority records":"Enregistrements d’autorité","Additional records":"Enregistrements additionnels",Question:"Question","www.example.com, type A, class IN":"www.example.com, type A, classe IN","The laptop.":"L’ordinateur.","The router’s side facing the home network.":"Le côté du routeur tourné vers le réseau domestique.","Started at 128; 10 routers on the way each took 1.":"Parti de 128 ; chacun des 10 routeurs du trajet a retiré 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180 : réponse, RD (récursion souhaitée), RA (récursion disponible)","DF (don’t fragment)":"DF (ne pas fragmenter)","Routers must not split it; if it’s too big they report back instead.":"Les routeurs ne doivent pas le fragmenter ; s’il est trop gros, ils le signalent en retour.","Picked by the laptop’s system for this connection.":"Choisi par le système de l’ordinateur pour cette connexion.","Sequence number":"Numéro de séquence","This side’s starting number. Shown as 0; the real one is random.":"Le numéro de départ de ce côté. Affiché comme 0 ; le vrai est aléatoire.","Real sequence number":"Numéro de séquence réel",Acknowledgment:"Accusé de réception","0 (not used yet)":"0 (pas encore utilisé)","A first SYN has nothing to acknowledge.":"Un premier SYN n’a rien à accuser.","Header length":"Longueur d’en-tête","20 bytes, plus 12 of options.":"20 octets, plus 12 d’options.",Window:"Fenêtre","How much more data this side can take right now.":"La quantité de données que ce côté peut encore recevoir maintenant.","Covers the header, the data and the IP addresses, so damage is caught.":"Couvre l’en-tête, les données et les adresses IP, pour détecter les dégâts.","Urgent pointer":"Pointeur d’urgence",Options:"Options","Maximum segment size":"Taille maximale de segment","The most data this side wants in one segment.":"Le maximum de données que ce côté veut dans un segment.","Spacing, so the next option lines up.":"Remplissage, pour aligner l’option suivante.","Window scale":"Facteur d’échelle de fenêtre","Window values are multiplied by this, so windows can be larger than 64 KB.":"Les valeurs de fenêtre sont multipliées par ce facteur, pour des fenêtres de plus de 64 KB.","SACK permitted":"SACK autorisé",yes:"oui","This side understands selective acknowledgements.":"Ce côté comprend les accusés de réception sélectifs.","Started at 64; 12 routers on the way each took 1.":"Parti de 64 ; chacun des 12 routeurs du trajet a retiré 1.","The next byte this side expects: everything before it has arrived.":"Le prochain octet attendu par ce côté : tout ce qui précède est arrivé.","Position of this segment’s first byte, counted from this side’s SYN.":"Position du premier octet de ce segment, comptée depuis le SYN de ce côté.",Padding:"Bourrage","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Les trames Ethernet font au moins 60 octets (64 avec la somme de contrôle ajoutée par la carte), donc les plus courtes sont complétées.",Text:"Texte","covers bytes not shown here":"couvre des octets non affichés ici","12,500 bytes: the HTML page":"12,500 octets : la page HTML","The page itself; its contents are not part of the lesson.":"La page elle-même ; son contenu ne fait pas partie de la leçon.","Secure Web":"Web sécurisé","TLS handshake":"Négociation TLS","HTTP request":"Requête HTTP","HTTP response":"Réponse HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS, c’est HTTP envoyé dans une connexion TLS chiffrée. TLS prouve par un certificat que le serveur est bien celui qu’il prétend être, convient de nouvelles clés de chiffrement, puis protège chaque requête et réponse contre la lecture ou la modification en route.","Application (HTTP over TLS)":"Application (HTTP sur TLS)",Security:"Sécurité","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 encore courant)",Proves:"Prouve","Server identity (certificate)":"L’identité du serveur (certificat)","Secure page delivered":"Page sécurisée livrée","Encrypted, except the lookup":"Chiffrée, sauf la résolution DNS","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Le navigateur a cherché l’adresse en DNS non chiffré, ouvert une connexion TCP, vérifié le certificat du serveur et convenu des clés en un seul aller-retour. Chaque octet HTTP a ensuite voyagé chiffré. Appuyez sur REVOIR pour tout revoir.",Cipher:"Chiffrement","Still visible":"Toujours visible","IPs, server name, sizes":"IP, nom du serveur, tailles","Secure Request":"Requête sécurisée","Browser asks for https://":"Le navigateur demande https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Vous tapez https://www.example.com. Le « s » indique au navigateur de protéger la connexion par TLS, sur le port 443 par défaut. Avant même de se connecter, il doit encore trouver l’adresse IP du serveur.",Port:"Port","DNS Lookup":"Résolution DNS","Same lookup as HTTP, not encrypted":"La même résolution qu’en HTTP, non chiffrée","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"La résolution est exactement la même qu’en HTTP simple : une requête vers 8.8.8.8 sur le port UDP 53. Elle n’est pas chiffrée, donc n’importe qui sur le trajet peut voir quel nom vous avez demandé, sauf si le navigateur utilise DNS over HTTPS.",Encrypted:"Chiffré","No (plain DNS)":"Non (DNS en clair)","TCP Handshake":"Poignée de main TCP","Opens a connection to port 443":"Ouvre une connexion vers le port 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS s’appuie sur TCP, donc la même poignée de main en trois temps vient d’abord, cette fois vers le port 443. Rien n’est encore chiffré.","TLS Handshake":"Négociation TLS","Agrees on keys, checks the certificate":"Convient des clés, vérifie le certificat","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Le navigateur propose des suites de chiffrement et des parts de clé, dont un hybride post-quantique. Le serveur le choisit et envoie sa propre part, puis son certificat, déjà chiffré. Le navigateur le vérifie auprès des autorités en qui il a confiance.",Version:"Version","Key exchange":"Échange de clés","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (hybride)","Server name":"Nom du serveur","Sent in clear (SNI)":"Envoyé en clair (SNI)","key shares: hybrid + x25519":"parts de clé : hybride + x25519","cipher: AES_128_GCM_SHA256":"chiffrement : AES_128_GCM_SHA256","then encrypted: cert, Finished":"puis chiffré : cert., Finished","handshake complete (encrypted)":"négociation terminée (chiffrée)","Encrypted Exchange":"Échange chiffré","HTTP inside TLS records":"HTTP dans des enregistrements TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"Le GET et le 200 OK sont les mêmes messages HTTP qu’avant, scellés dans des enregistrements TLS qui ressemblent à des « données d’application » aléatoires sur le réseau. Le serveur remet aussi deux tickets de session, pour qu’une visite ultérieure puisse sauter une partie de la négociation.",Inside:"À l’intérieur","GET / and 200 OK":"GET / et 200 OK",Tickets:"Tickets","2, for faster reconnects":"2, pour des reconnexions plus rapides","inside: GET / HTTP/1.1":"dedans : GET / HTTP/1.1","outside: encrypted bytes":"dehors : octets chiffrés","inside: HTTP/1.1 200 OK":"dedans : HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"dehors : 12.9 KB, 9 segments","Browser shows the padlock":"Le navigateur affiche le cadenas","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Le navigateur déchiffre la réponse, dessine la page et affiche un cadenas : la connexion est privée et le serveur a prouvé son identité. L’en-tête Strict-Transport-Security lui indique d’utiliser HTTPS pour ce site désormais.",Remembers:"Retient","HTTPS only (HSTS), 1 year":"HTTPS uniquement (HSTS), 1 an","Server Hello + encrypted handshake, 3 segments":"Server Hello + négociation chiffrée, 3 segments","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (chiffré)","Application Data (HTTP request)":"Application Data (requête HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (chiffré)","Application Data (HTTP response), 9 segments":"Application Data (réponse HTTP), 9 segments",Record:"Enregistrement","Content type":"Type de contenu","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"L’enregistrement d’un Client Hello indique TLS 1.0 pour que les anciens équipements intermédiaires le laissent passer ; les vraies versions sont proposées à l’intérieur.","Handshake type":"Type de négociation",Contents:"Contenu","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Tout ce que le navigateur prend en charge. Les navigateurs varient quelques détails d’une connexion à l’autre.","Server name (SNI)":"Nom du serveur (SNI)","Versions offered":"Versions proposées","Key shares":"Parts de clé","App protocols (ALPN)":"Protocoles d’application (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"Les enregistrements TLS 1.3 indiquent 1.2 à l’extérieur, par compatibilité.","The server’s choices and its half of the hybrid key exchange.":"Les choix du serveur et sa moitié de l’échange de clés hybride.","Cipher suite":"Suite de chiffrement","Key share":"Part de clé","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"N’a aucun rôle en TLS 1.3 ; envoyé pour que les équipements intermédiaires voient une négociation familière.","Every encrypted record says Application Data on the outside; the real type is inside.":"Tout enregistrement chiffré indique Application Data à l’extérieur ; le vrai type est à l’intérieur.","Encrypted data":"Données chiffrées","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Texte chiffré, terminé par une étiquette de 16 octets qui révèle toute modification. Seules les deux extrémités peuvent le lire.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN : http/1.1), Certificate (la chaîne), Certificate Verify (la signature), Finished","Finished: a check value over the whole handshake":"Finished : une valeur de contrôle sur toute la négociation","The HTTP request":"La requête HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket : permet de reprendre la session lors d’une visite ultérieure","The HTTP response, then the 12,500-byte page":"La réponse HTTP, puis la page de 12,500 octets","Reliable Delivery":"Livraison fiable","Handshake and ACKs":"Poignée de main et ACK","Data from laptop":"Données de l’ordinateur","Data from server":"Données du serveur","Closing (FIN)":"Fermeture (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP transforme la livraison de paquets « au mieux » d’Internet en un flux d’octets fiable et ordonné. Il numérote chaque octet, accuse réception de ce qui arrive, renvoie ce qui se perd et règle le rythme de l’émetteur pour ne submerger ni l’autre côté ni le réseau.","Transport (Layer 4)":"Transport (couche 4)","Three-way handshake":"Poignée de main en trois temps",Reliability:"Fiabilité","Sequence numbers + ACKs":"Numéros de séquence + ACK",Recovery:"Récupération",Retransmission:"Retransmission",Header:"En-tête","Connection closed":"Connexion fermée","Every byte accounted for":"Chaque octet compté","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP a ouvert une connexion, numéroté et acquitté chaque octet, repéré un trou et renvoyé uniquement le segment manquant, puis fermé proprement les deux sens. curl a reçu tous les octets dans l’ordre sans jamais voir la perte. Appuyez sur REVOIR pour tout revoir.",Segments:"Segments","14 (1 lost, 1 resent)":"14 (1 perdu, 1 renvoyé)","Bytes delivered":"Octets livrés","78 up, 2,920 down":"78 en montée, 2,920 en descente","Loss found by":"Perte détectée par","Duplicate ACK + SACK":"ACK dupliqué + SACK","Open Connection":"Ouvrir la connexion","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl connaît déjà l’adresse du serveur. Avant que la moindre donnée circule, les deux côtés choisissent un numéro de séquence initial et le confirment : SYN, SYN-ACK, ACK. Les numéros sont ici relatifs ; les vrais partent d’une valeur aléatoire.",Server:"Serveur","203.0.113.10, port 80":"203.0.113.10, port 80","Send Data":"Envoyer des données","Every byte is numbered":"Chaque octet est numéroté","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl envoie sa requête HTTP de 78 octets : les octets 1 à 78. Le numéro d’ACK du serveur, 79, est le prochain octet qu’il attend, ce qui signifie que tout ce qui précède est arrivé.",Sent:"Envoyé","79 = next byte expected":"79 = prochain octet attendu","Two Segments Back":"Deux segments en retour","One of them is lost":"L’un d’eux se perd","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Le serveur répond avec 2,920 octets : deux segments pleins de 1,460 octets, le maximum qui tient ici dans un paquet, envoyés à la suite. Le premier se perd quelque part sur Internet ; le second passe.","Segment 1":"Segment 1","bytes 1–1460 (lost)":"octets 1–1460 (perdu)","Segment 2":"Segment 2","Segment size":"Taille de segment","seq=1 and seq=1461":"seq=1 et seq=1461","the first is lost":"le premier se perd","A Gap Is Noticed":"Un trou est repéré","Duplicate ACK with SACK":"ACK dupliqué avec SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Les octets 1461–2920 arrivent, mais jamais les octets 1–1460. Un ACK ne peut compter que les octets reçus dans l’ordre, donc l’ordinateur répète aussitôt l’ACK 1 et ajoute un bloc SACK indiquant qu’il a déjà 1461–2920.","1 (still waiting for byte 1)":"1 (attend toujours l’octet 1)","holds bytes 1461–2920":"a les octets 1461–2920","At once, not delayed":"Aussitôt, sans délai","sack: has 1461–2920":"sack : a 1461–2920","Resend the Gap":"Renvoyer le trou","Only the missing bytes":"Seulement les octets manquants","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"Le SACK indique au serveur exactement ce qui manque, donc il renvoie seulement le segment 1, et l’ordinateur acquitte tout. Si aucun ACK n’était revenu, des minuteurs auraient pris le relais : d’abord une sonde après environ deux allers-retours, puis le délai de retransmission (au moins 200 ms sous Linux).",Resent:"Renvoyé","bytes 1–1460 only":"octets 1–1460 seulement","Next ACK":"ACK suivant","2921 (everything)":"2921 (tout)","curl saw":"curl a vu","Every byte, in order":"Tous les octets, dans l’ordre","just the missing segment":"seulement le segment manquant","Close Connection":"Fermer la connexion","Each side says goodbye":"Chaque côté dit au revoir","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl a terminé, il ferme donc. Chaque sens se ferme séparément : l’ordinateur envoie FIN et le serveur l’acquitte, puis le serveur envoie son propre FIN et l’ordinateur l’acquitte. L’ordinateur garde les détails de la connexion un moment (TIME-WAIT).","Closed by":"Fermée par","A FIN from each side":"Un FIN de chaque côté",Order:"Ordre",Then:"Puis","Laptop waits (TIME-WAIT)":"L’ordinateur attend (TIME-WAIT)",Data:"Données","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 octets : la réponse HTTP, octets 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 octets : la réponse HTTP, octets 1461–2920","has 1461–2920":"a 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Des octets arrivés après le trou, donc seul le trou doit être renvoyé.","Fast Datagrams":"Datagrammes rapides","Your voice":"Votre voix","Their voice":"Sa voix","Media Server":"Serveur multimédia","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP envoie des données dans des paquets indépendants appelés datagrammes, sans connexion, sans accusés de réception ni renvois. C’est ce qui le rend rapide et léger : idéal pour la voix, la vidéo, les jeux et le DNS, où une réponse tardive est pire qu’une réponse manquante.",None:"Aucune","None (no ACKs, no resends)":"Aucune (ni ACK, ni renvoi)",Ordering:"Ordre","Not guaranteed":"Non garanti","Call keeps flowing":"L’appel continue","Fast, simple, no guarantees":"Rapide, simple, sans garanties","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"L’audio a commencé dès le premier paquet, chaque datagramme a voyagé seul, et celui qui s’est perdu a tout simplement disparu : UDP ne s’en est jamais aperçu. L’appli a comblé le trou et l’appel a continué. Appuyez sur REVOIR pour tout revoir.",Datagrams:"Datagrammes","11 (1 lost, never resent)":"11 (1 perdu, jamais renvoyé)","Setup time":"Temps d’établissement","0 ms (no handshake)":"0 ms (pas de poignée de main)",Shown:"Montré","The first 0.2 s of a call":"Les 0.2 premières secondes d’un appel","Send Right Away":"Envoyer tout de suite","No handshake, data goes first":"Pas de poignée de main, les données partent d’abord","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Une appli d’appel connaît déjà l’adresse et le port du serveur multimédia depuis la connexion au compte. Elle n’ouvre aucune connexion : le tout premier datagramme transporte déjà 20 ms de votre voix, derrière un en-tête UDP de 8 octets.",Setup:"Établissement",Ports:"Ports","92 B of audio, no setup":"92 B d’audio, sans établissement","A Stream of Datagrams":"Un flux de datagrammes","One every 20 ms, each on its own":"Un toutes les 20 ms, chacun seul","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"L’appli continue d’envoyer un datagramme toutes les 20 ms. Chacun est autonome, avec son propre en-tête et sans lien avec les autres. UDP ne les numérote pas, et rien ne revient confirmer leur arrivée.",Rate:"Débit","1 datagram / 20 ms":"1 datagramme / 20 ms",Numbering:"Numérotation","None in UDP itself":"Aucune dans UDP lui-même",Confirmation:"Confirmation","None (no ACKs)":"Aucune (pas d’ACK)","voice frames 2–5":"trames vocales 2–5","each with its own 8-byte header":"chacune avec son en-tête de 8 octets","Lost on the Way":"Perdu en route","Nobody resends it":"Personne ne le renvoie","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"La trame 7 se perd quelque part sur Internet. Le serveur multimédia ne la redemande jamais et UDP ne prévient jamais l’ordinateur : il n’y a pas d’accusés de réception dont l’absence se remarquerait. Les datagrammes suivants arrivent normalement.",Lost:"Perdue","Voice frame 7":"Trame vocale 7","Never (no ACKs)":"Jamais (pas d’ACK)",Missing:"Manquant","20 ms of audio":"20 ms d’audio","voice frames 6–8":"trames vocales 6–8","frame 7 is lost":"la trame 7 se perd","Replies Come Back":"Les réponses reviennent","The other voice comes back":"L’autre voix revient","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"La voix de l’autre personne arrive de la même façon, en datagrammes séparés envoyés au port 50000. Ils peuvent entrer parce que votre routeur a retenu le port de sortie en traduisant votre adresse (NAT).",Direction:"Sens","Independent of ours":"Indépendant du nôtre","Through NAT":"À travers le NAT","Router remembers the port":"Le routeur retient le port","the other person’s voice":"la voix de l’autre personne","sent to port 50000":"envoyée au port 50000","The App Decides":"L’appli décide","Reliability is up to the app":"La fiabilité dépend de l’appli","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"L’appli d’appel numérote ses propres trames (c’est le rôle de RTP), elle voit donc que la trame 7 manque et masque le trou de 20 ms au lieu d’attendre. Attendre un renvoi retarderait tout l’appel.","App’s job (e.g. RTP)":"Le travail de l’appli (ex. RTP)",Loss:"Perte","Hidden by the app":"Masquée par l’appli","Also on UDP":"Aussi sur UDP","DNS, games, QUIC":"DNS, jeux, QUIC","Version etc.":"Version, etc.","2, no padding, no extension, no CSRCs":"2, sans bourrage, sans extension, sans CSRC","Marker, payload type":"Marqueur, type de charge utile","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, convenu à l’établissement de l’appel)","Counts up by one per packet, so the app can spot a missing or late one.":"Augmente de un par paquet, pour que l’appli repère un paquet manquant ou en retard.",Timestamp:"Horodatage","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Horloge audio à 48,000 par seconde : +960 par trame de 20 ms.","Identifies this audio stream.":"Identifie ce flux audio.",Audio:"Audio","80 bytes of Opus audio (20 ms)":"80 octets d’audio Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, convenu à l’établissement de l’appel)","Addressing & Routing":"Adressage et routage","Outgoing packet":"Paquet sortant",Reply:"Réponse","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP donne une adresse à chaque appareil et achemine les paquets de réseau en réseau. Chaque routeur ne regarde que l’adresse de destination pour choisir le prochain saut. IP fonctionne « au mieux » : il ne promet ni la livraison ni l’ordre. TCP ajoute cela par-dessus.","Network (Layer 3)":"Réseau (couche 3)",Address:"Adresse","Lowered by 1 at each router":"Diminue de 1 à chaque routeur",Delivery:"Livraison","Best effort":"Au mieux","There and back":"Aller et retour","Twelve routers each way":"Douze routeurs dans chaque sens","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"L’ordinateur a envoyé le paquet à son routeur, qui y a mis son adresse publique. Douze routeurs au total l’ont relayé d’après la seule adresse de destination, et la réponse est revenue de la même façon. Appuyez sur REVOIR pour tout revoir.",Routers:"Routeurs","12 each way (1 home + 11)":"12 dans chaque sens (1 domestique + 11)","TTL at server":"TTL au serveur","116 (sent with 128)":"116 (envoyé avec 128)","Rewritten by NAT":"Réécrit par le NAT","Source out, destination back":"Source à l’aller, destination au retour","IPv4 (IPv6 works alike)":"IPv4 (IPv6 fonctionne pareil)","Local or Not?":"Local ou pas ?","Compare the address with the subnet":"Comparer l’adresse au sous-réseau","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"L’ordinateur a l’adresse 192.168.1.10 avec un masque /24, donc son propre réseau va de 192.168.1.0 à 192.168.1.255. Le serveur, 203.0.113.10, est hors de cette plage, donc le paquet doit passer par la passerelle par défaut : le routeur de la maison.",Laptop:"Ordinateur","Local range":"Plage locale",Gateway:"Passerelle","Find the Router":"Trouver le routeur","ARP turns an IP into a MAC":"ARP transforme une IP en MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Sur le réseau local, les trames sont livrées par adresse MAC. Si la MAC du routeur n’est pas dans le cache ARP de l’ordinateur, celui-ci diffuse « qui a 192.168.1.1 ? » et le routeur répond avec son adresse MAC.",Asks:"Demande","Who has 192.168.1.1?":"Qui a 192.168.1.1 ?","Sent to":"Envoyé à","Everyone (broadcast)":"Tout le monde (diffusion)",Learns:"Apprend","Router’s MAC address":"L’adresse MAC du routeur","who has 192.168.1.1?":"qui a 192.168.1.1 ?","tell 192.168.1.10":"répondre à 192.168.1.10","Send the Packet":"Envoyer le paquet","Addresses, TTL and protocol":"Adresses, TTL et protocole","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"L’en-tête IP contient les adresses source et destination, un TTL et le protocole transporté. Ici, il contient un SYN TCP vers le port 443. Windows démarre le TTL à 128 (Linux et macOS utilisent 64).","From → to":"De → vers","TTL 128 · protocol TCP":"TTL 128 · protocole TCP","NAT, Then Hop by Hop":"NAT, puis saut par saut","The router rewrites and forwards":"Le routeur réécrit et transmet","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Le routeur remplace la source privée par son adresse publique 198.51.100.7 (et ici le port 52344 par 40112), note la correspondance et abaisse le TTL à 127. Puis 11 routeurs sur Internet choisissent chacun le prochain saut d’après la destination et abaissent à nouveau le TTL.","New source":"Nouvelle source","Leaves home":"Quitte la maison","At the server":"Au serveur","TTL 116 (11 more hops)":"TTL 116 (11 sauts de plus)","TTL 127 · after NAT":"TTL 127 · après le NAT","The Reply Comes Back":"La réponse revient","NAT translates it for the laptop":"Le NAT la traduit pour l’ordinateur","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Le serveur répond à l’adresse qu’il a vue, 198.51.100.7:40112. Le routeur la cherche dans sa table NAT, réécrit la destination en 192.168.1.10:52344 et transmet. La réponse est partie avec un TTL de 64 et arrive avec 52.","Delivered to":"Livrée à","TTL 52 · after NAT":"TTL 52 · après le NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (après le NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (après le NAT)","ARP request · 28 bytes":"Requête ARP · 28 octets","Broadcast: every device on the network receives it.":"Diffusion : tous les appareils du réseau la reçoivent.","The sender’s network card.":"La carte réseau de l’émetteur.","Hardware type":"Type de matériel","Protocol type":"Type de protocole","Address sizes":"Tailles d’adresse",Operation:"Opération","1 (request: who has …?)":"1 (requête : qui a … ?)","Sender MAC":"MAC de l’émetteur","Sender IP":"IP de l’émetteur","Target MAC":"MAC cible","All zeros: this is what the request wants to find out.":"Que des zéros : c’est ce que la requête veut découvrir.","Target IP":"IP cible","ARP reply · 28 bytes":"Réponse ARP · 28 octets","Straight back to the device that asked.":"Directement à l’appareil qui a demandé.","2 (reply: … is at …)":"2 (réponse : … est à …)","Seen as it leaves the router’s internet side":"Vu à la sortie, côté Internet du routeur","The internet provider’s router, the next hop.":"Le routeur du fournisseur d’accès, le prochain saut.","The router’s internet-facing port.":"Le port du routeur côté Internet.","As sent: this system starts at 64.":"Tel qu’envoyé : ce système démarre à 64.","The router’s NAT swapped in its own port for the laptop’s.":"Le NAT du routeur a mis son propre port à la place de celui de l’ordinateur.","The sender’s next router; each hop puts the packet in a new frame.":"Le routeur suivant de l’émetteur ; à chaque saut, le paquet est placé dans une nouvelle trame.","Name Resolution":"Résolution de noms",Query:"Requête",Referral:"Référence","DNSSEC not requested here":"DNSSEC non demandé ici","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"Le DNS transforme des noms comme www.example.com en adresses IP, celles qu’utilisent les ordinateurs pour se joindre. Aucun serveur ne connaît tous les noms : le système est une hiérarchie de serveurs, et les réponses sont mises en cache en chemin, si bien que la plupart des résolutions n’ont jamais à aller loin.","53, UDP (TCP if large)":"53, UDP (TCP si volumineux)",Turns:"Transforme","Names into IP addresses":"Les noms en adresses IP",Hierarchy:"Hiérarchie","Root → TLD → authoritative":"Racine → TLD → autorité",Caching:"Cache","For each record’s TTL":"Pendant le TTL de chaque enregistrement","Name resolved":"Nom résolu","And remembered for an hour":"Et mémorisé pendant une heure","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Partant d’un cache vide, le résolveur est allé de la racine à .com puis au serveur d’example.com, avant de répondre à l’ordinateur. Tant que le TTL n’est pas écoulé, la prochaine résolution de ce nom vient directement d’un cache. Appuyez sur REVOIR pour tout revoir.",Queries:"Requêtes","4 (laptop 1, resolver 3)":"4 (ordinateur 1, résolveur 3)","Cached for":"En cache pendant","Ask the Resolver":"Demander au résolveur","The laptop hands the question off":"L’ordinateur délègue la question","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Le navigateur a besoin de l’adresse IP de www.example.com, et ni lui ni Windows ne l’ont en cache. L’ordinateur envoie une seule question au résolveur récursif qui lui a été attribué, 8.8.8.8, et lui demande de faire toute la résolution (récursion souhaitée).","www.example.com, type A":"www.example.com, type A",Asked:"Demandé à","8.8.8.8 (recursive)":"8.8.8.8 (récursif)","RD (recursion desired)":"RD (récursion souhaitée)","flags: RD":"drapeaux : RD","Points the way to .com":"Indique le chemin vers .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"Le cache du résolveur est vide (il vient de démarrer), donc il commence par le sommet. Un serveur racine ne connaît pas l’adresse, mais il sait quels serveurs gèrent .com et répond par une référence. Beaucoup de résolveurs ne lui envoient que « com », pas le nom complet.","Root servers":"Serveurs racine","13 names, 1,000+ anycast sites":"13 noms, plus de 1,000 sites anycast","Referral (13 .com servers)":"Référence (13 serveurs .com)","no answer: ask .com":"pas de réponse : demandez à .com","Points the way to example.com":"Indique le chemin vers example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Le résolveur interroge un des serveurs .com. Eux non plus ne stockent pas l’adresse de chaque site, mais ils savent quels serveurs de noms utilise chaque domaine .com : cette réponse est donc une autre référence, avec les adresses de ces serveurs (glue) jointes.",Knows:"Connaît","Name servers of .com domains":"Les serveurs de noms des domaines .com","Referral + glue addresses":"Référence + adresses glue","no answer: ask example.com":"pas de réponse : demandez à example.com","Gives the actual answer":"Donne la vraie réponse","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Enfin, le résolveur interroge le serveur de noms d’example.com, qui détient les enregistrements du domaine. Il répond avec l’enregistrement A et marque la réponse comme faisant autorité. Le propriétaire du domaine fixe combien de temps elle peut rester en cache : ici, 3600 secondes.","AA (authoritative), TTL 3600":"AA (fait autorité), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · drapeau AA","Answer & Cache":"Réponse et cache","The laptop gets its address":"L’ordinateur obtient son adresse","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Le résolveur renvoie la réponse à l’ordinateur et en garde une copie. Pendant l’heure qui suit, il peut répondre aussitôt pour ce nom, ce qui explique pourquoi la résolution de la leçon HTTP n’a pris que 24 ms. L’ordinateur la met aussi en cache.","RD, RA (recursion available)":"RD, RA (récursion disponible)","Cached by":"En cache chez","Resolver and laptop":"Le résolveur et l’ordinateur","flags: RD RA":"drapeaux : RD RA","Referral: com. NS ×13 (with glue)":"Référence : com. NS ×13 (avec glue)","Referral: example.com. NS ×2 (with glue)":"Référence : example.com. NS ×2 (avec glue)","Response A 203.0.113.10 (authoritative)":"Réponse A 203.0.113.10 (fait autorité)","As sent: this system starts at 128.":"Tel qu’envoyé : ce système démarre à 128.","0x0000: query":"0x0000 : requête","UDP size 1232, DNSSEC OK = 0":"Taille UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Indique la taille maximale d’une réponse UDP. Les signatures DNSSEC ne sont pas demandées ici, pour garder la leçon courte ; un résolveur qui valide, comme 8.8.8.8, les demande.","0x8000: response":"0x8000 : réponse",Authority:"Autorité",Additional:"Additionnel","0x8400: response, AA (authoritative)":"0x8400 : réponse, AA (fait autorité)","Getting an Address":"Obtenir une adresse","From the laptop":"Depuis l’ordinateur","From the DHCP server":"Depuis le serveur DHCP","Dynamic Host Configuration Protocol":"Protocole de configuration dynamique des hôtes","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP donne à un appareil tout ce qu’il lui faut pour utiliser un réseau : une adresse IP, le masque de sous-réseau, le routeur par lequel faire passer le trafic et les serveurs DNS à interroger. Les adresses sont attribuées par bail pour une durée fixe et renouvelées tant que l’appareil reste sur le réseau.","UDP 67 (server), 68 (client)":"UDP 67 (serveur), 68 (client)","Hands out":"Distribue","IP, mask, gateway, DNS":"IP, masque, passerelle, DNS",Exchange:"Échange",Lease:"Bail","Renewed at half its time":"Renouvelé à mi-parcours","On the network":"Sur le réseau","Leased, and kept up to date":"Bail obtenu, et tenu à jour","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Quatre messages ont fait passer l’ordinateur d’aucune adresse à une configuration complète, et à la moitié du bail de 24 heures, il l’a renouvelé par une demande directe au routeur. Appuyez sur REVOIR pour tout revoir.",Messages:"Messages","4 to join, 2 per renewal":"4 pour rejoindre, 2 par renouvellement","24 h, renewed at 12 h":"24 h, renouvelé à 12 h","No Address Yet":"Pas encore d’adresse","The laptop joins the network":"L’ordinateur rejoint le réseau","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"L’ordinateur vient de se connecter. Il a une adresse MAC intégrée, mais ni adresse IP, ni passerelle, ni serveur DNS, donc il ne peut encore parler à rien au-delà de son propre réseau. Il les demande avec DHCP.","IP address":"Adresse IP","None (uses 0.0.0.0)":"Aucune (utilise 0.0.0.0)","MAC address":"Adresse MAC",Needs:"A besoin de",Discover:"Découverte","Shout to the whole network":"Crier à tout le réseau","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Sans adresse à lui, l’ordinateur envoie depuis 0.0.0.0 vers l’adresse de diffusion 255.255.255.255, si bien que tous les appareils du réseau local la reçoivent. Seuls les serveurs DHCP répondent.",From:"De","0.0.0.0, UDP port 68":"0.0.0.0, port UDP 68","255.255.255.255, port 67":"255.255.255.255, port 67",Carries:"Transporte","MAC, transaction ID":"MAC, ID de transaction","any DHCP server out there?":"un serveur DHCP dans le coin ?",Offer:"Offre","The router proposes an address":"Le routeur propose une adresse","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"Le serveur DHCP du routeur choisit une adresse libre et la propose avec le reste des réglages. L’ordinateur ne peut pas encore utiliser d’adresse IP, donc l’offre va directement à son adresse MAC (certains clients demandent plutôt une diffusion).",Offered:"Proposée","Gateway, DNS":"Passerelle, DNS","offer: 192.168.1.10/24":"offre : 192.168.1.10/24","gateway, DNS, lease 24 h":"passerelle, DNS, bail de 24 h","Accept, out loud":"Accepter, à voix haute","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"L’ordinateur demande l’adresse proposée, en nommant le serveur qu’il a choisi. Il diffuse encore, si bien que tout autre serveur DHCP ayant fait une offre apprend qu’il n’a pas été retenu et peut libérer son adresse.",Requests:"Demande","Chosen server":"Serveur choisi","I’ll take 192.168.1.10":"Je prends 192.168.1.10","from server 192.168.1.1":"du serveur 192.168.1.1",Acknowledge:"Accusé de réception","The address is the laptop’s":"L’adresse est à l’ordinateur","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Le serveur confirme, et l’ordinateur configure son adresse, son masque, sa passerelle et son serveur DNS. Beaucoup de systèmes vérifient d’abord avec ARP qu’aucun autre appareil n’utilise déjà l’adresse.","DNS server":"Serveur DNS","192.168.1.10 is yours":"192.168.1.10 est à vous","for 24 hours":"pour 24 heures",Renew:"Renouvellement","Halfway through the lease":"À la moitié du bail","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Douze heures plus tard, la moitié du bail est écoulée. L’ordinateur a maintenant une adresse, il demande donc directement au routeur de prolonger le bail, et le routeur le remet à 24 heures. Sans réponse du routeur, il diffuserait à 87.5 %.",When:"Quand","50% of lease (T1 = 12 h)":"50 % du bail (T1 = 12 h)","The router (unicast)":"Le routeur (unicast)","If unanswered":"Sans réponse","Broadcast at 87.5% (T2)":"Diffusion à 87.5 % (T2)","renew 192.168.1.10":"renouveler 192.168.1.10","sent straight to 192.168.1.1":"envoyé directement à 192.168.1.1","lease renewed":"bail renouvelé","another 24 hours":"24 heures de plus",Message:"Message","1 (request, from a client)":"1 (requête, d’un client)",Hardware:"Matériel","Ethernet, 6-byte addresses":"Ethernet, adresses de 6 octets",Hops:"Sauts","Chosen by the client; every reply repeats it.":"Choisi par le client ; chaque réponse le répète.",Seconds:"Secondes","0x0000 (unicast replies are fine)":"0x0000 (les réponses unicast conviennent)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Drapeau de diffusion désactivé : le serveur peut envoyer directement à l’adresse MAC du client.","Client address":"Adresse du client","Filled in only when the client already has an address (renewing).":"Rempli seulement quand le client a déjà une adresse (renouvellement).","Your address":"Votre adresse","The address the server is giving out.":"L’adresse que le serveur attribue.","Next server":"Serveur suivant","Relay agent":"Agent relais","Client MAC":"MAC du client","Server name, boot file":"Nom du serveur, fichier de démarrage",empty:"vide","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Indique que les options qui suivent sont du DHCP.","Message type: 1 (Discover)":"Type de message : 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Identifiant client : 01 00:00:5e:00:53:10","Host name: alice-laptop":"Nom d’hôte : alice-laptop","Vendor class: MSFT 5.0":"Classe du fabricant : MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Paramètres voulus : 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (réponse, d’un serveur)","Message type: 2 (Offer)":"Type de message : 2 (Offer)","Server identifier: 192.168.1.1":"Identifiant du serveur : 192.168.1.1","Lease time: 86,400 s (24 h)":"Durée du bail : 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"Délai de renouvellement (T1) : 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"Délai de réassociation (T2) : 75,600 s (21 h)","Subnet mask: 255.255.255.0":"Masque de sous-réseau : 255.255.255.0","Broadcast address: 192.168.1.255":"Adresse de diffusion : 192.168.1.255","DNS server: 8.8.8.8":"Serveur DNS : 8.8.8.8","Message type: 3 (Request)":"Type de message : 3 (Request)","Requested address: 192.168.1.10":"Adresse demandée : 192.168.1.10","Client FQDN: alice-laptop":"FQDN du client : alice-laptop","Message type: 5 (ACK)":"Type de message : 5 (ACK)","Network Diagnostics":"Diagnostic réseau","Ping / probe":"Ping / sonde","Echo reply":"Réponse d’écho","Error report":"Rapport d’erreur","Internet Control Message Protocol":"Protocole de messages de contrôle d’Internet","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP est la façon dont le réseau fait remonter des informations : un routeur signale que le temps d’un paquet est écoulé, un serveur signale que rien n’écoute sur un port. Des outils comme ping et traceroute reposent sur ces messages. Il voyage dans IP mais ne transporte aucune donnée d’application.","Carried in":"Transporté dans","IP (protocol 1)":"IP (protocole 1)","A type and a code":"Un type et un code",Tools:"Outils",Often:"Souvent","Filtered by firewalls":"Filtré par les pare-feu","The network answered":"Le réseau a répondu","Replies, expiries and errors":"Réponses, expirations et erreurs","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Une requête d’écho a mesuré l’aller-retour, des paquets à petit TTL ont poussé chaque routeur du chemin à se signaler, et un port fermé a été signalé aussitôt. Appuyez sur REVOIR pour tout revoir.","Round trip":"Aller-retour",Path:"Chemin","12 routers, server at hop 13":"12 routeurs, serveur au saut 13","Types used":"Types utilisés","8, 0, 11 and 3":"8, 0, 11 et 3","Reply TTL":"TTL de la réponse",Ping:"Ping","Echo request":"Requête d’écho","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"« ping -n 1 203.0.113.10 » envoie une requête d’écho ICMP (un ping simple en envoie quatre, à une seconde d’intervalle) : type 8, code 0, avec un identifiant, un numéro de séquence et 32 octets de remplissage. Le système du serveur répond tout seul, sans application.","Type, code":"Type, code","8, 0 (echo request)":"8, 0 (requête d’écho)","type 8 · seq 1":"type 8 · séq. 1","32 bytes of data":"32 octets de données","Echo Reply":"Réponse d’écho","Round-trip time":"Temps aller-retour","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Le serveur renvoie une réponse d’écho, type 0, avec le même identifiant, le même numéro de séquence et les mêmes données. Ping affiche le temps écoulé et le TTL avec lequel la réponse est arrivée : « octets=32 temps=34 ms TTL=52 ».","0, 0 (echo reply)":"0, 0 (réponse d’écho)","TTL on arrival":"TTL à l’arrivée","type 0 · seq 1":"type 0 · séq. 1","same 32 bytes back":"les mêmes 32 octets en retour","The first router answers":"Le premier routeur répond","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"« ping -n 1 -i 1 » envoie la même requête avec un TTL de 1. Le routeur de la maison l’abaisse à 0 : il doit donc jeter le paquet, et il renvoie un message « temps dépassé » (Time Exceeded) depuis sa propre adresse : « Réponse de 192.168.1.1 : TTL expiré lors du transit. »","Sent with":"Envoyé avec","Dropped by":"Jeté par","11, 0 (time exceeded)":"11, 0 (temps dépassé)","echo request":"requête d’écho","expires at the first router":"expire au premier routeur","type 11 · from 192.168.1.1":"type 11 · de 192.168.1.1","quotes the dropped header":"cite l’en-tête jeté","The next router answers":"Le routeur suivant répond","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Avec « -i 2 », le routeur de la maison abaisse le TTL à 1 et transmet. Le premier routeur du fournisseur d’accès l’abaisse à 0 et le signale depuis 198.51.100.1. Le routeur de la maison retraduit ce rapport pour l’ordinateur comme n’importe quelle réponse.","ISP router 198.51.100.1":"Routeur du FAI 198.51.100.1","expires at the second router":"expire au deuxième routeur","type 11 · from 198.51.100.1":"type 11 · de 198.51.100.1","That’s Traceroute":"C’est ça, traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … jusqu’à l’arrivée","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert automatise cela : il augmente le TTL de un à chaque fois, envoie trois sondes par saut et liste qui répond. Les sauts 3 à 12 fonctionnent de la même façon, et avec un TTL de 13, la requête atteint enfin le serveur, qui répond normalement.","12 routers, then the server":"12 routeurs, puis le serveur","Per hop":"Par saut","3 probes":"3 sondes","On Linux":"Sous Linux","traceroute sends UDP":"traceroute envoie de l’UDP","enough hops to arrive":"assez de sauts pour arriver","the server itself answers":"le serveur lui-même répond","end of the route":"fin de la route",Unreachable:"Injoignable","Nothing listening on that port":"Rien n’écoute sur ce port","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Une appli envoie un datagramme UDP au port 9999, où rien n’écoute. Le serveur ne peut pas le livrer, il répond donc par « destination injoignable », code 3 (port injoignable), en citant le début du datagramme. Beaucoup de pare-feu jettent plutôt ce genre de paquets sans rien dire.","3, 3 (port unreachable)":"3, 3 (port injoignable)","Other codes":"Autres codes","0 net, 1 host, 4 too big":"0 réseau, 1 hôte, 4 trop gros",Firewalls:"Pare-feu","Often silent instead":"Souvent muets à la place","to port 9999":"vers le port 9999","nothing listening there":"rien n’y écoute","type 3 · code 3":"type 3 · code 3","port unreachable":"port injoignable","ICMP · Echo request":"ICMP · Requête d’écho",Code:"Code","Covers the whole ICMP message.":"Couvre tout le message ICMP.",Identifier:"Identifiant","Matches replies to this ping program.":"Associe les réponses à ce programme ping.","Windows counts up across every ping it sends.":"Windows incrémente ce compteur sur tous les pings qu’il envoie.","Windows ping’s filler: the alphabet, a to w, then again.":"Le remplissage du ping de Windows : l’alphabet, de a à w, puis à nouveau.","ICMP · Echo reply":"ICMP · Réponse d’écho","Sent back exactly as it came.":"Renvoyé exactement tel qu’il est arrivé.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Temps dépassé (TTL arrivé à 0)","Time exceeded (TTL reached 0)":"Temps dépassé (TTL arrivé à 0)",Unused:"Inutilisé","Original packet":"Paquet d’origine","Its source, destination":"Sa source, sa destination","its IP header and first 8 bytes (28 bytes)":"son en-tête IP et ses 8 premiers octets (28 octets)","App data":"Données de l’appli","What the app sent; nothing on the server is listening for it.":"Ce que l’appli a envoyé ; rien sur le serveur ne l’attend.","ICMP · Destination unreachable (port unreachable)":"ICMP · Destination injoignable (port injoignable)","Destination unreachable (port unreachable)":"Destination injoignable (port injoignable)","Sending Email":"Envoyer un e-mail","SMTP command":"Commande SMTP","SMTP reply":"Réponse SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP achemine les e-mails : de votre appli de messagerie au serveur de votre fournisseur, puis de ce serveur à celui du destinataire. C’est une conversation de courtes commandes texte, chacune suivie d’un code de réponse à trois chiffres. Lire ses e-mails est une autre affaire, réglée par IMAP ou POP3.","465/587 submit, 25 relay":"465/587 envoi, 25 relais","TCP, usually with TLS":"TCP, généralement avec TLS",Commands:"Commandes",Replies:"Réponses","2xx ok, 3xx go on, 4/5xx error":"2xx OK, 3xx continuer, 4/5xx erreur","Mail delivered":"E-mail livré","Two hops, one message":"Deux étapes, un message","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"L’appli d’Alice a remis le message à son fournisseur par une connexion chiffrée et authentifiée. Le fournisseur a trouvé le serveur de messagerie de Bob dans le DNS et l’y a relayé, en passant ce lien en TLS. Le message attend maintenant dans la boîte de Bob jusqu’à ce qu’il le lise avec IMAP ou POP3.","Laptop → provider → Bob’s":"Ordinateur → fournisseur → Bob",Submission:"Envoi","Port 465, TLS, login":"Port 465, TLS, connexion",Relay:"Relais","Port 25, STARTTLS":"Port 25, STARTTLS","Checks at Bob’s":"Vérifications chez Bob","Connect Securely":"Se connecter en sécurité","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice appuie sur Envoyer. Son appli de messagerie se connecte au serveur d’envoi de son fournisseur, smtp.example.com, sur le port 465. Sur ce port, TLS démarre immédiatement : toute la conversation SMTP, mot de passe compris, est donc chiffrée.","TLS from the start":"TLS dès le départ","SMTP inside TLS":"SMTP dans TLS","Greeting & Login":"Accueil et connexion","EHLO, then AUTH":"EHLO, puis AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Le serveur salue avec le code 220. L’appli dit EHLO et le serveur liste ce qu’il prend en charge, dont AUTH. L’appli se connecte avec AUTH PLAIN (nom d’utilisateur et mot de passe, encodés en base64) et reçoit 235 : authentifiée.",Greeting:"Accueil",Capabilities:"Capacités","Login result":"Résultat de la connexion","user and password, base64":"utilisateur et mot de passe, en base64","Send the Message":"Envoyer le message","Envelope, then content":"L’enveloppe, puis le contenu","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM et RCPT TO forment l’enveloppe : expéditeur et destinataire. PIPELINING permet aux trois commandes de partager un seul paquet. Après le 354 vient le message, terminé par une ligne ne contenant qu’un point.",Envelope:"Enveloppe","Content ends":"Fin du contenu","A line with only “.”":"Une ligne avec seulement « . »",Result:"Résultat","… message …":"… message …","Find Bob’s Server":"Trouver le serveur de Bob","An MX lookup in DNS":"Une recherche MX dans le DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Le fournisseur d’Alice doit maintenant livrer à example.org. Il demande au DNS l’enregistrement MX de ce domaine, qui nomme le serveur acceptant son courrier, puis cherche l’adresse de ce serveur.","MX record":"Enregistrement MX","Asked by":"Demandé par","Alice’s provider":"Le fournisseur d’Alice","Server to Server":"De serveur à serveur","Port 25, upgraded with STARTTLS":"Port 25, sécurisé avec STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Le fournisseur se connecte à mx.example.org sur le port 25. Cette conversation commence en clair : l’accueil et la réponse à EHLO annoncent STARTTLS, le fournisseur le demande, reçoit 220, et les deux côtés passent en TLS.","Starts as":"Commence en","Plain text":"Texte en clair",Upgrade:"Passage en TLS",Deliver:"Livrer","The same transaction again":"La même transaction, à nouveau","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Une fois TLS actif, le fournisseur répète EHLO, puis l’enveloppe et le message, désormais avec une signature DKIM et un en-tête Received ajoutés. Le serveur de Bob vérifie SPF, DKIM et DMARC et l’accepte.","Login needed":"Connexion requise","No (server to server)":"Non (de serveur à serveur)","1,316 bytes (signed)":"1,316 octets (signé)","Server Hello + encrypted handshake, 2 segments":"Server Hello + poignée de main chiffrée, 2 segments","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 capacités (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (identifiants)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (en pipeline)","Message (316 bytes), then “.”":"Message (316 octets), puis « . »","250 capabilities (PIPELINING, STARTTLS …)":"250 capacités (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 capacités (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Message (1,316 octets), puis « . »","What this client supports. Its exact contents vary from client to client; this is an example.":"Ce que ce client prend en charge. Le contenu exact varie d’un client à l’autre ; ceci est un exemple.","up to 512 bytes":"jusqu’à 512 octets","The server’s choices and its key share.":"Les choix du serveur et sa part de clé.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (la chaîne), Certificate Verify (la signature), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Le message d’Alice (316 octets), puis une ligne ne contenant que « . »","example.org, type MX, class IN":"example.org, type MX, classe IN","mx.example.org, type A, class IN":"mx.example.org, type A, classe IN",Timestamps:"Horodatages","Used to measure round trips; both sides offered them.":"Servent à mesurer les allers-retours ; les deux côtés les ont proposés.","The signed message (1,316 bytes), then a line holding only “.”":"Le message signé (1,316 octets), puis une ligne ne contenant que « . »","Downloading Email":"Relever ses e-mails","POP3 command":"Commande POP3","POP3 reply":"Réponse POP3","Post Office Protocol, version 3":"Protocole de bureau de poste, version 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"POP3 permet à une appli de messagerie de télécharger les messages d’une boîte aux lettres sur un serveur. Il a été conçu pour un seul appareil qui récupère le courrier puis le supprime du serveur. Les commandes sont des mots courts, et chaque réponse commence par +OK ou -ERR.",Model:"Modèle","Download, then delete":"Télécharger, puis supprimer","Mail downloaded":"Courrier téléchargé","And gone from the server":"Et disparu du serveur","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"L’appli de Bob s’est connectée, a vu deux messages, a téléchargé le premier puis l’a supprimé, ce que le serveur a exécuté au QUIT. Ce message n’existe plus que sur cet ordinateur : voilà pourquoi POP3 convient à un seul appareil et IMAP à plusieurs.","2 waiting, 1 downloaded":"2 en attente, 1 téléchargé",Deleted:"Supprimé","At QUIT (UPDATE state)":"Au QUIT (état UPDATE)","Best for":"Idéal pour","A single device":"Un seul appareil","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"L’appli de messagerie de Bob se connecte à pop.example.org sur le port 995, où TLS démarre tout de suite. À l’intérieur, le serveur salue avec +OK. (Sur le port 110, la session commence en clair et passe en TLS avec la commande STLS.)","USER, then PASS":"USER, puis PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"L’appli envoie le nom d’utilisateur avec USER et le mot de passe avec PASS. Chaque commande reçoit son propre +OK. Comme la session est dans TLS, le mot de passe n’est pas lisible en chemin.","Protected by":"Protégé par","Check the Mailbox":"Consulter la boîte","STAT and LIST":"STAT et LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT renvoie le nombre de messages et leur taille totale : 2 messages, 5120 octets. LIST donne le numéro et la taille de chaque message, et se termine par une ligne ne contenant qu’un point.","Message 1":"Message 1","Message 2":"Message 2",Download:"Télécharger","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 demande le premier message. Le serveur répond +OK avec sa taille, puis le message et un point final : 1904 octets plus la ligne de réponse, deux segments TCP.",Command:"Commande","Delete & Quit":"Supprimer et quitter","Deleted only at QUIT":"Supprimé seulement au QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 ne fait que marquer le message. Le serveur le supprime quand l’appli dit QUIT : si la connexion tombait avant, rien ne serait supprimé. Beaucoup d’applis proposent « laisser une copie sur le serveur », ce qui saute DELE.","Marks message 1":"Marque le message 1",Removed:"Supprimé",Option:"Option","Leave a copy on server":"Laisser une copie sur le serveur","PASS (password)":"PASS (mot de passe)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, message, « . » (2 segments)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, le message de 1,904 octets, puis une ligne ne contenant que « . »","IMAP command":"Commande IMAP","IMAP response":"Réponse IMAP","Internet Message Access Protocol":"Protocole d’accès aux messages Internet","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"IMAP permet aux applis de messagerie de travailler sur une boîte aux lettres qui reste sur le serveur. Les dossiers, les marques lu et suivi et les suppressions y sont conservés : un téléphone, un ordinateur et le webmail voient donc la même boîte. Le serveur peut aussi prévenir une appli de l’arrivée d’un nouveau courrier.","Mail stays on the server":"Le courrier reste sur le serveur",Syncs:"Synchronise","Folders and flags":"Dossiers et indicateurs","Mailbox in sync":"Boîte synchronisée","Read once, read everywhere":"Lu une fois, lu partout","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"L’appli de Bob a ouvert sa boîte de réception et lu un message, ce qui l’a marqué \\Seen sur le serveur pour tous ses appareils, puis elle a attendu avec IDLE que le serveur annonce un nouveau courrier. Rien n’a été supprimé : le serveur garde tout.","2, then 3 (new mail)":"2, puis 3 (nouveau courrier)","Read mark":"Marque de lecture","\\Seen, stored on server":"\\Seen, stocké sur le serveur","New mail":"Nouveau courrier","Pushed during IDLE":"Poussé pendant IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"L’appli de Bob se connecte à imap.example.org sur le port 993, où TLS démarre tout de suite. Le serveur salue avec une ligne « * OK » sans étiquette, qui liste aussi ses capacités, comme IDLE.","Commands carry tags":"Les commandes portent des étiquettes","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Chaque commande commence par une étiquette choisie par l’appli, comme a1, et le serveur termine sa réponse par la même étiquette. Ainsi, plusieurs commandes peuvent être en cours et chaque réponse est associée à la bonne. Les lignes commençant par * sont des données sans étiquette.",Tags:"Étiquettes","Match replies to commands":"Associer réponses et commandes","Open the Inbox":"Ouvrir la boîte de réception","SELECT a folder":"SELECT sur un dossier","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX ouvre le dossier. Le serveur indique le nombre de messages, les indicateurs qu’il gère et le premier message non lu, puis confirme que le dossier est ouvert en lecture-écriture.","First unread":"Premier non lu",Access:"Accès","Read a Message":"Lire un message","FETCH, and the \\Seen flag":"FETCH, et l’indicateur \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] télécharge le message 2 (trois segments TCP). Cela active son indicateur \\Seen sur le serveur, il apparaît donc comme lu sur le téléphone de Bob aussi, et le message y reste.","Flag set":"Indicateur activé","\\Seen (on the server)":"\\Seen (sur le serveur)","Wait for New Mail":"Attendre un nouveau courrier","IDLE: the server pushes":"IDLE : le serveur pousse","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE dit au serveur « préviens-moi quand quelque chose change ». Environ 42 secondes plus tard, le message d’Alice arrive et le serveur pousse aussitôt « * 3 EXISTS ». L’appli met fin à IDLE avec DONE et peut récupérer le nouveau courrier.","Server says":"Le serveur dit","* 3 EXISTS (new mail)":"* 3 EXISTS (nouveau courrier)","Ended by":"Terminé par","a1 LOGIN (user and password)":"a1 LOGIN (utilisateur et mot de passe)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, le message de 3,216 octets, puis a3 OK FETCH completed","Transferring Files":"Transfert de fichiers","FTP command":"Commande FTP","FTP reply":"Réponse FTP","File data":"Données du fichier","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP transfère des fichiers entre un client et un serveur. Il a la particularité d’utiliser deux connexions TCP : une pour les commandes et les réponses, et une nouvelle pour chaque fichier ou listing. Il date du début des années 1970 et envoie tout en clair, mots de passe compris.","21 control, data varies":"21 contrôle, données variables",Connections:"Connexions","Control + one per transfer":"Contrôle + une par transfert",Encryption:"Chiffrement","None (plain text)":"Aucun (texte en clair)","Safer options":"Options plus sûres","File downloaded":"Fichier téléchargé","Two connections, no encryption":"Deux connexions, aucun chiffrement","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Les commandes sont passées par la connexion de contrôle, le fichier par sa propre connexion de données, et la fermeture de celle-ci a marqué la fin du fichier. N’importe qui sur le chemin aurait pu lire le mot de passe et le fichier : voilà pourquoi on utilise aujourd’hui SFTP ou FTPS.","2 (control + data)":"2 (contrôle + données)",File:"Fichier","4,000 bytes, 3 segments":"4,000 octets, 3 segments",Password:"Mot de passe","Sent in plain text":"Envoyé en clair","Use instead":"Utiliser plutôt","Control Connection":"Connexion de contrôle","Port 21, plain text":"Port 21, texte en clair","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"L’appli FTP ouvre une connexion TCP vers ftp.example.com sur le port 21. Cette connexion de contrôle transporte les commandes et les réponses de toute la session. Le serveur salue avec 220. Comme pour SMTP, chaque réponse commence par un code à trois chiffres.","USER and PASS, readable by anyone":"USER et PASS, lisibles par tous","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"L’appli envoie USER, le serveur demande le mot de passe avec 331, et PASS l’envoie. Rien n’est chiffré : le nom d’utilisateur et le mot de passe traversent tous les réseaux du chemin en texte lisible.","Visible to":"Visible par","Anyone on the path":"N’importe qui sur le chemin","Passive Mode":"Mode passif","The server names a data port":"Le serveur indique un port de données","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I demande une copie binaire octet par octet. PASV demande au serveur d’ouvrir un port pour la connexion de données. La réponse code l’adresse et le port en six nombres : 195 × 256 + 149 = port 50069. L’ordinateur se connecte vers l’extérieur, ce qui passe à travers le NAT.","Data port":"Port de données","Active mode":"Mode actif","Server dials in: NAT blocks":"Le serveur rappelle : le NAT bloque","Data Connection":"Connexion de données","A second TCP connection":"Une seconde connexion TCP","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"L’appli ouvre une seconde connexion TCP, vers le port 50069, et demande le fichier sur la connexion de contrôle avec RETR. Le serveur y répond 150 et commence à envoyer le fichier sur la nouvelle connexion.","Data to":"Données vers","The File Arrives":"Le fichier arrive","Closing the connection ends it":"Fermer la connexion marque la fin","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"Les 4,000 octets arrivent en 3 segments TCP. FTP n’envoie aucune indication de longueur dans les données elles-mêmes : le serveur ferme la connexion de données pour marquer la fin du fichier. Une fois que l’ordinateur a tout acquitté, le serveur confirme avec 226 sur la connexion de contrôle.","End of file":"Fin du fichier","Data connection closed":"Connexion de données fermée","4,000 bytes, readable by anyone":"4,000 octets, lisibles par tous","end of file:":"fin du fichier :","data connection closed":"connexion de données fermée",Quit:"Quitter","Close the control connection":"Fermer la connexion de contrôle","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT met fin à la session et le serveur dit au revoir avec 221. Pour tout ce qui est sensible, SFTP (un autre protocole, qui passe par SSH) ou FTPS (FTP dans TLS) font le même travail avec chiffrement.","Encrypted cousins":"Cousins chiffrés","FTP data":"Données FTP","The file itself, unencrypted: anyone on the path could read it.":"Le fichier lui-même, non chiffré : n’importe qui sur le chemin pourrait le lire.","Secure Remote Login":"Accès distant sécurisé","Plain setup":"Mise en place en clair","From laptop":"Depuis l’ordinateur","From server":"Depuis le serveur","Some packets not shown":"Certains paquets ne sont pas montrés","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH vous donne une connexion chiffrée et authentifiée vers un autre ordinateur, pour y exécuter des commandes, copier des fichiers (SFTP, scp) ou transporter d’autres connexions. Le serveur prouve son identité avec une clé d’hôte ; vous prouvez la vôtre avec une paire de clés ou un mot de passe.","Server proves":"Le serveur prouve","Host key (known_hosts)":"Clé d’hôte (known_hosts)","You prove":"Vous prouvez","Key pair or password":"Paire de clés ou mot de passe","Logged in securely":"Connecté en sécurité","Encrypted from the key exchange on":"Chiffré dès l’échange de clés","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"Les deux côtés se sont mis d’accord sur les algorithmes, ont construit des clés communes avec un échange hybride post-quantique, et le serveur a prouvé son identité avec sa clé d’hôte. Alice a prouvé la sienne en signant avec une clé privée qui n’a jamais quitté l’ordinateur, puis a tapé une commande, un paquet par touche.",Login:"Connexion","Ed25519 key, no password":"Clé Ed25519, sans mot de passe","Say Hello":"Dire bonjour","Versions, in plain text":"Les versions, en clair","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice lance « ssh alice@server.example.com ». Après la poignée de main TCP sur le port 22, chaque côté envoie une ligne de texte en clair indiquant la version du protocole SSH (2.0) et son logiciel. Tout le reste de SSH est binaire.","Agree on Algorithms":"Négocier les algorithmes","KEXINIT lists, first match wins":"Listes KEXINIT, la première correspondance l’emporte","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Chaque côté envoie un KEXINIT listant tous les algorithmes qu’il prend en charge, par ordre de préférence, pour l’échange de clés, les clés d’hôte, le chiffrement, l’intégrité et la compression. Dans chaque catégorie, on choisit le premier algorithme de la liste de l’ordinateur que le serveur prend aussi en charge.","Host key":"Clé d’hôte","server’s algorithm lists":"listes d’algorithmes du serveur","in order of preference":"par ordre de préférence","laptop’s algorithm lists":"listes d’algorithmes de l’ordinateur","Key Exchange":"Échange de clés","Shared keys, and a host key check":"Des clés communes, et une vérification de la clé d’hôte","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"L’ordinateur envoie sa moitié d’un échange hybride : une clé Streamlined NTRU Prime, choisie pour résister aux futurs ordinateurs quantiques, plus une clé X25519. Le serveur répond avec sa moitié, sa clé d’hôte et une signature sur l’échange. NEWKEYS active le chiffrement.",Hybrid:"Hybride","Matches known_hosts":"Correspond à known_hosts","First visit":"Première visite","ssh asks you to confirm":"ssh vous demande de confirmer","public keys":"clés publiques","its half, its host key":"sa moitié, sa clé d’hôte","and a signature":"et une signature","Log In with a Key":"Se connecter avec une clé","Sign, don’t send a secret":"Signer, sans envoyer de secret","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Le serveur liste les méthodes de connexion qu’il accepte. L’ordinateur propose la clé publique d’Alice, et le serveur répond qu’il l’accepterait. L’ordinateur signe alors cette session avec la clé privée, qui ne quitte jamais l’ordinateur. Le serveur vérifie la signature grâce à authorized_keys.",Methods:"Méthodes","Ed25519, private stays here":"Ed25519, la privée reste ici","Checked with":"Vérifiée avec","alice’s public key":"clé publique d’alice","would you accept it?":"l’accepteriez-vous ?","yes, that key":"oui, cette clé","is in authorized_keys":"est dans authorized_keys","same key, plus a signature":"la même clé, plus une signature","made with the private key":"faite avec la clé privée","logged in":"connexion réussie","Open a Session":"Ouvrir une session","Channels inside one connection":"Des canaux dans une seule connexion","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Une connexion SSH peut transporter de nombreux canaux : un shell, des transferts de fichiers, des ports redirigés. L’ordinateur ouvre un canal de session, puis demande un terminal et un shell (non montrés), et le serveur envoie son texte d’accueil et une invite.",Channel:"Canal",session:"session","Then asks for":"Puis demande","A terminal and a shell":"Un terminal et un shell","Also possible":"Aussi possible","SFTP, port forwarding":"SFTP, redirection de ports","open a channel:":"ouvrir un canal :","channel open":"canal ouvert","Type a Command":"Taper une commande","Every key is a packet":"Chaque touche est un paquet","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice tape pwd. Chaque touche part aussitôt dans son propre paquet chiffré, et le serveur renvoie le caractère pour l’afficher (l’écho). Depuis la version 9.5, OpenSSH envoie les touches sur un rythme de 20 ms et ajoute des paquets leurres, pour que le rythme de frappe soit plus difficile à deviner d’après le minutage.","Per key":"Par touche","1 packet, 90 bytes":"1 paquet, 90 octets",Echo:"Écho","Sent back by the server":"Renvoyé par le serveur",Timing:"Minutage","20 ms beat plus decoys":"Rythme de 20 ms plus des leurres","Enter key":"Touche Entrée","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Client: KEX_ECDH_INIT (clés publiques sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Server: KEX_ECDH_REPLY (clé d’hôte, sa moitié, signature)","Encrypted (len=44): service request, ssh-userauth":"Chiffré (len=44) : demande de service, ssh-userauth","Encrypted (len=44): service accept":"Chiffré (len=44) : service accepté","Encrypted (len=68): login with method none":"Chiffré (len=68) : connexion avec la méthode none","Encrypted (len=52): try publickey,password":"Chiffré (len=52) : essayez publickey,password","Encrypted (len=140): offer public key":"Chiffré (len=140) : propose une clé publique","Encrypted (len=100): public key OK":"Chiffré (len=100) : clé publique OK","Encrypted (len=308): public key + signature":"Chiffré (len=308) : clé publique + signature","Encrypted (len=28): login success":"Chiffré (len=28) : connexion réussie","Encrypted (len=52): channel open: session":"Chiffré (len=52) : ouverture de canal : session","Encrypted (len=44): channel open confirmed":"Chiffré (len=44) : ouverture du canal confirmée","Encrypted (len=36): keystroke":"Chiffré (len=36) : frappe","Encrypted (len=36): echo":"Chiffré (len=36) : écho","Encrypted (len=36): keystroke (Enter)":"Chiffré (len=36) : frappe (Entrée)","Encrypted (len=132): output and a new prompt":"Chiffré (len=132) : sortie et nouvelle invite","Packet length":"Longueur du paquet","Bytes after this field.":"Octets après ce champ.","Padding length":"Longueur du bourrage","Random padding brings the packet to a multiple of 8 bytes.":"Un bourrage aléatoire porte le paquet à un multiple de 8 octets.",Cookie:"Cookie","Host keys":"Clés d’hôte","Ciphers, out":"Chiffrements, sortie","Ciphers, in":"Chiffrements, entrée","MACs, out":"MAC, sortie","Compression, out":"Compression, sortie","Compression, in":"Compression, entrée","Languages, out":"Langues, sortie","Languages, in":"Langues, entrée","First packet follows":"Le premier paquet suit",Reserved:"Réservé","Public keys":"Clés publiques","51 bytes: ssh-ed25519 public key":"51 octets : clé publique ssh-ed25519","Server’s half":"Moitié du serveur","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 octets (texte chiffré sntrup761 1,039 + X25519 32)",Signature:"Signature","83 bytes: ssh-ed25519 signature over the exchange":"83 octets : signature ssh-ed25519 sur l’échange","From the next packet on, this side encrypts.":"À partir du paquet suivant, ce côté chiffre.","SSH · encrypted packet":"SSH · paquet chiffré","Encrypted packet":"Paquet chiffré","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Avec chacha20-poly1305, même la longueur est chiffrée ; une étiquette de 16 octets à la fin révèle toute modification.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50) : utilisateur « alice », service « ssh-connection », méthode « none »","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51) : méthodes pouvant continuer : « publickey,password »","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50) : méthode « publickey », sans signature, la clé publique ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60) : la même clé ssh-ed25519","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50) : méthode « publickey-hostbound-v00@openssh.com », la clé, la clé d’hôte du serveur et une signature","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90) : « session », canal 0, fenêtre de 2 Mo, paquets jusqu’à 32 Ko","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91) : le canal 0 est ouvert","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « p »","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « p », renvoyé pour être affiché","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « w »","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « w », renvoyé pour être affiché","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « d »","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « d », renvoyé pour être affiché","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, un retour chariot (Entrée)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 94 octets : un saut de ligne, les codes de terminal du shell, « /home/alice » et l’invite en couleur","From browser":"Depuis le navigateur","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS installe un canal sécurisé au-dessus de TCP. Il prouve l’identité du serveur avec un certificat, convient de clés neuves, puis chiffre et authentifie tout ce qui est envoyé. HTTPS, l’e-mail sécurisé et bien d’autres protocoles fonctionnent à l’intérieur. SSL était le nom de son prédécesseur.",Sits:"Se situe","Between TCP and the app":"Entre TCP et l’appli","OSI layer":"Couche OSI","Often placed at 6":"Souvent placé en 6",Current:"Actuelle",Retired:"Retirées","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 et 3, TLS 1.0 et 1.1","The app’s own (443, 993 …)":"Celui de l’appli (443, 993 …)","Secure from start to finish":"Sécurisé de bout en bout","One round trip to set up":"Un aller-retour pour l’établir","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Un seul aller-retour a suffi pour convenir d’une version, d’un chiffrement et d’une clé hybride post-quantique. La chaîne de certificats a prouvé qui était le serveur, et chaque octet après le Server Hello a été chiffré et authentifié, jusqu’au close_notify. Appuyez sur REVOIR pour tout revoir.","1 round trip":"1 aller-retour","Everything the browser supports":"Tout ce que le navigateur prend en charge","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Après la poignée de main TCP, le navigateur liste ce qu’il sait faire : versions de TLS, suites de chiffrement et parts de clé pour les groupes qu’il attend, dont l’hybride post-quantique X25519MLKEM768. Il nomme aussi le site (SNI) et les protocoles qu’il parle (ALPN).",Versions:"Versions","versions, ciphers, key shares":"versions, chiffrements, parts de clé","Choices made, keys computed":"Choix faits, clés calculées","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Le serveur choisit TLS 1.3, la suite de chiffrement et le groupe hybride, et envoie sa propre part de clé. À partir des deux parts, les deux côtés calculent le même secret sans qu’il traverse jamais le réseau. Tout ce qui suit ce message est chiffré.",Group:"Groupe","From here on":"À partir d’ici","its key share":"sa part de clé",Certificate:"Certificat","Who the server is, proven":"L’identité du serveur, prouvée","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Désormais chiffré, l’envoi continue : le protocole choisi (http/1.1), la chaîne de certificats, une signature faite avec la clé privée du certificat, et Finished.",Chain:"Chaîne","Site → intermediate → root":"Site → intermédiaire → racine","Proves the private key":"Prouve la clé privée",Checked:"Vérifié","Name, dates, trusted root":"Nom, dates, racine de confiance","encrypted: http/1.1, certificates,":"chiffré : http/1.1, certificats,","signature, Finished":"signature, Finished","One round trip, then data":"Un aller-retour, puis les données","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Le navigateur envoie son propre Finished : une valeur de contrôle sur tout ce que les deux côtés se sont dit, calculée avec le nouveau secret, si bien que toute falsification des hellos se verrait. TLS 1.3 n’a besoin que d’un aller-retour avant que les données circulent ; TLS 1.2 en demandait deux.",Covers:"Couvre","The whole handshake":"Toute la poignée de main","For old middleboxes":"Pour les vieux équipements intermédiaires","check value over":"valeur de contrôle sur","the whole handshake":"toute la poignée de main","Encrypted Data":"Données chiffrées","Records, tags and tickets":"Enregistrements, étiquettes et tickets","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP voyage maintenant dans des enregistrements chiffrés, chacun avec une étiquette de 16 octets qui révèle toute modification. Le serveur envoie aussi deux tickets de session : la prochaine fois, le navigateur pourra reprendre avec l’un d’eux et sauter le certificat.","Per record":"Par enregistrement","22 bytes of overhead":"22 octets de surcoût","2, for resuming later":"2, pour reprendre plus tard",Visible:"Visible","IPs, SNI, sizes, timing":"IP, SNI, tailles, minutage","2 session tickets":"2 tickets de session","for resuming later":"pour reprendre plus tard",Closing:"Fermeture","close_notify, then TCP":"close_notify, puis TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Après 75 secondes d’inactivité, le serveur ferme la connexion. Il envoie d’abord une alerte close_notify, chiffrée comme tout le reste, pour que le navigateur sache que les données se sont arrêtées volontairement et n’ont pas été coupées par un attaquant. Puis TCP se ferme comme d’habitude.",Alert:"Alerte","Shows nothing was cut off":"Montre que rien n’a été coupé","TCP FIN from both sides":"TCP FIN des deux côtés","alert: close_notify":"alerte : close_notify",encrypted:"chiffré","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ chiffré)","Encrypted handshake (continued)":"Poignée de main chiffrée (suite)","Encrypted handshake (certificate, verify, Finished)":"Poignée de main chiffrée (certificat, vérification, Finished)","Application Data (inside: close_notify alert)":"Application Data (à l’intérieur : alerte close_notify)","Alert: close_notify (the data ends here, on purpose)":"Alerte : close_notify (les données s’arrêtent ici, volontairement)","No IP address":"Pas d’adresse IP","192.168.1.1 · DHCP server":"192.168.1.1 · serveur DHCP"},c={"Two-way web messaging":"Messagerie web bidirectionnelle","Browser video calls":"Appels vidéo dans le navigateur","HTTP/3 over UDP":"HTTP/3 sur UDP","Routing between networks":"Routage entre réseaux","Address setup, neighbour discovery":"Autoconfiguration et voisins","Private DNS lookups":"Requêtes DNS privées","Signed DNS answers":"Réponses DNS signées","Network Time Protocol":"Protocole de temps réseau","Joining a network (WPA2)":"Rejoindre un réseau (WPA2)","Wi-Fi Protected Access 3":"Accès protégé Wi-Fi 3","802.1X Enterprise Wi-Fi":"Wi-Fi d’entreprise 802.1X","Hotel and café Wi-Fi logins":"Wi-Fi d’hôtels et de cafés","Windows file sharing":"Partage de fichiers Windows","Forward proxy and CONNECT":"Proxy direct et CONNECT","Socket Secure proxy":"Proxy Socket Secure","TLS offloading":"Déchargement TLS","A modern VPN":"Un VPN moderne","IKEv2 and ESP":"IKEv2 et ESP","Industrial control (OT)":"Contrôle industriel (OT)",Proxy:"Proxy","App Server":"Serveur d’application","File Server":"Serveur de fichiers","ISP Router":"Routeur du FAI","Transit Router":"Routeur de transit","Hosting Router":"Routeur de l’hébergeur","Their Router":"Routeur de l’autre","Their Laptop":"Ordinateur de l’autre",Transit:"Transit",Hosting:"Hébergeur","The router itself.":"Le routeur lui-même.","Mail in Sync":"Courrier synchronisé","Live Updates":"En direct","From the browser":"Du navigateur","From the server":"Du serveur","The WebSocket Protocol":"Le protocole WebSocket","A WebSocket keeps one connection open between a web page and a server, so either side can send a message at any moment: chat, live scores, games, shared documents. It starts as an ordinary HTTP request asking to upgrade; after that, messages travel in small frames with a header of just a few bytes.":"Un WebSocket garde une connexion ouverte entre une page web et un serveur, si bien que chaque côté peut envoyer un message à tout moment : discussion, scores en direct, jeux, documents partagés. Il commence comme une requête HTTP ordinaire qui demande une mise à niveau ; ensuite, les messages voyagent dans de petites trames avec un en-tête de quelques octets seulement.","80 (ws://), 443 (wss://)":"80 (ws://), 443 (wss://)","An HTTP request (Upgrade)":"Une requête HTTP (Upgrade)","Frames both ways, any time":"Des trames dans les deux sens, à tout moment","Frame header":"En-tête de trame","2–14 bytes":"2–14 octets","One request, then messages":"Une requête, puis des messages","One HTTP request turned an ordinary TCP connection into a two-way channel. After that every message cost a few bytes of header, and the server could send whenever it had something to say. Press REPLAY to watch it again.":"Une requête HTTP a transformé une connexion TCP ordinaire en canal bidirectionnel. Ensuite, chaque message n’a coûté que quelques octets d’en-tête, et le serveur a pu envoyer dès qu’il avait quelque chose à dire. Appuyez sur REVOIR pour tout revoir.","GET with Upgrade, then 101":"GET avec Upgrade, puis 101","Smallest frame":"Plus petite trame","2 bytes (a ping)":"2 octets (un ping)","Server push":"Envoi du serveur","Any time, unasked":"À tout moment, sans demande","Real sites":"Vrais sites","wss:// (inside TLS)":"wss:// (dans TLS)","TCP to the server, as for HTTP":"TCP vers le serveur, comme pour HTTP",'The chat page is already open, loaded from www.example.com. Its script calls new WebSocket("ws://www.example.com/chat"), and the browser starts with an ordinary TCP connection to port 80. (Real sites use wss://, the same thing inside TLS; plain ws:// lets you read every byte.)':'La page de discussion est déjà ouverte, chargée depuis www.example.com. Son script appelle new WebSocket("ws://www.example.com/chat"), et le navigateur commence par une connexion TCP ordinaire vers le port 80. (Les vrais sites utilisent wss://, la même chose dans TLS ; ws:// en clair permet de lire chaque octet.)',"ws://www.example.com/chat":"ws://www.example.com/chat","Ask to Upgrade":"Demander la mise à niveau","An HTTP request with Upgrade: websocket":"Une requête HTTP avec Upgrade: websocket","The browser sends an HTTP GET with Upgrade: websocket and Connection: Upgrade. Sec-WebSocket-Key is 16 random bytes written in base64, which the server has to answer correctly. The browser also offers to compress messages (permessage-deflate).":"Le navigateur envoie un GET HTTP avec Upgrade: websocket et Connection: Upgrade. Sec-WebSocket-Key, ce sont 16 octets aléatoires écrits en base64, auxquels le serveur doit répondre correctement. Le navigateur propose aussi de compresser les messages (permessage-deflate).","Asks for":"Demande","16 random bytes, base64":"16 octets aléatoires, base64",UPGRADE:"UPGRADE","Switch Protocols":"Changement de protocole","101: from now on, WebSocket":"101 : désormais, WebSocket","The server answers 101 Switching Protocols. Its Sec-WebSocket-Accept is the key with a fixed string added, hashed with SHA-1 and written in base64: proof that it understood the request. It didn’t take up compression, so messages go as plain text. HTTP is finished on this connection; from now on both sides send WebSocket frames.":"Le serveur répond 101 Switching Protocols. Son Sec-WebSocket-Accept est la clé suivie d’une chaîne fixe, hachée avec SHA-1 et écrite en base64 : la preuve qu’il a compris la requête. Il n’a pas accepté la compression, donc les messages partent en texte clair. HTTP est terminé sur cette connexion ; désormais les deux côtés envoient des trames WebSocket.",Accept:"Accept","SHA-1 of the key + a fixed string":"SHA-1 de la clé + une chaîne fixe",Compression:"Compression","Offered, not taken":"Proposée, refusée","NOW A WEBSOCKET":"C’EST UN WEBSOCKET","Small frames, from either side":"De petites trames, de chaque côté",'You send "Hello": a 2-byte header, a 4-byte masking key and the 5 masked bytes, 11 bytes in all instead of a whole HTTP request. Seconds later the server pushes Bob’s message without being asked: the connection is still open, so it can. Frames from the browser are always masked; frames from the server never are.':'Vous envoyez "Hello" : un en-tête de 2 octets, une clé de masquage de 4 octets et les 5 octets masqués, 11 octets en tout au lieu d’une requête HTTP entière. Quelques secondes plus tard, le serveur pousse le message de Bob sans qu’on le lui demande : la connexion est toujours ouverte, il le peut. Les trames du navigateur sont toujours masquées ; celles du serveur, jamais.',"You send":"Vous envoyez","Server pushes":"Le serveur pousse",'"bob: hi there"':'"bob: hi there"',Masked:"Masquage","From the browser only":"Navigateur seulement",TEXT:"TEXTE",masked:"masqué",unasked:"sans demande","Keeping It Alive":"Garder le lien","Ping and pong":"Ping et pong","After half a minute with nothing to say, the server sends a ping, so routers and firewalls on the way don’t forget the quiet connection. The browser answers with a pong on its own; the page’s script never sees either.":"Après une demi-minute sans rien à dire, le serveur envoie un ping, pour que les routeurs et pare-feu du trajet n’oublient pas la connexion silencieuse. Le navigateur répond tout seul par un pong ; le script de la page ne voit ni l’un ni l’autre.","Opcode 9, from either side":"Opcode 9, de chaque côté",Pong:"Pong","Opcode 10, by itself":"Opcode 10, tout seul","How often":"Fréquence","Up to the server (30 s)":"Au choix du serveur (30 s)","A close frame each way":"Une trame de fermeture dans chaque sens","When you leave the chat, the page’s script closes the WebSocket with status 1000 (normal closure): the browser sends a close frame and the server answers with its own. Then the server closes the TCP connection. (Simply closing the tab would send 1001, going away.)":"Quand vous quittez la discussion, le script de la page ferme le WebSocket avec le statut 1000 (fermeture normale) : le navigateur envoie une trame de fermeture et le serveur répond par la sienne. Puis le serveur ferme la connexion TCP. (Fermer simplement l’onglet enverrait 1001, going away.)",Opcode:"Opcode","8 (close)":"8 (fermeture)","1000 (normal closure)":"1000 (fermeture normale)","TCP closes":"TCP se ferme",CLOSE:"FERMETURE","1000 normal closure":"1000 fermeture normale","FIN 1: this frame is a whole message. The opcode says what it carries.":"FIN 1 : cette trame est un message entier. L’opcode dit ce qu’elle transporte.","Mask, length":"Masque, longueur","Everything a browser sends is masked.":"Tout ce qu’envoie un navigateur est masqué.","Masking key":"Clé de masquage","Chosen at random for every frame.":"Choisie au hasard pour chaque trame.",Payload:"Données","Each byte XORed with the masking key in turn; the server XORs it back.":"Chaque octet passe tour à tour par un XOR avec la clé de masquage ; le serveur annule le XOR.","A server never masks what it sends.":"Un serveur ne masque jamais ce qu’il envoie.","Status code":"Code de statut","Joining a Network":"Rejoindre un réseau","From the access point":"Du point d’accès","4-way handshake":"Négociation en 4 temps","Access Point":"Point d’accès","Wi-Fi (802.11) with WPA2":"Wi-Fi (802.11) avec WPA2","Wi-Fi carries a network over radio. Before a device can send anything, it has to find the network, join it and prove it knows the password. With WPA2-Personal that proof is the 4-way handshake: four short messages that turn the password into fresh encryption keys, without the password ever going over the air.":"Le Wi-Fi transporte un réseau par radio. Avant de pouvoir envoyer quoi que ce soit, un appareil doit trouver le réseau, le rejoindre et prouver qu’il connaît le mot de passe. Avec WPA2-Personal, cette preuve est la négociation en 4 temps : quatre messages courts qui transforment le mot de passe en clés de chiffrement neuves, sans que le mot de passe passe jamais dans les airs.","Data Link (Layer 2)":"Liaison de données (couche 2)",Standard:"Norme",Joining:"Pour rejoindre","Probe, authenticate, associate":"Sonde, authentification, association","Keys from":"Clés tirées de","The 4-way handshake":"La négociation en 4 temps",Connected:"Connecté","Eleven frames to a secure link":"Onze trames jusqu’à un lien sûr","The laptop found the network, joined it with two formalities and proved it knew the password in a four-message handshake, without ever sending it. Everything after that was encrypted with keys made for this connection alone. Press REPLAY to watch it again.":"L’ordinateur a trouvé le réseau, l’a rejoint en deux formalités et a prouvé qu’il connaissait le mot de passe en une négociation de quatre messages, sans jamais l’envoyer. Tout ce qui a suivi a été chiffré avec des clés créées pour cette seule connexion. Appuyez sur REVOIR pour tout revoir.","Frames to join":"Trames pour rejoindre","Password sent":"Mot de passe envoyé",Never:"Jamais","Session keys":"Clés de session","New every time":"Neuves à chaque fois",Next:"Ensuite","DHCP, for an IP address":"DHCP, pour une adresse IP","Find the Network":"Trouver le réseau","A beacon, then a probe":"Une balise, puis une sonde",'About ten times a second the router’s Wi-Fi sends a beacon: here is "HomeNet", protected with WPA2, on channel 36. The laptop could simply wait to hear one; to be quicker it also asks out loud with a probe request, and the access point answers with a probe response.':'Une dizaine de fois par seconde, le Wi-Fi du routeur envoie une balise (beacon) : voici "HomeNet", protégé par WPA2, sur le canal 36. L’ordinateur pourrait simplement attendre d’en entendre une ; pour aller plus vite, il demande aussi à voix haute avec une requête de sonde, et le point d’accès répond par une réponse de sonde.',"WPA2-Personal (password)":"WPA2-Personal (mot de passe)",BEACON:"BALISE","WPA2 · channel 36":"WPA2 · canal 36",PROBE:"SONDE","any networks here?":"des réseaux par ici ?","PROBE RESPONSE":"RÉPONSE DE SONDE","Join the Network":"Rejoindre le réseau","Two formalities: hello, then join":"Deux formalités : bonjour, puis rejoindre","Open System authentication lets anyone this far: no password yet. Then the laptop asks to associate, repeating the security it chose (CCMP, with a password), and the access point gives it association ID 1. The laptop is connected, but the only thing it may send is the handshake that comes next.":"L’authentification Open System laisse n’importe qui arriver jusqu’ici : pas encore de mot de passe. Puis l’ordinateur demande à s’associer, en répétant la sécurité qu’il a choisie (CCMP, avec mot de passe), et le point d’accès lui donne l’identifiant d’association 1. L’ordinateur est connecté, mais il ne peut envoyer que la négociation qui suit.",Authentication:"Authentification","Open System (no password)":"Open System (sans mot de passe)","Association ID":"ID d’association","Allowed so far":"Autorisé pour l’instant",success:"succès",ASSOCIATE:"ASSOCIATION",'join "HomeNet"':'rejoindre "HomeNet"',"CCMP, password":"CCMP, mot de passe",ASSOCIATED:"ASSOCIÉ","association ID 1":"ID d’association 1","Messages 1 and 2":"Messages 1 et 2","The 4-way handshake: nonces":"La négociation en 4 temps : les nonces","Both sides already hold the same key, worked out from the password and the network’s name (the PMK); it never goes over the air. The access point sends a random number, the ANonce. The laptop sends its own, the SNonce, with a check value (MIC). From the PMK, the two nonces and both MAC addresses, each side now works out the same session keys.":"Les deux côtés ont déjà la même clé, tirée du mot de passe et du nom du réseau (la PMK) ; elle ne passe jamais dans les airs. Le point d’accès envoie un nombre aléatoire, l’ANonce. L’ordinateur envoie le sien, le SNonce, avec une valeur de contrôle (MIC). À partir de la PMK, des deux nonces et des deux adresses MAC, chaque côté calcule maintenant les mêmes clés de session.","Shared key":"Clé partagée","PMK, from the password":"PMK, tirée du mot de passe",Exchanged:"Échangés","Two random nonces":"Deux nonces aléatoires","Worked out":"Calculées","Session keys (PTK)":"Clés de session (PTK)","MESSAGE 1":"MESSAGE 1","MESSAGE 2":"MESSAGE 2","Messages 3 and 4":"Messages 3 et 4","The 4-way handshake: keys":"La négociation en 4 temps : les clés","Message 3 shows the access point has the same keys (its MIC checks out) and brings the group key (GTK) for broadcasts, encrypted. Message 4 says the laptop is ready, and both ends start encrypting.":"Le message 3 montre que le point d’accès a les mêmes clés (son MIC est correct) et apporte la clé de groupe (GTK) pour les diffusions, chiffrée. Le message 4 dit que l’ordinateur est prêt, et les deux bouts commencent à chiffrer.","Group key":"Clé de groupe","GTK, sent encrypted":"GTK, envoyée chiffrée",Install:"Installation","Both ends at once":"Les deux bouts à la fois","MESSAGE 3":"MESSAGE 3","group key, encrypted":"clé de groupe, chiffrée","MESSAGE 4":"MESSAGE 4","keys installed":"clés installées","Encrypted Now":"Chiffré désormais","And what a listener could still do":"Et ce qu’une oreille indiscrète peut encore faire","Every data frame is encrypted now, like this first one carrying a DHCP Discover: anyone nearby sees only the MAC addresses and the size. But someone who recorded the four handshake messages can try password guesses at home, as fast as their computer allows: a guess is right when it gives the same MIC. A long, random password makes that hopeless; WPA3 removes the weakness.":"Chaque trame de données est désormais chiffrée, comme cette première qui transporte un DHCP Discover : qui se trouve à proximité ne voit que les adresses MAC et la taille. Mais quelqu’un qui a enregistré les quatre messages de la négociation peut essayer des mots de passe chez lui, aussi vite que son ordinateur le permet : un essai est juste quand il donne le même MIC. Un mot de passe long et aléatoire rend cela vain ; WPA3 supprime cette faiblesse.","Others see":"Les autres voient","MAC addresses, sizes, timing":"Adresses MAC, tailles, horaires","Weak point":"Point faible","Offline password guessing":"Deviner le mot de passe hors ligne",Defence:"Défense","A long password, or WPA3":"Un long mot de passe, ou WPA3","DHCP Discover inside":"dedans, un DHCP Discover","ENCRYPTED FROM HERE ON":"CHIFFRÉ À PARTIR D’ICI","QoS Data (encrypted)":"QoS Data (chiffré)","Seen over the air, on Wi-Fi channel 36":"Vu dans les airs, sur le canal Wi-Fi 36","Frame type":"Type de trame","Management, Beacon":"Gestion, Beacon",Duration:"Durée","Nobody acknowledges a broadcast, so nothing is booked.":"Personne n’accuse réception d’une diffusion, donc rien n’est réservé.",Receiver:"Récepteur","Broadcast: every device in range listens.":"Diffusion : tous les appareils à portée écoutent.",Transmitter:"Émetteur","The access point.":"Le point d’accès.","The access point’s own address: which network this is about.":"L’adresse propre du point d’accès : de quel réseau il s’agit.","Lets the receiver spot a repeat when a frame is sent again.":"Permet au récepteur de repérer une répétition quand une trame est renvoyée.","The access point’s clock; devices on the network keep theirs in step with it.":"L’horloge du point d’accès ; les appareils du réseau règlent la leur sur elle.","Beacon interval":"Intervalle des balises","A beacon goes out about ten times a second.":"Une balise part environ dix fois par seconde.","0x0011: access point network, encrypted":"0x0011 : réseau avec point d’accès, chiffré","Privacy bit set: joining takes a key.":"Bit de confidentialité activé : il faut une clé pour rejoindre.","The network’s name.":"Le nom du réseau.","Supported rates":"Débits pris en charge","Only the oldest, slowest rates; the fast ones are in the elements that follow.":"Seulement les débits les plus anciens et les plus lents ; les rapides sont dans les éléments qui suivent.","DTIM count 0, period 1":"Compteur DTIM 0, période 1","Tells sleeping devices whether frames are waiting for them.":"Indique aux appareils endormis si des trames les attendent.","Robust Security Network: how this network is protected.":"Robust Security Network : comment ce réseau est protégé.","Element ID, length":"ID d’élément, longueur","48, 20 bytes":"48, 20 octets","Group cipher":"Chiffrement de groupe","Encrypts broadcasts, which every device on the network can read.":"Chiffre les diffusions, que tout appareil du réseau peut lire.","Pairwise cipher":"Chiffrement par paire","Encrypts each device’s own traffic, with keys only it and the access point have.":"Chiffre le trafic propre à chaque appareil, avec des clés que seuls lui et le point d’accès possèdent.","Key management":"Gestion des clés","1: PSK (a shared password)":"1 : PSK (un mot de passe partagé)","More elements":"Autres éléments","Wi-Fi 4, 5 and 6 capabilities and settings (HT, VHT, HE: channel 36, 80 MHz wide), and vendor extras.":"Capacités et réglages Wi-Fi 4, 5 et 6 (HT, VHT, HE : canal 36, 80 MHz de large) et extras du fabricant.","Management, Probe Request":"Gestion, Probe Request","The laptop’s Wi-Fi card.":"La carte Wi-Fi de l’ordinateur.","empty (any network)":"vide (n’importe quel réseau)","Any access point may answer. (Devices used to ask for every network they had joined by name, telling anyone listening where they had been.)":"N’importe quel point d’accès peut répondre. (Avant, les appareils demandaient par leur nom chaque réseau déjà rejoint, révélant à qui écoutait où ils étaient passés.)","What the laptop’s radio can do: Wi-Fi 4, 5 and 6 capabilities, and vendor extras.":"Ce que sait faire la radio de l’ordinateur : capacités Wi-Fi 4, 5 et 6, et extras du fabricant.","Management, Probe Response":"Gestion, Probe Response","How long the channel stays booked for this exchange; other devices wait.":"Combien de temps le canal reste réservé pour cet échange ; les autres appareils attendent.","The radio this frame is for.":"La radio à qui s’adresse cette trame.","Authentication · Open System":"Authentification · Open System","Management, Authentication":"Gestion, Authentication",Algorithm:"Algorithme","Open: anyone may get this far. The password is checked later, in the 4-way handshake.":"Ouverte : n’importe qui peut arriver jusqu’ici. Le mot de passe est vérifié plus tard, dans la négociation en 4 temps.",Transaction:"Transaction","0 (success)":"0 (succès)","Management, Association Request":"Gestion, Association Request","Listen interval":"Intervalle d’écoute","10 beacons":"10 balises","How often the laptop wakes to check for waiting frames when saving power.":"À quelle fréquence l’ordinateur se réveille pour voir si des trames l’attendent quand il économise l’énergie.","What the laptop’s radio can do (Wi-Fi 4, 5 and 6), and vendor extras.":"Ce que sait faire la radio de l’ordinateur (Wi-Fi 4, 5 et 6) et extras du fabricant.","Management, Association Response":"Gestion, Association Response","The laptop’s number at this access point (the top two bits are always set).":"Le numéro de l’ordinateur auprès de ce point d’accès (les deux bits de poids fort sont toujours à 1).","The settings the access point uses (Wi-Fi 4, 5 and 6), and vendor extras.":"Les réglages qu’utilise le point d’accès (Wi-Fi 4, 5 et 6) et extras du fabricant.","Data, QoS Data":"Données, QoS Data","0x02 (from the access point)":"0x02 (depuis le point d’accès)","Sent by the access point itself.":"Envoyé par le point d’accès lui-même.","QoS control":"Contrôle QoS","Priority 7, the highest: the handshake goes first.":"Priorité 7, la plus haute : la négociation passe en premier.",Organization:"Organisation","0x888e (802.1X authentication)":"0x888e (authentification 802.1X)","What follows: plays the part an Ethernet type field does on a cable.":"Ce qui suit : joue le rôle du champ de type Ethernet sur un câble.","Descriptor type":"Type de descripteur","Key information":"Informations de clé","0x008a: pairwise, ACK":"0x008a : par paire, ACK","ACK: the laptop must answer.":"ACK : l’ordinateur doit répondre.","Key length":"Longueur de clé","The pairwise key is 16 bytes (AES-128).":"La clé par paire fait 16 octets (AES-128).","Replay counter":"Compteur anti-rejeu","Counts up with each message from the access point; an old one sent again is ignored.":"Augmente à chaque message du point d’accès ; un ancien renvoyé est ignoré.","A random number from the access point.":"Un nombre aléatoire du point d’accès.","Key IV":"IV de clé",zeros:"zéros","Key RSC":"RSC de clé","No keys yet, so nothing to check with.":"Pas encore de clés, donc rien pour vérifier.","Key data length":"Longueur des données de clé","0x01 (to the access point)":"0x01 (vers le point d’accès)","The access point itself.":"Le point d’accès lui-même.","0x010a: pairwise, MIC":"0x010a : par paire, MIC","MIC: this message carries a check value.":"MIC : ce message porte une valeur de contrôle.","A random number from the laptop. From both numbers, both MAC addresses and the key that comes from the password, each side works out the same session keys.":"Un nombre aléatoire de l’ordinateur. Avec les deux nombres, les deux adresses MAC et la clé tirée du mot de passe, chaque côté calcule les mêmes clés de session.","Worked out with the new keys: it proves the sender knows the password, and that the message wasn’t changed.":"Calculé avec les nouvelles clés : prouve que l’expéditeur connaît le mot de passe et que le message n’a pas été modifié.","0x13ca: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13ca : par paire, installer, ACK, MIC, sécurisé, données de clé chiffrées","Install: start using the keys. The group key comes encrypted.":"Installer : commencer à utiliser les clés. La clé de groupe arrive chiffrée.","Where the group key’s packet numbers start.":"Où commencent les numéros de paquet de la clé de groupe.","Key data":"Données de clé","Encrypted with a key from the handshake.":"Chiffrées avec une clé de la négociation.","The access point’s RSN element":"L’élément RSN du point d’accès","GTK: the group key, for broadcasts":"GTK : la clé de groupe, pour les diffusions","0x030a: pairwise, MIC, secure":"0x030a : par paire, MIC, sécurisé","Secure: the keys are in place.":"Sécurisé : les clés sont en place.","CCMP · encrypted":"CCMP · chiffré","0x41 (protected, to the access point)":"0x41 (protégée, vers le point d’accès)","Protected: what follows the header is encrypted.":"Protégée : ce qui suit l’en-tête est chiffré.","Where the access point should pass it on to: everyone on the network.":"À qui le point d’accès doit la transmettre : à tout le réseau.","CCMP header":"En-tête CCMP","packet number 1, key 0":"numéro de paquet 1, clé 0","Counts up with every frame; one seen before is thrown away.":"Augmente à chaque trame ; une trame déjà vue est jetée.","LLC/SNAP: an IPv4 packet":"LLC/SNAP : un paquet IPv4","Shows any change to the frame.":"Révèle toute modification de la trame.","Safer Wi-Fi":"Un Wi-Fi plus sûr","WPA3 is the current Wi-Fi security standard. Its Personal mode keeps the simple shared password but changes how it is checked: SAE, a password exchange that no recording can attack offline, gives every connection a fresh key. It also makes protected management frames compulsory.":"WPA3 est la norme actuelle de sécurité Wi-Fi. Son mode Personal garde le simple mot de passe partagé mais change la façon de le vérifier : SAE, un échange de mot de passe qu’aucun enregistrement ne permet d’attaquer hors ligne, donne à chaque connexion une clé neuve. Il rend aussi obligatoires les trames de gestion protégées.","Password check":"Vérification",Required:"Obligatoire","Protected management frames":"Trames de gestion protégées",Since:"Depuis","Connected with WPA3":"Connecté avec WPA3","Same password, better protocol":"Même mot de passe, meilleur protocole","The laptop and the access point proved to each other that they know the password without giving anyone a way to test guesses offline, then made fresh keys exactly as WPA2 does. Press REPLAY to watch it again.":"L’ordinateur et le point d’accès se sont prouvé qu’ils connaissent le mot de passe sans donner à quiconque le moyen de tester des essais hors ligne, puis ont créé des clés neuves exactement comme WPA2. Appuyez sur REVOIR pour tout revoir.","SAE frames":"Trames SAE","4 (commit, confirm)":"4 (commit, confirm)","4 EAPOL-Key frames":"4 trames EAPOL-Key","Offline guessing":"Essais hors ligne","Not possible":"Impossibles","Forged disconnects":"Fausses déconnexions",Ignored:"Ignorées","A WPA3 Network":"Un réseau WPA3","The beacon asks for SAE":"La balise demande SAE","The beacon looks like WPA2’s with two changes in its RSN element: the key management is SAE instead of PSK, and protected management frames are required. Everyone still uses one shared password.":"La balise ressemble à celle de WPA2, avec deux changements dans son élément RSN : la gestion des clés est SAE au lieu de PSK, et les trames de gestion protégées sont obligatoires. Tout le monde utilise toujours un seul mot de passe partagé.","Management frames":"Trames de gestion","Protected (required)":"Protégées (obligatoire)","Still one for everyone":"Toujours un pour tous","SAE Commit":"SAE Commit","Each side commits to the password":"Chaque côté s’engage sur le mot de passe","Instead of Open System authentication, the two sides run SAE, a password exchange between equals. Each picks a random secret and sends a scalar and an element worked out from that secret and the password. The password is the same on both sides, the secrets are not, so every connection ends up with a new key.":"Au lieu de l’authentification Open System, les deux côtés exécutent SAE, un échange de mot de passe entre égaux. Chacun choisit un secret aléatoire et envoie un scalaire et un élément calculés à partir de ce secret et du mot de passe. Le mot de passe est le même des deux côtés, les secrets non, donc chaque connexion obtient une clé neuve.","19 (256-bit curve)":"19 (courbe de 256 bits)","Each sends":"Chacun envoie","A scalar and an element":"Un scalaire et un élément",Replaces:"Remplace","Open System authentication":"L’authentification Open System",COMMIT:"COMMIT","scalar + element":"scalaire + élément","SAE Confirm":"SAE Confirm","Proof, without the password":"Une preuve, sans le mot de passe","Each side now works out the shared key and sends a confirm, a value only someone with the right password could produce. Recording all four SAE frames doesn’t let an attacker test guesses at home: every guess takes a live exchange with the access point, which can slow them down or shut them out.":"Chaque côté calcule maintenant la clé partagée et envoie un confirm, une valeur que seul quelqu’un ayant le bon mot de passe pourrait produire. Enregistrer les quatre trames SAE ne permet pas à un attaquant de tester des mots de passe chez lui : chaque essai exige un échange en direct avec le point d’accès, qui peut le ralentir ou le bloquer.","A new key (PMK) each time":"Une clé neuve (PMK) à chaque fois",Guessing:"Essais","Live only, never offline":"En direct seulement, jamais hors ligne","Password leaks":"Fuite du mot de passe","Past traffic stays safe":"Le trafic passé reste protégé",CONFIRM:"CONFIRM","proof of the key":"preuve de la clé","Join, Handshake":"Rejoindre, négocier","Then the 4-way handshake, as in WPA2":"Puis la négociation en 4 temps, comme avec WPA2","Association works as before, repeating the choice of SAE. The 4-way handshake that follows is WPA2’s, starting from the key SAE just made, except that message 3 also brings the IGTK, a key that signs broadcast management frames.":"L’association fonctionne comme avant, en répétant le choix de SAE. La négociation en 4 temps qui suit est celle de WPA2, à partir de la clé que SAE vient de créer, sauf que le message 3 apporte aussi l’IGTK, une clé qui signe les trames de gestion diffusées.","Message 3 adds":"Le message 3 ajoute","Why It’s Safer":"Pourquoi c’est plus sûr","Forged disconnects stop working":"Les fausses déconnexions ne marchent plus","With WPA2, anyone in range could forge a “disconnect” frame and knock a device off the network, often to record its handshake when it joined again. WPA3 requires protected management frames, so forged disconnects are ignored. Many routers also offer a transition mode that lets WPA2 devices join too; those devices keep WPA2’s weaknesses.":"Avec WPA2, n’importe qui à portée pouvait forger une trame de « déconnexion » et éjecter un appareil du réseau, souvent pour enregistrer sa négociation quand il revenait. WPA3 exige des trames de gestion protégées, donc les fausses déconnexions sont ignorées. Beaucoup de routeurs proposent aussi un mode de transition qui laisse entrer les appareils WPA2 ; ces appareils gardent les faiblesses de WPA2.",Protected:"Protégées","Disconnects, other management":"Déconnexions, autres trames de gestion","WPA2/3 mode":"Mode WPA2/3","WPA2 devices stay at risk":"Les appareils WPA2 restent exposés","Stronger still":"Plus solide encore","WPA3-Enterprise (192-bit)":"WPA3-Enterprise (192 bits)","MANAGEMENT FRAMES PROTECTED":"TRAMES DE GESTION PROTÉGÉES","0x00c0: management frame protection required":"0x00c0 : protection des trames de gestion obligatoire","Disconnect messages and other management frames are signed, so they can’t be forged.":"Les messages de déconnexion et autres trames de gestion sont signés, donc impossibles à falsifier.","Authentication · SAE Commit":"Authentification · SAE Commit","Simultaneous Authentication of Equals: WPA3’s password exchange.":"Simultaneous Authentication of Equals : l’échange de mot de passe de WPA3.","19 (256-bit elliptic curve)":"19 (courbe elliptique de 256 bits)",Scalar:"Scalaire","Worked out from a random secret and the password.":"Calculé à partir d’un secret aléatoire et du mot de passe.",Element:"Élément","A point on the curve, also tied to the password. Recording the scalar and element doesn’t let anyone test password guesses afterwards.":"Un point de la courbe, lui aussi lié au mot de passe. Enregistrer le scalaire et l’élément ne permet à personne de tester des mots de passe ensuite.","Authentication · SAE Confirm":"Authentification · SAE Confirm","Proves this side worked out the same key, without giving it away.":"Prouve que ce côté a calculé la même clé, sans la dévoiler.","0x0088: pairwise, ACK":"0x0088 : par paire, ACK","0x0108: pairwise, MIC":"0x0108 : par paire, MIC","0x13c8: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13c8 : par paire, installer, ACK, MIC, sécurisé, données de clé chiffrées","IGTK: the key that signs broadcast management frames":"IGTK : la clé qui signe les trames de gestion diffusées","0x0308: pairwise, MIC, secure":"0x0308 : par paire, MIC, sécurisé","Sign-In":"Connexion","From the router":"Du routeur","From the test server":"Du serveur de test","Hotel Router":"Routeur de l’hôtel","192.168.1.1 · captive portal":"192.168.1.1 · portail captif","Wi-Fi login pages":"Pages de connexion Wi-Fi","Hotels, cafés, airports and trains often put a login page in front of their Wi-Fi. Until you accept the terms (or pay), the router lets nothing out to the internet. It catches your device’s first plain HTTP request and answers it with a redirect to its own page; your device notices because a test page it knows comes back wrong.":"Hôtels, cafés, aéroports et trains placent souvent une page de connexion devant leur Wi-Fi. Tant que vous n’acceptez pas les conditions (ou ne payez pas), le routeur ne laisse rien sortir vers Internet. Il intercepte la première requête HTTP en clair de votre appareil et y répond par une redirection vers sa propre page ; votre appareil s’en aperçoit parce qu’une page de test qu’il connaît revient fausse.",Where:"Où","Hotels, cafés, airports":"Hôtels, cafés, aéroports",How:"Comment","Catches plain HTTP requests":"Intercepte les requêtes HTTP en clair","Noticed by":"Repéré par","Your system’s test page":"La page de test de votre système","Logging in":"En se connectant","Lets your MAC address through":"Laisse passer votre adresse MAC","Newer way":"Méthode récente","DHCP option 114 (RFC 8910)":"Option DHCP 114 (RFC 8910)","Described In":"Décrit dans",Online:"En ligne","Noticed, logged in, let through":"Repéré, connecté, laissé passer","Windows asked a test page for an answer it knows and got a redirect instead, so it knew a portal was in the way and opened the login page. Once the terms were accepted, the router let the laptop through, and the same check came back right. Press REPLAY to watch it again.":"Windows a demandé à une page de test une réponse qu’il connaît et a reçu une redirection à la place ; il a donc compris qu’un portail se trouvait sur le chemin et a ouvert la page de connexion. Une fois les conditions acceptées, le routeur a laissé passer l’ordinateur, et la même vérification est revenue correcte. Appuyez sur REVOIR pour tout revoir.","A plain HTTP test page":"Une page de test HTTP en clair","Faked by":"Simulé par","The router (TTL 64)":"Le routeur (TTL 64)","Let through":"Laisse passer","The laptop’s MAC address":"L’adresse MAC de l’ordinateur","Open Wi-Fi":"Wi-Fi ouvert","Use HTTPS, or a VPN":"Utilisez HTTPS, ou un VPN","Joined, Offline":"Connecté, sans issue","An address, but no way out":"Une adresse, mais pas d’issue","The laptop has joined the hotel’s Wi-Fi, which has no password, and got an address from the router by DHCP. The router answers the laptop itself and passes on its DNS lookups, but drops anything else bound for the internet until the guest has logged in. (An open network also means anyone nearby can read whatever isn’t protected by HTTPS.)":"L’ordinateur a rejoint le Wi-Fi de l’hôtel, qui n’a pas de mot de passe, et a obtenu une adresse du routeur par DHCP. Le routeur répond lui-même à l’ordinateur et transmet ses requêtes DNS, mais jette tout le reste destiné à Internet tant que le client ne s’est pas connecté. (Un réseau ouvert signifie aussi que n’importe qui à proximité peut lire ce qui n’est pas protégé par HTTPS.)","192.168.1.10 (by DHCP)":"192.168.1.10 (par DHCP)","Wi-Fi password":"Mot de passe Wi-Fi","None (open network)":"Aucun (réseau ouvert)","Blocked until you log in":"Bloqué jusqu’à la connexion","CONNECTED, NO INTERNET YET":"CONNECTÉ, PAS ENCORE D’INTERNET","Internet Check":"Test d’Internet","Windows checks a test page":"Windows consulte une page de test",'After joining any network, Windows looks up www.msftconnecttest.com (the router passes the lookup on) and asks it for /connecttest.txt over plain HTTP; the right answer is the text "Microsoft Connect Test". The router catches the connection and answers the handshake itself, in the test server’s name. The laptop can’t tell yet.':'Après avoir rejoint n’importe quel réseau, Windows cherche www.msftconnecttest.com (le routeur transmet la requête) et lui demande /connecttest.txt en HTTP en clair ; la bonne réponse est le texte "Microsoft Connect Test". Le routeur intercepte la connexion et répond lui-même à la poignée de main, au nom du serveur de test. L’ordinateur ne peut pas encore s’en apercevoir.',"Test page":"Page de test","msftconnecttest.com/connecttest.txt":"msftconnecttest.com/connecttest.txt",Expected:"Attendu","Answered by":"Répondu par","The router, posing as the server":"Le routeur, qui se fait passer pour le serveur",'from "203.0.113.30"':'de "203.0.113.30"',"/connecttest.txt":"/connecttest.txt",Redirected:"Redirigé","The wrong answer gives it away":"La mauvaise réponse le trahit",'Instead of the test text, the "server" answers 302 Found, pointing to the router’s login page. Its TTL is 64, not lowered at all, because it came straight from the router. Windows sees the wrong answer, marks the network as needing action and opens the browser, whose first request the router redirects the same way, to its login page. This only works with plain HTTP: the router can’t fake an HTTPS page without a certificate error.':'Au lieu du texte de test, le "serveur" répond 302 Found, en pointant vers la page de connexion du routeur. Son TTL est 64, pas du tout diminué, parce qu’il vient directement du routeur. Windows voit la mauvaise réponse, marque le réseau comme nécessitant une action et ouvre le navigateur, dont le routeur redirige la première requête de la même façon, vers sa page de connexion. Cela ne marche qu’avec HTTP en clair : le routeur ne peut pas simuler une page HTTPS sans erreur de certificat.',"302 → 192.168.1.1/login":"302 → 192.168.1.1/login","Give-away":"Indice","TTL 64, from one hop away":"TTL 64, à un saut","Why HTTP":"Pourquoi HTTP","HTTPS can’t be faked":"HTTPS ne se simule pas","302 FOUND":"302 FOUND","ACTION NEEDED":"ACTION REQUISE","The Login Page":"La page de connexion","Served by the router itself":"Servie par le routeur lui-même","The browser opens http://192.168.1.1/login, a page the router serves itself: the hotel’s name, the terms of use and an Accept button. This connection really does go to the router.":"Le navigateur ouvre http://192.168.1.1/login, une page servie par le routeur lui-même : le nom de l’hôtel, les conditions d’utilisation et un bouton Accepter. Cette connexion va vraiment au routeur.",Page:"Page","http://192.168.1.1/login":"http://192.168.1.1/login","Served by":"Servie par","The router":"Le routeur",Size:"Taille","2,400 bytes of HTML":"2,400 octets de HTML","/login":"/login","the login page":"la page de connexion","Accept the Terms":"Accepter les conditions","The router lets the laptop out":"Le routeur laisse sortir l’ordinateur","Clicking Accept posts a small form back to the router. It adds the laptop’s MAC address to the list of devices allowed out, often for the length of the stay, and redirects the browser on its way.":"Cliquer sur Accepter renvoie un petit formulaire au routeur. Il ajoute l’adresse MAC de l’ordinateur à la liste des appareils autorisés à sortir, souvent pour toute la durée du séjour, et redirige le navigateur vers sa destination.",Form:"Formulaire","terms=accepted":"terms=accepted","Router allows":"Le routeur autorise","302 to where you were going":"302 vers votre destination","you’re online":"vous êtes en ligne","MAC ADDRESS ALLOWED":"ADRESSE MAC AUTORISÉE","The same check, now real":"La même vérification, pour de vrai","Windows checks again. This time the router lets the connection through to the real test server, twelve routers away (its replies arrive with TTL 52), and the answer is the expected text. The network is marked as connected to the internet.":"Windows vérifie à nouveau. Cette fois le routeur laisse passer la connexion jusqu’au vrai serveur de test, à douze routeurs de là (ses réponses arrivent avec un TTL de 52), et la réponse est le texte attendu. Le réseau est marqué comme connecté à Internet.","Connected to the internet":"Connecté à Internet",ONLINE:"EN LIGNE","www.msftconnecttest.com, type A, class IN":"www.msftconnecttest.com, type A, classe IN","www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)":"www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)","Sent with 64 and not lowered at all: it came from the router next door, not from a server 12 routers away.":"Envoyé avec 64 et pas du tout diminué : il vient du routeur d’à côté, pas d’un serveur à 12 routeurs de là.","2,400 bytes: the login page":"2,400 octets : la page de connexion","Via a Proxy":"Par un proxy","TLS, through the tunnel":"TLS, par le tunnel","Forward proxy, and CONNECT for HTTPS":"Proxy direct, et CONNECT pour HTTPS","A forward proxy fetches web pages on your behalf. Companies and schools use one to filter sites, keep copies of popular pages and log what goes out; the sites you visit see the proxy, not you. Plain HTTP passes through it in the clear. For HTTPS the browser asks the proxy for a tunnel, and the encrypted connection runs through it unread.":"Un proxy direct récupère les pages web à votre place. Entreprises et écoles en utilisent un pour filtrer des sites, garder des copies des pages populaires et journaliser ce qui sort ; les sites que vous visitez voient le proxy, pas vous. Le HTTP en clair le traverse à découvert. Pour HTTPS, le navigateur demande au proxy un tunnel, et la connexion chiffrée le traverse sans être lue.","Common ports":"Ports courants","http:// pages":"Pages http://","Fetched by the proxy":"Récupérées par le proxy","https:// pages":"Pages https://","Tunnelled with CONNECT":"Par un tunnel CONNECT","Used for":"Sert à","Filtering, caching, logging":"Filtrer, mettre en cache, journaliser","Two ways through":"Deux façons de passer","Fetched for you, or tunnelled":"Récupérée pour vous, ou par un tunnel","For the plain page, the proxy did the work: it read the request, fetched the page on its own connection and could have kept, changed or refused it. For HTTPS it only opened a tunnel and copied encrypted bytes, knowing nothing but the site’s name. Press REPLAY to watch it again.":"Pour la page en clair, le proxy a fait le travail : il a lu la requête, récupéré la page par sa propre connexion et aurait pu la garder, la modifier ou la refuser. Pour HTTPS, il a seulement ouvert un tunnel et copié des octets chiffrés, sans rien savoir d’autre que le nom du site. Appuyez sur REVOIR pour tout revoir.","Server sees":"Le serveur voit","The proxy (192.0.2.80)":"Le proxy (192.0.2.80)","Plain HTTP":"HTTP en clair","The proxy reads it all":"Le proxy lit tout","Name and sizes only":"Nom et tailles seulement","DNS for the site":"DNS du site","Done by the proxy":"Fait par le proxy","Proxy Settings":"Réglages du proxy","The browser sends everything there":"Le navigateur y envoie tout","The browser is set to send everything through a proxy at 192.0.2.80, port 8080, as many companies and schools require. You open http://www.example.com. The browser doesn’t look up www.example.com itself: it connects to the proxy and leaves the rest to it.":"Le navigateur est réglé pour tout envoyer par un proxy en 192.0.2.80, port 8080, comme l’exigent beaucoup d’entreprises et d’écoles. Vous ouvrez http://www.example.com. Le navigateur ne cherche pas www.example.com lui-même : il se connecte au proxy et lui laisse le reste.","Left to the proxy":"Laissé au proxy","To the Proxy":"Vers le proxy","TCP to port 8080":"TCP vers le port 8080","The laptop opens an ordinary TCP connection, not to the website, but to the proxy’s port 8080.":"L’ordinateur ouvre une connexion TCP ordinaire, non pas vers le site web, mais vers le port 8080 du proxy.","192.0.2.80, port 8080":"192.0.2.80, port 8080","Not to":"Pas vers","The Whole URL":"L’URL entière","Sent to a proxy, the request line carries the whole address, not just the path: GET http://www.example.com/ HTTP/1.1. That is how the proxy knows where to go. Chrome adds Proxy-Connection: keep-alive, a header only proxies read.":"Envoyée à un proxy, la ligne de requête porte l’adresse entière, pas seulement le chemin : GET http://www.example.com/ HTTP/1.1. C’est ainsi que le proxy sait où aller. Chrome ajoute Proxy-Connection: keep-alive, un en-tête que seuls les proxys lisent.","Request line":"Ligne de requête","To a server":"Vers un serveur","Readable by":"Lisible par","The proxy (plain HTTP)":"Le proxy (HTTP en clair)","to the proxy":"vers le proxy","Proxy Fetches It":"Le proxy la récupère","Its own connection to the server":"Sa propre connexion au serveur","The proxy looks up www.example.com itself (not shown) and opens its own connection to the server. Its request is the ordinary kind, GET /, with headers of its own: Via names the proxy, and X-Forwarded-For gives the address the request came from (the home router’s public address, since the laptop is behind NAT).":"Le proxy cherche www.example.com lui-même (non montré) et ouvre sa propre connexion au serveur. Sa requête est ordinaire, GET /, avec ses propres en-têtes : Via nomme le proxy, et X-Forwarded-For donne l’adresse d’où vient la requête (l’adresse publique du routeur de la maison, puisque l’ordinateur est derrière un NAT).","The proxy’s own":"Celle du proxy","1.1 proxy.example.net":"1.1 proxy.example.net","Forwarded for":"Pour le compte de","Page Passed On":"Page transmise","The page, passed on":"La page, transmise","The server answers the proxy, and the proxy passes the page on to the laptop with a Via header of its own. It could keep a copy and give it to the next person who asks without troubling the server (X-Cache: MISS says it had none yet), and it can refuse sites that aren’t allowed.":"Le serveur répond au proxy, et le proxy transmet la page à l’ordinateur avec son propre en-tête Via. Il pourrait en garder une copie et la donner à la prochaine personne qui la demande sans déranger le serveur (X-Cache: MISS indique qu’il n’en avait pas encore), et il peut refuser les sites non autorisés.","The proxy, not the laptop":"Le proxy, pas l’ordinateur",Cache:"Cache","MISS (first request)":"MISS (première requête)","Proxy can":"Le proxy peut","Cache, filter, log, change":"Mettre en cache, filtrer, journaliser, modifier","CONNECT www.example.com:443":"CONNECT www.example.com:443","Now you open https://www.example.com. A proxy can’t fetch an HTTPS page for you without breaking its encryption, so the browser asks for a tunnel instead: CONNECT www.example.com:443. The proxy opens a TCP connection to port 443 and answers 200 Connection established.":"Vous ouvrez maintenant https://www.example.com. Un proxy ne peut pas récupérer une page HTTPS pour vous sans casser son chiffrement ; le navigateur demande donc un tunnel : CONNECT www.example.com:443. Le proxy ouvre une connexion TCP vers le port 443 et répond 200 Connection established.","Proxy opens":"Le proxy ouvre","TCP to port 443":"TCP vers le port 443","200 Connection established":"200 Connection established","Connection established":"Connexion établie","In the Tunnel":"Dans le tunnel","The proxy copies, unread":"Le proxy copie sans lire","From now on the proxy copies bytes both ways without reading them. The browser’s TLS Client Hello goes in on the laptop’s connection and comes out, byte for byte the same, on the proxy’s connection to the server. TLS runs from end to end, so the proxy learns the site’s name and the sizes, never the pages. (Some company proxies do open HTTPS, using a certificate authority installed on every company laptop; then they see everything.)":"Désormais, le proxy copie les octets dans les deux sens sans les lire. Le Client Hello TLS du navigateur entre par la connexion de l’ordinateur et ressort, identique octet pour octet, par la connexion du proxy vers le serveur. TLS va de bout en bout : le proxy apprend le nom du site et les tailles, jamais les pages. (Certains proxys d’entreprise ouvrent bien le HTTPS, grâce à une autorité de certification installée sur chaque ordinateur de l’entreprise ; ils voient alors tout.)","Proxy sees":"Le proxy voit","Site name, sizes, timing":"Nom du site, tailles, rythme","Hidden from it":"Caché pour lui","Pages, passwords, cookies":"Pages, mots de passe, cookies","TLS, laptop to server":"TLS, de l’ordinateur au serveur","the same bytes":"les mêmes octets","COPIES BYTES, CAN’T READ THEM":"COPIE LES OCTETS SANS POUVOIR LES LIRE","Any Connection":"Toute connexion","From the proxy":"Du proxy","SOCKS Proxy":"Proxy SOCKS","Socket Secure, version 5":"Socket Secure, version 5","SOCKS is a general-purpose proxy. Where an HTTP proxy understands web requests, a SOCKS proxy simply opens a connection on your behalf and copies the bytes, whatever the protocol: web, email, games, SSH. Apps use it to reach a network through one gateway, or to hide their own address; ssh -D and Tor both offer one.":"SOCKS est un proxy polyvalent. Là où un proxy HTTP comprend les requêtes web, un proxy SOCKS ouvre simplement une connexion pour vous et copie les octets, quel que soit le protocole : web, e-mail, jeux, SSH. Les applications s’en servent pour atteindre un réseau par une seule passerelle, ou pour cacher leur propre adresse ; ssh -D et Tor en proposent un.","Session (Layer 5)":"Session (couche 5)","Any TCP, and UDP":"Tout TCP, et UDP",Logins:"Identification","None, or user and password":"Aucune, ou utilisateur et mot de passe","Offered by":"Proposé par","ssh -D, Tor, proxy servers":"ssh -D, Tor, serveurs proxy","Tunnel open":"Tunnel ouvert","A few bytes, then just copying":"Quelques octets, puis rien que de la copie","Four tiny messages told the proxy where to connect; after that it only copied bytes. The website saw the proxy’s address, and because the laptop sent a name rather than an address, even the DNS lookup happened at the proxy. Press REPLAY to watch it again.":"Quatre minuscules messages ont indiqué au proxy où se connecter ; ensuite, il n’a fait que copier des octets. Le site web a vu l’adresse du proxy et, comme l’ordinateur a envoyé un nom plutôt qu’une adresse, même la requête DNS s’est faite au proxy. Appuyez sur REVOIR pour tout revoir.","4 messages, 37 bytes":"4 messages, 37 octets","DNS lookup":"Requête DNS","At the proxy":"Au proxy","Only the TLS inside":"Seul le TLS à l’intérieur","TCP to port 1080":"TCP vers le port 1080","An app set to use a SOCKS proxy (a browser, a game launcher, or a tunnel made with ssh -D) opens a TCP connection to it, port 1080. SOCKS doesn’t care what will travel inside: it can carry any TCP connection.":"Une application réglée pour utiliser un proxy SOCKS (un navigateur, un lanceur de jeux ou un tunnel créé avec ssh -D) ouvre une connexion TCP vers lui, port 1080. Peu importe à SOCKS ce qui voyagera dedans : il peut transporter n’importe quelle connexion TCP.","Any TCP connection":"N’importe quelle connexion TCP","Wants to reach":"Veut atteindre","https://www.example.com":"https://www.example.com","Version 5, and how to log in":"Version 5, et comment s’identifier","The laptop sends three bytes: version 5, one login method offered, and that method, 0: no login. The proxy answers with two: version 5, method 0. Had it chosen method 2, the app would next send a user name and password, in plain text.":"L’ordinateur envoie trois octets : version 5, une méthode d’identification proposée, et cette méthode, 0 : sans identification. Le proxy répond par deux : version 5, méthode 0. S’il avait choisi la méthode 2, l’application aurait ensuite envoyé un nom d’utilisateur et un mot de passe, en clair.","Laptop sends":"L’ordinateur envoie","05 01 00 (3 bytes)":"05 01 00 (3 octets)","Proxy answers":"Le proxy répond","05 00 (2 bytes)":"05 00 (2 octets)","None needed here":"Aucune ici",GREETING:"SALUTATION","no login, please":"sans identification, svp",METHOD:"MÉTHODE","no login needed":"pas d’identification","Where To?":"Où aller ?","Connect to www.example.com:443":"Se connecter à www.example.com:443","The laptop asks the proxy to connect to www.example.com, port 443. It gives the name rather than an address, so the proxy does the DNS lookup and the laptop needs none. The proxy opens its own TCP connection to the server, then replies: succeeded, and the address and port it connected from.":"L’ordinateur demande au proxy de se connecter à www.example.com, port 443. Il donne le nom plutôt qu’une adresse : c’est donc le proxy qui fait la requête DNS, et l’ordinateur n’en a besoin d’aucune. Le proxy ouvre sa propre connexion TCP vers le serveur, puis répond : réussite, avec l’adresse et le port d’où il s’est connecté.","www.example.com (a name)":"www.example.com (un nom)","Succeeded, from 192.0.2.80:40220":"Réussite, depuis 192.0.2.80:40220",SUCCEEDED:"RÉUSSITE","from 192.0.2.80:40220":"depuis 192.0.2.80:40220","Copied both ways, unread":"Copié dans les deux sens, sans être lu","Now the proxy just copies. The app starts TLS with the server: its Client Hello goes in on the laptop’s connection and comes out unchanged on the proxy’s, and the server’s answer comes back the same way. The server only ever sees the proxy’s address; the proxy sees only encrypted bytes.":"Le proxy ne fait plus que copier. L’application démarre TLS avec le serveur : son Client Hello entre par la connexion de l’ordinateur et ressort inchangé par celle du proxy, et la réponse du serveur revient par le même chemin. Le serveur ne voit jamais que l’adresse du proxy ; le proxy ne voit que des octets chiffrés.","The proxy’s address":"L’adresse du proxy","Encrypted bytes":"Des octets chiffrés","Same bytes":"Mêmes octets","On both connections":"Sur les deux connexions",unchanged:"inchangé","+ encrypted handshake":"+ négociation chiffrée","Version 5, 1 method: no login":"Version 5, 1 méthode : sans identification","Version 5, method chosen: no login":"Version 5, méthode choisie : sans identification","Succeeded, bound to 192.0.2.80:40220":"Réussite, liée à 192.0.2.80:40220","SOCKS5 · greeting":"SOCKS5 · salutation","Methods offered":"Méthodes proposées","0 (no login)":"0 (sans identification)","SOCKS5 · method chosen":"SOCKS5 · méthode choisie","Method chosen":"Méthode choisie","SOCKS5 · connect request":"SOCKS5 · demande de connexion","Open a TCP connection on my behalf.":"Ouvrir une connexion TCP pour mon compte.","Address type":"Type d’adresse","3 (domain name)":"3 (nom de domaine)","The proxy looks the name up itself, so the laptop needs no DNS lookup of its own.":"Le proxy résout le nom lui-même : l’ordinateur n’a besoin d’aucune requête DNS de son côté.","SOCKS5 · reply":"SOCKS5 · réponse","0 (succeeded)":"0 (réussite)","The address the proxy connects from.":"L’adresse depuis laquelle le proxy se connecte.",Offloading:"Déchargement","Reverse Proxy":"Proxy inverse","TLS (SSL) offloading":"Déchargement TLS (SSL)","A reverse proxy stands in front of a website’s servers: visitors connect to it, and it passes their requests on to an app server behind it. It can spread the load over many servers, keep copies of pages and turn away attacks. Often it also does the TLS work, decrypting HTTPS at the edge so the servers behind it speak plain HTTP. That is SSL (or TLS) offloading.":"Un proxy inverse se place devant les serveurs d’un site web : les visiteurs se connectent à lui, et il transmet leurs requêtes à un serveur d’application situé derrière. Il peut répartir la charge sur plusieurs serveurs, garder des copies des pages et repousser les attaques. Souvent, il fait aussi le travail TLS, en déchiffrant le HTTPS en bordure pour que les serveurs derrière lui parlent HTTP en clair. C’est le déchargement SSL (ou TLS).","Visitors reach":"Les visiteurs atteignent","The proxy, never the app":"Le proxy, jamais l’application","TLS ends":"TLS se termine","At the proxy (offloading)":"Au proxy (déchargement)","Plain HTTP (or TLS again)":"HTTP en clair (ou de nouveau TLS)",Adds:"Ajoute","For example":"Par exemple","nginx, HAProxy, cloud LBs":"nginx, HAProxy, répartiteurs cloud","Served from the edge":"Servi depuis la bordure","Encrypted outside, plain inside":"Chiffré dehors, en clair dedans","The laptop saw one HTTPS website. Behind it, the reverse proxy decrypted the request, asked an app server in plain HTTP over the private network and encrypted the answer for the trip back. Press REPLAY to watch it again.":"L’ordinateur a vu un seul site HTTPS. Derrière, le proxy inverse a déchiffré la requête, l’a demandée à un serveur d’application en HTTP en clair sur le réseau privé, puis a chiffré la réponse pour le retour. Appuyez sur REVOIR pour tout revoir.","Laptop ↔ proxy only":"Ordinateur ↔ proxy seulement","App learns visitor":"L’application connaît le visiteur","From X-Forwarded-For":"Par X-Forwarded-For","Certificate kept":"Certificat conservé","On the proxy":"Sur le proxy","The Front Door":"La porte d’entrée","The proxy holds the certificate":"Le proxy détient le certificat","The laptop opens https://www.example.com. The address DNS gives for the name belongs to the reverse proxy, which holds the site’s certificate and does the TLS handshake. Nothing tells the laptop there is another server behind it.":"L’ordinateur ouvre https://www.example.com. L’adresse que le DNS donne pour ce nom appartient au proxy inverse, qui détient le certificat du site et fait la négociation TLS. Rien n’indique à l’ordinateur qu’il y a un autre serveur derrière.","Laptop connects to":"L’ordinateur se connecte à","On the reverse proxy":"Sur le proxy inverse","Also called":"Aussi appelé","Load balancer, edge":"Répartiteur de charge, bordure","TLS Ends Here":"TLS s’arrête ici","Offloading: the proxy does the TLS work":"Déchargement : le proxy fait le travail TLS","The request arrives encrypted, and the reverse proxy decrypts it. That is the offloading: the TLS work is done here, once, instead of on every app server. Now the proxy can read the URL, headers and cookies, and pick a server by them.":"La requête arrive chiffrée, et le proxy inverse la déchiffre. C’est le déchargement : le travail TLS se fait ici, une fois, plutôt que sur chaque serveur d’application. Le proxy peut maintenant lire l’URL, les en-têtes et les cookies, et choisir un serveur selon eux.","At the reverse proxy":"Au proxy inverse","Proxy can read":"Le proxy peut lire","URL, headers, cookies":"URL, en-têtes, cookies","Then picks":"Puis choisit","An app server":"Un serveur d’application","TLS ENDS HERE":"TLS S’ARRÊTE ICI","In the Clear":"En clair","Passed on to the app server":"Transmise au serveur d’application","The proxy passes the request on over the data centre’s private network, as plain HTTP to port 8080. It adds X-Forwarded-For, the visitor’s address, and X-Forwarded-Proto: https, how the visitor came in; otherwise the app would see only the proxy. Anyone able to watch this private network could read it all.":"Le proxy transmet la requête sur le réseau privé du centre de données, en HTTP en clair vers le port 8080. Il ajoute X-Forwarded-For, l’adresse du visiteur, et X-Forwarded-Proto: https, la façon dont le visiteur est arrivé ; sinon l’application ne verrait que le proxy. Quiconque pourrait observer ce réseau privé pourrait tout lire.","The App Answers":"L’application répond","In plain HTTP too":"En HTTP en clair, elle aussi","The app server builds the page and answers the proxy, in plain HTTP: it never deals with TLS or certificates at all.":"Le serveur d’application construit la page et répond au proxy, en HTTP en clair : il ne s’occupe jamais de TLS ni de certificats.","text/html, 12,500 bytes":"text/html, 12,500 octets","readable inside":"lisible à l’intérieur","Encrypted Again":"De nouveau chiffré","An ordinary HTTPS answer":"Une réponse HTTPS ordinaire","The reverse proxy encrypts the answer in the TLS session it holds with the laptop and sends it on. From outside, it is an ordinary HTTPS site.":"Le proxy inverse chiffre la réponse dans la session TLS qu’il tient avec l’ordinateur et l’envoie. De l’extérieur, c’est un site HTTPS ordinaire.","Laptop sees":"L’ordinateur voit","One HTTPS server":"Un seul serveur HTTPS","App servers":"Serveurs d’application","Never handle TLS":"Ne gèrent jamais TLS",Certificates:"Certificats","Renewed in one place":"Renouvelés en un seul endroit","Three Options":"Trois options","Offload, re-encrypt or pass through":"Décharger, rechiffrer ou laisser passer","Offloading, as here, is simple and fast but leaves the inside traffic readable. Re-encrypting opens a second TLS connection from the proxy to the app server, so it stays encrypted inside too. Passing through forwards the TLS bytes without opening them: the certificate lives on the app servers, and the proxy can only choose a server by address and the name in the Client Hello, not by URL.":"Le déchargement, comme ici, est simple et rapide mais laisse le trafic interne lisible. Le rechiffrement ouvre une seconde connexion TLS du proxy vers le serveur d’application, si bien que tout reste chiffré à l’intérieur aussi. Le passage direct transmet les octets TLS sans les ouvrir : le certificat reste sur les serveurs d’application, et le proxy ne peut choisir un serveur que d’après l’adresse et le nom figurant dans le Client Hello, pas d’après l’URL.",Offload:"Déchargement","Plain HTTP inside":"HTTP en clair à l’intérieur","Re-encrypt":"Rechiffrement","TLS inside as well":"TLS à l’intérieur aussi","Pass through":"Passage direct","Proxy can’t read it":"Le proxy ne peut pas le lire","PLAIN HTTP INSIDE":"HTTP EN CLAIR À L’INTÉRIEUR","A Modern VPN":"Un VPN moderne","WireGuard (encrypted)":"WireGuard (chiffré)","TCP beyond the VPN":"TCP au-delà du VPN",Keepalive:"Keepalive","VPN Server":"Serveur VPN","A VPN carries your traffic inside an encrypted tunnel to a VPN server, which sends it on to the internet. On a café’s Wi-Fi, others see only encrypted packets going to the VPN server; websites see the VPN server’s address instead of yours. WireGuard is a modern VPN: a small amount of code, one fixed set of modern algorithms and a handshake of two messages.":"Un VPN transporte votre trafic dans un tunnel chiffré jusqu’à un serveur VPN, qui l’envoie ensuite sur Internet. Sur le Wi-Fi d’un café, les autres ne voient que des paquets chiffrés vers le serveur VPN ; les sites web voient l’adresse du serveur VPN au lieu de la vôtre. WireGuard est un VPN moderne : peu de code, un seul ensemble fixe d’algorithmes modernes et une négociation en deux messages.","UDP (51820 by default)":"UDP (51820 par défaut)","2 messages, 1 round trip":"2 messages, 1 aller-retour",Crypto:"Cryptographie",Identity:"Identité","Public keys, like SSH":"Clés publiques, comme SSH","The WireGuard whitepaper":"Le livre blanc de WireGuard","Tunnel up":"Tunnel établi","Encrypted to the VPN, plain beyond it":"Chiffré jusqu’au VPN, en clair au-delà","Two handshake messages made the keys. After that every packet the laptop sent was sealed whole inside a UDP packet to the VPN server, and the website saw only the VPN server’s address. Beyond the VPN server traffic is no better protected than without one, so HTTPS still matters. Press REPLAY to watch it again.":"Deux messages de négociation ont créé les clés. Ensuite, chaque paquet envoyé par l’ordinateur était scellé entier dans un paquet UDP vers le serveur VPN, et le site web n’a vu que l’adresse du serveur VPN. Au-delà du serveur VPN, le trafic n’est pas mieux protégé que sans lui : HTTPS reste donc important. Appuyez sur REVOIR pour tout revoir.","Others nearby see":"Les voisins voient","UDP to 192.0.2.51":"UDP vers 192.0.2.51","Websites see":"Les sites web voient","The VPN server":"Le serveur VPN","Beyond the VPN":"Au-delà du VPN","Only HTTPS protects":"Seul HTTPS protège",Overhead:"Surcoût","60 bytes + padding":"60 octets + bourrage","Set Up Once":"Configuré une fois","Keys, not passwords":"Des clés, pas des mots de passe","The laptop runs the WireGuard app with a short configuration: its own private key, the server’s public key and address (192.0.2.51, UDP port 51820), and AllowedIPs = 0.0.0.0/0, which means everything goes through the tunnel. Inside the tunnel the laptop’s address is 10.8.0.2.":"L’ordinateur exécute l’application WireGuard avec une courte configuration : sa propre clé privée, la clé publique et l’adresse du serveur (192.0.2.51, port UDP 51820), et AllowedIPs = 0.0.0.0/0, ce qui signifie que tout passe par le tunnel. Dans le tunnel, l’adresse de l’ordinateur est 10.8.0.2.","Inside address":"Adresse interne","Through the tunnel":"Par le tunnel","Everything (0.0.0.0/0)":"Tout (0.0.0.0/0)","TUNNEL ADDRESS 10.8.0.2":"ADRESSE DANS LE TUNNEL 10.8.0.2","Two messages, one round trip":"Deux messages, un aller-retour","When the laptop first has something to send, it starts a handshake: 148 bytes with a fresh public key, its own long-term key (encrypted, so only the server learns who is calling) and the time (encrypted, so a recording can’t be replayed). The server answers only keys it knows, here with 92 bytes. One round trip, and both sides have new session keys.":"Quand l’ordinateur a quelque chose à envoyer pour la première fois, il lance une négociation : 148 octets avec une clé publique neuve, sa propre clé à long terme (chiffrée, pour que seul le serveur sache qui appelle) et l’heure (chiffrée, pour qu’un enregistrement ne puisse pas être rejoué). Le serveur ne répond qu’aux clés qu’il connaît, ici avec 92 octets. Un aller-retour, et les deux côtés ont de nouvelles clés de session.",Initiation:"Initiation","Server answers":"Le serveur répond à","Only keys it knows":"Seulement les clés connues",INITIATION:"INITIATION","fresh key + identity":"clé neuve + identité",RESPONSE:"RÉPONSE","keys agreed":"clés convenues","Into the Tunnel":"Dans le tunnel","A packet inside a packet":"Un paquet dans un paquet","You open https://www.example.com; its address was looked up through the tunnel too (not shown). The first packet of the connection, a TCP SYN from 10.8.0.2 to the web server, is encrypted whole and sent inside a UDP packet to the VPN server. On the café’s Wi-Fi only the outer packet shows: from the laptop to 192.0.2.51, port 51820.":"Vous ouvrez https://www.example.com ; son adresse a elle aussi été cherchée par le tunnel (non montré). Le premier paquet de la connexion, un TCP SYN de 10.8.0.2 vers le serveur web, est chiffré entier et envoyé dans un paquet UDP vers le serveur VPN. Sur le Wi-Fi du café, seul le paquet extérieur apparaît : de l’ordinateur vers 192.0.2.51, port 51820.",Outside:"À l’extérieur","UDP to 192.0.2.51:51820":"UDP vers 192.0.2.51:51820","inside: TCP SYN to :443":"dedans : TCP SYN vers :443","Out to the Web":"Vers le web","Decrypted, then sent on":"Déchiffré, puis transmis","The VPN server decrypts the packet, swaps 10.8.0.2 for its own public address (NAT) and sends the SYN on, one hop older (TTL 127). The SYN offers a maximum segment of 1380 bytes, not 1460: the tunnel adds 60 bytes to every packet. The web server sees a visitor at 192.0.2.51 and answers there.":"Le serveur VPN déchiffre le paquet, remplace 10.8.0.2 par sa propre adresse publique (NAT) et transmet le SYN, plus vieux d’un saut (TTL 127). Le SYN propose un segment maximal de 1380 octets, pas 1460 : le tunnel ajoute 60 octets à chaque paquet. Le serveur web voit un visiteur en 192.0.2.51 et répond là.","Website sees":"Le site voit","192.0.2.51 (the VPN)":"192.0.2.51 (le VPN)","Hidden from the site":"Cachée au site","127 (one hop, the VPN)":"127 (un saut, le VPN)","from 192.0.2.51":"depuis 192.0.2.51","The Way Back":"Le chemin du retour","Sealed again, for the laptop":"Scellé à nouveau, pour l’ordinateur","The answer goes back the same way. The VPN server seals the SYN-ACK in a WireGuard packet for the laptop, which opens it and hands it to Windows as if it had come straight from the web server.":"La réponse revient par le même chemin. Le serveur VPN scelle le SYN-ACK dans un paquet WireGuard pour l’ordinateur, qui l’ouvre et le remet à Windows comme s’il venait directement du serveur web.",Counter:"Compteur","Each side counts its own":"Chaque côté compte le sien",Replays:"Rejeux","Thrown away":"Rejetés","inside: TCP SYN-ACK":"dedans : TCP SYN-ACK","Keeping It Open":"Le garder ouvert","A keepalive, and new keys":"Un keepalive, et de nouvelles clés","With nothing to send, a WireGuard tunnel goes quiet. Because the laptop is behind NAT, it is set to send an empty packet every 25 seconds (PersistentKeepalive), a keepalive of 32 bytes, so the router doesn’t forget the connection. Every two minutes a new handshake makes fresh keys, and if the laptop moves to another network, the tunnel simply carries on from its new address.":"Sans rien à envoyer, un tunnel WireGuard se tait. Comme l’ordinateur est derrière un NAT, il est réglé pour envoyer un paquet vide toutes les 25 secondes (PersistentKeepalive), un keepalive de 32 octets, pour que le routeur n’oublie pas la connexion. Toutes les deux minutes, une nouvelle négociation crée des clés neuves, et si l’ordinateur passe sur un autre réseau, le tunnel continue simplement depuis sa nouvelle adresse.","Every 25 s, 32 bytes":"Toutes les 25 s, 32 octets","New keys":"Nouvelles clés","Every 2 minutes":"Toutes les 2 minutes","New network":"Nouveau réseau","The tunnel carries on":"Le tunnel continue",KEEPALIVE:"KEEPALIVE","empty, 32 bytes":"vide, 32 octets","Message type":"Type de message","Sender index":"Index de l’émetteur","A number this side picked for the session; the other side puts it in every packet it sends back.":"Un nombre que ce côté a choisi pour la session ; l’autre côté le met dans chaque paquet qu’il renvoie.","Ephemeral key":"Clé éphémère","A new public key, made just for this handshake.":"Une nouvelle clé publique, créée pour cette seule négociation.","Encrypted static key":"Clé statique chiffrée","The laptop’s long-term public key (32 bytes) and a 16-byte tag, encrypted: only the server learns who is calling.":"La clé publique à long terme de l’ordinateur (32 octets) et une étiquette de 16 octets, chiffrées : seul le serveur apprend qui appelle.","Encrypted timestamp":"Horodatage chiffré","The time (12 bytes) and a tag, encrypted. An old initiation sent again is refused.":"L’heure (12 octets) et une étiquette, chiffrées. Une ancienne initiation renvoyée est refusée.","Keyed with the server’s public key: without it, the server doesn’t answer at all.":"Calculé avec la clé publique du serveur : sans elle, le serveur ne répond pas du tout.","Used only when the server is busy and asks for a cookie first.":"Utilisé seulement quand le serveur est occupé et demande d’abord un cookie.","Receiver index":"Index du destinataire","The other side’s index: which session this packet belongs to.":"L’index de l’autre côté : la session à laquelle appartient ce paquet.","The server’s new public key for this handshake.":"La nouvelle clé publique du serveur pour cette négociation.","Encrypted nothing":"Rien de chiffré","Only a tag: it proves the server holds its private key.":"Juste une étiquette : elle prouve que le serveur détient sa clé privée.","Counts up with every packet; one seen before is thrown away.":"Augmente à chaque paquet ; un paquet déjà vu est rejeté.","The whole inner packet, padded to a multiple of 16 bytes, then a 16-byte tag.":"Tout le paquet intérieur, complété jusqu’à un multiple de 16 octets, puis une étiquette de 16 octets.","then 12 bytes of padding, and the tag":"puis 12 octets de bourrage, et l’étiquette","The laptop sent it with 128; the VPN server took 1 when it passed it on.":"L’ordinateur l’a envoyé avec 128 ; le serveur VPN a retiré 1 en le transmettant.","Nothing but the 16-byte tag: an empty packet that keeps the tunnel open.":"Rien que l’étiquette de 16 octets : un paquet vide qui garde le tunnel ouvert.","ESP (encrypted)":"ESP (chiffré)","TCP beyond the gateway":"TCP au-delà de la passerelle","VPN Gateway":"Passerelle VPN","IP Security":"Sécurité IP","IPsec protects IP packets themselves. IKEv2 sets things up: the two sides agree on algorithms, make keys and prove who they are with certificates or other credentials. Then ESP carries each packet encrypted inside another. IPsec links offices together and brings laptops into company networks, and it is built into most operating systems and firewalls.":"IPsec protège les paquets IP eux-mêmes. IKEv2 met tout en place : les deux côtés s’accordent sur les algorithmes, créent des clés et prouvent leur identité avec des certificats ou d’autres justificatifs. Ensuite ESP transporte chaque paquet chiffré dans un autre. IPsec relie des bureaux entre eux et fait entrer des ordinateurs portables dans les réseaux d’entreprise ; il est intégré à la plupart des systèmes d’exploitation et des pare-feu.","Behind NAT":"Derrière un NAT","ESP (IP protocol 50)":"ESP (protocole IP 50)","Certificates, EAP, keys":"Certificats, EAP, clés","IKE to set up, ESP to carry":"IKE pour préparer, ESP pour transporter","Four IKE messages agreed on algorithms, found the NAT, proved both identities and set up the tunnel. After that each packet travelled whole inside ESP, encrypted and checked, and wrapped in UDP to get through the home router. Press REPLAY to watch it again.":"Quatre messages IKE ont choisi les algorithmes, repéré le NAT, prouvé les deux identités et monté le tunnel. Ensuite, chaque paquet a voyagé entier dans ESP, chiffré et vérifié, et enveloppé dans UDP pour traverser le routeur de la maison. Appuyez sur REVOIR pour tout revoir.","IKE messages":"Messages IKE","4 (2 exchanges)":"4 (2 échanges)","NAT traversal":"Traversée de NAT","One SPI each way":"Un SPI dans chaque sens","Agree on algorithms, swap keys":"Choisir les algorithmes, échanger les clés","The VPN client opens with IKE on UDP port 500. Its first message proposes the algorithms (AES-GCM with 256-bit keys, SHA-256, Curve25519) and carries a public key and a random nonce; the gateway picks the proposal and sends its own key and nonce. Both now share a secret, but neither has proved who it is yet.":"Le client VPN commence par IKE sur le port UDP 500. Son premier message propose les algorithmes (AES-GCM avec des clés de 256 bits, SHA-256, Curve25519) et porte une clé publique et un nonce aléatoire ; la passerelle choisit la proposition et envoie sa propre clé et son nonce. Tous deux partagent maintenant un secret, mais aucun n’a encore prouvé qui il est.",Proposed:"Proposé","After this":"Après cela","Shared keys, no identities":"Clés partagées, pas d’identités","proposal, key, nonce":"proposition, clé, nonce","NAT detection":"Détection du NAT","chosen proposal, key, nonce":"proposition choisie, clé, nonce","A NAT in the Way":"Un NAT au milieu","So everything moves to port 4500":"Tout passe donc au port 4500","Both messages also carried hashes of the address and port each side sent from. At the gateway they don’t match what arrived: the home router rewrote the laptop’s address on the way (NAT). ESP has no port numbers, so a NAT can’t pass it; both sides move to UDP port 4500 and wrap ESP in UDP from now on.":"Les deux messages portaient aussi des empreintes de l’adresse et du port d’où chaque côté a envoyé. À la passerelle, elles ne correspondent pas à ce qui est arrivé : le routeur de la maison a réécrit l’adresse de l’ordinateur en route (NAT). ESP n’a pas de numéros de port, donc un NAT ne peut pas le laisser passer ; les deux côtés passent au port UDP 4500 et enveloppent désormais ESP dans UDP.","Hashes of":"Empreintes de","Address and port sent from":"Adresse et port d’envoi",Mismatch:"Discordance","The router rewrote them":"Le routeur les a réécrits",Fix:"Solution","Everything over UDP 4500":"Tout par UDP 4500","NAT DETECTED":"NAT DÉTECTÉ","Prove who you are, encrypted":"Prouver qui l’on est, chiffré","Now encrypted, each side sends its identity, its certificate and a signature over everything said so far, so anyone in the middle would be caught. The laptop asks for an address inside the network and gets 10.8.0.2. The same exchange sets up the ESP tunnel itself, with its own keys and an SPI for each direction.":"Désormais chiffré, chaque côté envoie son identité, son certificat et une signature sur tout ce qui a été dit jusque-là : quiconque se serait glissé au milieu serait démasqué. L’ordinateur demande une adresse à l’intérieur du réseau et obtient 10.8.0.2. Le même échange met en place le tunnel ESP lui-même, avec ses propres clés et un SPI pour chaque sens.","UDP 4500 (NAT traversal)":"UDP 4500 (traversée de NAT)","Identity, by certificate":"Identité, par certificat","Laptop gets":"L’ordinateur obtient","10.8.0.2, and a DNS server":"10.8.0.2 et un serveur DNS","identity, certificate":"identité, certificat",signature:"signature","address 10.8.0.2":"adresse 10.8.0.2","The whole packet, encrypted":"Tout le paquet, chiffré","You open https://www.example.com, looked up through the tunnel at the DNS server the gateway gave (not shown). The SYN from 10.8.0.2 is encrypted whole into an ESP packet: an SPI that names the tunnel, a sequence number, then the encrypted packet and a check value, all inside UDP port 4500. Its UDP checksum is zero: ESP checks its own contents.":"Vous ouvrez https://www.example.com, cherché par le tunnel auprès du serveur DNS fourni par la passerelle (non montré). Le SYN de 10.8.0.2 est chiffré entier dans un paquet ESP : un SPI qui désigne le tunnel, un numéro de séquence, puis le paquet chiffré et une valeur de contrôle, le tout dans UDP port 4500. Sa somme de contrôle UDP vaut zéro : ESP vérifie lui-même son contenu.","Names the tunnel":"Désigne le tunnel","The whole IP packet":"Tout le paquet IP","62 bytes + padding":"62 octets + bourrage","Out and Back":"Aller et retour","Through the gateway and home again":"Par la passerelle, puis retour à la maison","The gateway decrypts the packet and sends the SYN on from its own address, one hop older. The answer comes back to the gateway and returns through the tunnel as another ESP packet, with the SPI for the laptop’s direction and its own sequence numbers.":"La passerelle déchiffre le paquet et transmet le SYN depuis sa propre adresse, plus vieux d’un saut. La réponse revient à la passerelle et repasse par le tunnel dans un autre paquet ESP, avec le SPI du sens de l’ordinateur et ses propres numéros de séquence.","192.0.2.51 (the gateway)":"192.0.2.51 (la passerelle)","Each direction":"Chaque sens","Its own SPI and keys":"Son propre SPI et ses clés","Which VPN?":"Quel VPN ?","IPsec or WireGuard":"IPsec ou WireGuard","IPsec is older and very flexible: it negotiates its algorithms, takes many kinds of credentials and is built into Windows, macOS, iOS, Android and most firewalls, which makes it the usual way to join a company network or link two offices. WireGuard does less, with far less code and one fixed set of algorithms.":"IPsec est plus ancien et très souple : il négocie ses algorithmes, accepte de nombreux types de justificatifs et est intégré à Windows, macOS, iOS, Android et à la plupart des pare-feu, ce qui en fait le moyen habituel de rejoindre le réseau d’une entreprise ou de relier deux bureaux. WireGuard en fait moins, avec beaucoup moins de code et un seul ensemble fixe d’algorithmes.","Built into":"Intégré à","Also links":"Relie aussi","Office to office":"Bureau à bureau",Negotiates:"Négocie","Its algorithms (WireGuard: no)":"Ses algorithmes (WireGuard : non)","Initiator SPI":"SPI de l’initiateur","Picked by the laptop: which IKE session this is.":"Choisi par l’ordinateur : de quelle session IKE il s’agit.","Responder SPI":"SPI du répondeur","0 (not known yet)":"0 (encore inconnu)","Next payload":"Type des données suivantes","Exchange type":"Type d’échange","0x08 (initiator)":"0x08 (initiateur)","Message ID":"ID du message","Each request and its response share a number; the next exchange counts up.":"Chaque requête et sa réponse partagent un numéro ; l’échange suivant l’incrémente.","SA payload":"Données SA","Next payload, length":"Type des données suivantes, longueur",Proposal:"Proposition","What the laptop offers; a real client often offers several.":"Ce que propose l’ordinateur ; un vrai client en propose souvent plusieurs.","KE payload":"Données KE","DH group":"Groupe DH","This side’s public key. From the two, both work out the same secret.":"La clé publique de ce côté. À partir des deux, chacun calcule le même secret.","Nonce payload":"Données Nonce","Notify payload":"Données Notify",Notify:"Notify",Hash:"Empreinte","A hash of the SPIs and the address and port this side sent from. If what arrives doesn’t match, a NAT changed it on the way.":"Une empreinte des SPI et de l’adresse et du port d’où ce côté a envoyé. Si ce qui arrive ne correspond pas, un NAT l’a modifié en route.","The same for the address and port it sent to.":"La même chose pour l’adresse et le port de destination.","0x20 (response)":"0x20 (réponse)","The one the server chose from the laptop’s offer.":"Celle que le serveur a choisie parmi l’offre de l’ordinateur.","Non-ESP marker":"Marqueur non-ESP","Four zero bytes: an IKE message, not an ESP packet (they share port 4500).":"Quatre octets à zéro : un message IKE, pas un paquet ESP (ils partagent le port 4500).","Encrypted payload":"Données chiffrées","Encrypted payloads":"Données chiffrées","Everything else in this message, encrypted with the keys from IKE_SA_INIT.":"Tout le reste de ce message, chiffré avec les clés d’IKE_SA_INIT.","IDi, CERT, AUTH: who the laptop is, proven":"IDi, CERT, AUTH : qui est l’ordinateur, preuve à l’appui","CP: asks for an inside address and DNS":"CP : demande une adresse interne et un DNS","SA: what to use for ESP (AES-GCM)":"SA : quoi utiliser pour ESP (AES-GCM)","TSi, TSr: which traffic goes in the tunnel":"TSi, TSr : quel trafic passe dans le tunnel","Integrity check":"Contrôle d’intégrité","IDr, CERT, AUTH: who the gateway is, proven":"IDr, CERT, AUTH : qui est la passerelle, preuve à l’appui","CP: inside address 10.8.0.2, DNS 10.8.0.1":"CP : adresse interne 10.8.0.2, DNS 10.8.0.1","SA: ESP with AES-GCM, and the SPIs":"SA : ESP avec AES-GCM, et les SPI","TSi, TSr: everything (0.0.0.0/0)":"TSi, TSr : tout (0.0.0.0/0)","0 (not used)":"0 (non utilisée)","ESP checks its own contents, so ESP carried in UDP leaves this at zero.":"ESP vérifie lui-même son contenu, donc ESP transporté dans UDP laisse ce champ à zéro.","Which tunnel (security association) this belongs to; the receiving side chose it during IKE_AUTH.":"Le tunnel (association de sécurité) auquel ceci appartient ; le côté récepteur l’a choisi pendant IKE_AUTH.","Different for every packet.":"Différent pour chaque paquet.","The whole inner packet, then padding, the pad length and the next header (4: an IPv4 packet).":"Tout le paquet intérieur, puis le bourrage, la longueur du bourrage et l’en-tête suivant (4 : un paquet IPv4).","then padding, pad length and next header (4)":"puis bourrage, longueur du bourrage et en-tête suivant (4)","Shows any change to the packet.":"Révèle toute modification du paquet.","The laptop sent it with 128; the gateway took 1 when it passed it on.":"L’ordinateur l’a envoyé avec 128 ; la passerelle a retiré 1 en le transmettant.","HTTP/3 over QUIC":"HTTP/3 sur QUIC","QUIC is a newer transport that runs over UDP and has TLS 1.3 built in. Its first packets do the transport and the encryption handshakes together, so a page request can leave after one round trip. It carries many streams at once, so one lost packet doesn’t hold up the rest, and it survives a change of network. HTTP/3 is HTTP running over QUIC.":"QUIC est un transport plus récent qui fonctionne sur UDP et intègre TLS 1.3. Ses premiers paquets font en même temps la négociation du transport et celle du chiffrement, si bien que la requête d’une page peut partir après un seul aller-retour. Il transporte de nombreux flux à la fois, de sorte qu’un paquet perdu ne retarde pas les autres, et il survit à un changement de réseau. HTTP/3, c’est HTTP sur QUIC.","Runs over":"Fonctionne sur","UDP, port 443":"UDP, port 443","TLS 1.3, always":"TLS 1.3, toujours","1 round trip (0 when returning)":"1 aller-retour (0 au retour)",Streams:"Flux","Many, independent":"Nombreux, indépendants","One round trip, then the request":"Un aller-retour, puis la requête","QUIC folded the transport and TLS handshakes into one round trip, so the request left 36 ms after the first packet; over TCP and TLS it would have waited twice as long. Everything after the first packets was encrypted, even most of each packet’s header. Press REPLAY to watch it again.":"QUIC a réuni les négociations du transport et de TLS en un seul aller-retour : la requête est partie 36 ms après le premier paquet ; avec TCP et TLS, elle aurait attendu deux fois plus. Tout ce qui a suivi les premiers paquets était chiffré, même la plus grande partie de l’en-tête de chaque paquet. Appuyez sur REVOIR pour tout revoir.","1 before the request (TCP + TLS: 2)":"1 avant la requête (TCP + TLS : 2)","Lost packet":"Paquet perdu","Holds up one stream only":"Ne retarde qu’un flux","Choosing HTTP/3":"Choisir HTTP/3","An earlier visit said it can":"Une visite précédente l’a annoncé",'On an earlier visit the server answered with Alt-Svc: h3=":443", meaning it also speaks HTTP/3 on UDP port 443 (DNS can say the same in an HTTPS record). So this time the browser skips TCP and talks QUIC.':'Lors d’une visite précédente, le serveur a répondu avec Alt-Svc: h3=":443", ce qui signifie qu’il parle aussi HTTP/3 sur le port UDP 443 (le DNS peut dire la même chose dans un enregistrement HTTPS). Cette fois, le navigateur saute donc TCP et parle QUIC.',"Learned from":"Appris par","Alt-Svc header, or DNS":"En-tête Alt-Svc, ou DNS","QUIC over UDP 443":"QUIC sur UDP 443","TLS 1.3, built in":"TLS 1.3, intégré","Initial Packets":"Paquets Initial","The Client Hello, straight away":"Le Client Hello, tout de suite","There is no separate TCP handshake: the very first packets carry the TLS Client Hello. With its post-quantum key share it is 1,880 bytes, too big for one packet, so it fills two Initial packets. Each datagram is padded to at least 1,200 bytes; a server may send back only three times what it has received, so a forged sender address can’t turn it into an amplifier.":"Il n’y a pas de négociation TCP séparée : les tout premiers paquets portent le Client Hello TLS. Avec son partage de clé post-quantique, il fait 1,880 octets, trop pour un seul paquet ; il remplit donc deux paquets Initial. Chaque datagramme est complété jusqu’à au moins 1,200 octets ; un serveur ne peut renvoyer que trois fois ce qu’il a reçu, pour qu’une adresse d’expéditeur falsifiée ne puisse pas en faire un amplificateur.","2 × 1,250 bytes":"2 × 1,250 octets","The TLS Client Hello":"Le Client Hello TLS","Readable?":"Lisible ?","Yes (Initial keys are public)":"Oui (les clés Initial sont publiques)","Client Hello, part 1":"Client Hello, partie 1","Client Hello, part 2":"Client Hello, partie 2",padding:"bourrage","Then the certificate, encrypted":"Puis le certificat, chiffré","The server answers with its Server Hello in an Initial packet. Both sides can now work out handshake keys, so the rest (the certificate, its signature and Finished) comes in Handshake packets that only the laptop can read. Four datagrams, well under three times what the laptop sent.":"Le serveur répond par son Server Hello dans un paquet Initial. Les deux côtés peuvent maintenant calculer les clés de négociation ; le reste (le certificat, sa signature et Finished) arrive donc dans des paquets Handshake que seul l’ordinateur peut lire. Quatre datagrammes, bien en dessous de trois fois ce que l’ordinateur a envoyé.","Certificate, signature, Finished":"Certificat, signature, Finished","Server limit":"Limite du serveur","3× the bytes received":"3× les octets reçus","certificate, Finished":"certificat, Finished","The request, one round trip in":"La requête, après un aller-retour","The laptop checks the certificate and sends its Finished, and in the same moment its first HTTP/3 request in a 1-RTT packet: a HEADERS frame on stream 0, its headers compressed with QPACK. One round trip after the first packet, the request is on its way; TCP and TLS together would need two.":"L’ordinateur vérifie le certificat et envoie son Finished, et au même moment sa première requête HTTP/3 dans un paquet 1-RTT : une trame HEADERS sur le flux 0, avec des en-têtes compressés par QPACK. Un aller-retour après le premier paquet, la requête est en route ; TCP et TLS ensemble en demanderaient deux.","1 (TCP + TLS: 2)":"1 (TCP + TLS : 2)","HEADERS on stream 0":"HEADERS sur le flux 0",Headers:"En-têtes","Compressed (QPACK)":"Compressés (QPACK)","HTTP/3, stream 0":"HTTP/3, flux 0","The Response":"La réponse","On its own stream":"Sur son propre flux","The server confirms the handshake is over (HANDSHAKE_DONE) and answers on stream 0: headers, then the page. Every request gets its own stream, so a lost packet holds up only the stream it belonged to. Over TCP one missing segment stalls everything behind it.":"Le serveur confirme que la négociation est terminée (HANDSHAKE_DONE) et répond sur le flux 0 : les en-têtes, puis la page. Chaque requête a son propre flux, donc un paquet perdu ne retarde que le flux auquel il appartenait. Avec TCP, un seul segment manquant bloque tout ce qui le suit.","Frames on QUIC streams":"Trames sur des flux QUIC","Holds up one stream":"Retarde un seul flux","All but a few header bits":"Tout sauf quelques bits de l’en-tête","the page":"la page","New Network":"Nouveau réseau","Known by ID, not by address":"Reconnue par son ID, pas par son adresse","A QUIC connection is known by its connection IDs, not by addresses and ports. If the laptop moves from Wi-Fi to a phone’s hotspot, its address changes but the connection carries on: the server checks the new path and continues. And on the next visit the browser can send its request in its very first packets (0-RTT).":"Une connexion QUIC est reconnue par ses identifiants de connexion, pas par des adresses et des ports. Si l’ordinateur passe du Wi-Fi au partage de connexion d’un téléphone, son adresse change mais la connexion continue : le serveur vérifie le nouveau chemin et poursuit. Et à la visite suivante, le navigateur peut envoyer sa requête dès ses tout premiers paquets (0-RTT).","Known by":"Reconnue par","Connection ID":"ID de connexion","New address":"Nouvelle adresse","The connection carries on":"La connexion continue","Next visit":"Visite suivante","0-RTT: request at once":"0-RTT : requête immédiate","SAME CONNECTION ON ANY NETWORK":"LA MÊME CONNEXION SUR N’IMPORTE QUEL RÉSEAU","Initial, CRYPTO (Client Hello, part 1)":"Initial, CRYPTO (Client Hello, partie 1)","Initial, CRYPTO (Client Hello, part 2), PADDING":"Initial, CRYPTO (Client Hello, partie 2), PADDING","Handshake, CRYPTO (Certificate, part 1)":"Handshake, CRYPTO (certificat, partie 1)","Handshake, CRYPTO (Certificate, part 2)":"Handshake, CRYPTO (certificat, partie 2)","Initial packet":"Paquet Initial","Header type":"Type d’en-tête","long header, Initial":"en-tête long, Initial","The top bits say what kind of packet this is; the last bits are disguised (header protection).":"Les bits de poids fort indiquent le type de paquet ; les derniers sont masqués (protection d’en-tête).","Destination connection ID":"ID de connexion de destination","Which connection this belongs to. Each side picks its own ID; the other writes it here.":"La connexion à laquelle il appartient. Chaque côté choisit son propre ID ; l’autre l’écrit ici.","Source connection ID":"ID de connexion source","Token length":"Longueur du jeton","No token: the server hasn’t asked this client to prove its address first.":"Pas de jeton : le serveur n’a pas demandé à ce client de prouver d’abord son adresse.","The packet number and payload. Whatever follows is another packet in the same datagram.":"Le numéro de paquet et les données. Ce qui suit est un autre paquet dans le même datagramme.","Packet number":"Numéro de paquet","Hidden by header protection, so nobody on the way can read or change it.":"Masqué par la protection d’en-tête, pour que personne en route ne puisse le lire ni le modifier.","Encrypted with keys anyone can work out from the connection ID, so it stops accidents, not eavesdroppers: the Client Hello inside can be read on the way.":"Chiffré avec des clés que n’importe qui peut calculer à partir de l’ID de connexion : cela évite les accidents, pas les indiscrets. Le Client Hello à l’intérieur peut être lu en route.","CRYPTO: Client Hello, bytes 1–1,203 of 1,880":"CRYPTO : Client Hello, octets 1–1,203 sur 1,880","SNI www.example.com, ALPN h3, X25519MLKEM768 key share":"SNI www.example.com, ALPN h3, partage de clé X25519MLKEM768","CRYPTO: Client Hello, bytes 1,204–1,880":"CRYPTO : Client Hello, octets 1,204–1,880","PADDING, up to 1,250 bytes":"PADDING, jusqu’à 1,250 octets","ACK: packets 0–1 arrived":"ACK : paquets 0–1 arrivés","CRYPTO: Server Hello, with its half of the key (1,120 bytes)":"CRYPTO : Server Hello, avec sa moitié de la clé (1,120 octets)","Handshake packet":"Paquet Handshake","long header, Handshake":"en-tête long, Handshake","Encrypted with keys from the key exchange so far.":"Chiffré avec les clés issues de l’échange de clés jusqu’ici.","CRYPTO: Encrypted Extensions, Certificate (start)":"CRYPTO : Encrypted Extensions, Certificate (début)","CRYPTO: Certificate (continued)":"CRYPTO : Certificate (suite)","CRYPTO: Certificate Verify, Finished":"CRYPTO : Certificate Verify, Finished","ACK: the server’s Initial arrived":"ACK : l’Initial du serveur est arrivé","ACK: the Handshake packets arrived":"ACK : les paquets Handshake sont arrivés","1-RTT packet":"Paquet 1-RTT","short header":"en-tête court","Only the receiver’s ID, and no length: it knows how long its own IDs are. It stays the same if the laptop changes network.":"Seulement l’ID du destinataire, sans longueur : il connaît la taille de ses propres ID. Il ne change pas si l’ordinateur change de réseau.","Encrypted with the session keys.":"Chiffré avec les clés de session.","STREAM 2: SETTINGS (the control stream)":"STREAM 2 : SETTINGS (le flux de contrôle)","STREAM 0: HEADERS, GET / (QPACK-compressed)":"STREAM 0 : HEADERS, GET / (compressé par QPACK)","HANDSHAKE_DONE: the handshake is over":"HANDSHAKE_DONE : la négociation est terminée","STREAM 0: HEADERS 200, then DATA: the page (1,000 bytes)":"STREAM 0 : HEADERS 200, puis DATA : la page (1,000 octets)","ACK: the response arrived":"ACK : la réponse est arrivée","Address Setup":"Configurer l’adresse","No IPv6 address":"Pas d’adresse IPv6","IPv6: SLAAC and neighbour discovery":"IPv6 : SLAAC et découverte des voisins","IPv6 addresses are 128 bits long, enough for every device to have its own. A device can usually set itself up with no DHCP server: it makes a link-local address, asks for a router, and builds its global address from the prefix the router advertises (SLAAC). Neighbour discovery, part of ICMPv6, finds MAC addresses and does the work ARP does for IPv4.":"Les adresses IPv6 font 128 bits, assez pour que chaque appareil ait la sienne. Un appareil peut généralement se configurer seul, sans serveur DHCP : il crée une adresse lien-local, demande un routeur et construit son adresse globale à partir du préfixe que le routeur annonce (SLAAC). La découverte des voisins, qui fait partie d’ICMPv6, trouve les adresses MAC et fait le travail qu’ARP fait pour IPv4.","128 bits":"128 bits",Addresses:"Adresses","SLAAC: no server needed":"SLAAC : aucun serveur","Replaces ARP":"Remplace ARP","Neighbour discovery":"Découverte des voisins",Optional:"Facultatif","Two addresses, no DHCP":"Deux adresses, sans DHCP","Made by the laptop itself":"Créées par l’ordinateur lui-même","The laptop made a link-local address and a global one, checked that nobody else had either, and learned its router, MTU and DNS server from a single advertisement. When packets came for it, neighbour discovery found its MAC address. Press REPLAY to watch it again.":"L’ordinateur a créé une adresse lien-local et une adresse globale, vérifié que personne d’autre n’avait l’une ni l’autre, et appris son routeur, sa MTU et son serveur DNS grâce à une seule annonce. Quand des paquets sont arrivés pour lui, la découverte des voisins a trouvé son adresse MAC. Appuyez sur REVOIR pour tout revoir.","Link-local":"Lien-local",Global:"Globale","2001:db8:1234:5678::/64 + its own ID":"2001:db8:1234:5678::/64 + son propre ID","Router, DNS":"Routeur, DNS","From one advertisement":"Grâce à une seule annonce","6, all ICMPv6":"6, tous ICMPv6","Link-Local First":"D’abord le lien-local","Every IPv6 interface gets a link-local address, usable only on its own network. The laptop makes one from fe80:: and a random-looking 64-bit interface ID. First it checks nobody already has it: a Neighbor Solicitation asking for that address, sent from :: because it can’t use the address yet. Nobody answers, so it’s the laptop’s.":"Chaque interface IPv6 reçoit une adresse lien-local, utilisable seulement sur son propre réseau. L’ordinateur en crée une à partir de fe80:: et d’un ID d’interface de 64 bits d’apparence aléatoire. Il vérifie d’abord que personne ne l’a déjà : un Neighbor Solicitation qui demande cette adresse, envoyé depuis :: parce qu’il ne peut pas encore l’utiliser. Personne ne répond, elle est donc à l’ordinateur.",Check:"Vérification","Duplicate address detection":"Détection d’adresse en double","None: the address is free":"Aucune : l’adresse est libre","IS IT TAKEN?":"DÉJÀ PRISE ?","from ::":"depuis ::","target fe80::8d2e:4f61:a9b0:7c13":"cible fe80::8d2e:4f61:a9b0:7c13","NO ANSWER: ADDRESS IS FREE":"PAS DE RÉPONSE : ADRESSE LIBRE","Any Routers?":"Des routeurs ?","A Router Solicitation":"Un Router Solicitation","Link-local addresses can’t reach the internet. The laptop sends a Router Solicitation to ff02::2, the address every router on the network listens to, with its own MAC address attached.":"Les adresses lien-local ne peuvent pas atteindre Internet. L’ordinateur envoie un Router Solicitation à ff02::2, l’adresse qu’écoutent tous les routeurs du réseau, avec sa propre adresse MAC jointe.","ff02::2 (all routers)":"ff02::2 (tous les routeurs)",Includes:"Contient","ROUTERS?":"DES ROUTEURS ?","Router Answers":"Le routeur répond","Prefix, MTU and DNS in one message":"Préfixe, MTU et DNS en un message","The router answers to ff02::1, every device on the network, with a Router Advertisement: use me as your way out for 30 minutes, here is my MAC address, the MTU is 1500, the network’s prefix is 2001:db8:1234:5678::/64 and you may make your own address in it, and ask 2001:4860:4860::8888 for DNS. Routers also send these on their own every few minutes.":"Le routeur répond à ff02::1, tous les appareils du réseau, par un Router Advertisement : utilisez-moi comme sortie pendant 30 minutes, voici mon adresse MAC, la MTU est de 1500, le préfixe du réseau est 2001:db8:1234:5678::/64 et vous pouvez y créer votre propre adresse, et demandez le DNS à 2001:4860:4860::8888. Les routeurs en envoient aussi d’eux-mêmes toutes les quelques minutes.",Prefix:"Préfixe","Make your own":"Créer la sienne","Yes (flag A)":"Oui (drapeau A)",ADVERTISEMENT:"ANNONCE","prefix 2001:db8:1234:5678::/64":"préfixe 2001:db8:1234:5678::/64","A Global Address":"Une adresse globale","Prefix + interface ID":"Préfixe + ID d’interface","The laptop joins the prefix and its interface ID into a global address, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, and checks it the same way. Windows also makes a temporary address with a random ID that changes every day, used for outgoing connections so websites can’t follow one device by its address.":"L’ordinateur assemble le préfixe et son ID d’interface en une adresse globale, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, et la vérifie de la même façon. Windows crée aussi une adresse temporaire avec un ID aléatoire qui change chaque jour, utilisée pour les connexions sortantes afin que les sites web ne puissent pas suivre un appareil grâce à son adresse.","Also made":"Crée aussi","A temporary address":"Une adresse temporaire","target the global address":"cible l’adresse globale","Neighbour Lookup":"Recherche du voisin","Who has this address? (ARP’s job)":"Qui a cette adresse ? (le travail d’ARP)","A reply from the internet arrives at the router for the laptop’s global address. To deliver it, the router needs the MAC address that goes with it: it sends a Neighbor Solicitation to the address’s solicited-node group, so only devices whose address ends the same way even look. The laptop answers with a Neighbor Advertisement carrying its MAC address.":"Une réponse venue d’Internet arrive au routeur pour l’adresse globale de l’ordinateur. Pour la livrer, le routeur a besoin de l’adresse MAC correspondante : il envoie un Neighbor Solicitation au groupe de nœud sollicité de cette adresse, si bien que seuls les appareils dont l’adresse se termine de la même façon y prêtent attention. L’ordinateur répond par un Neighbor Advertisement qui porte son adresse MAC.","Asked to":"Demandé à","Instead of":"Au lieu de","ARP broadcasts to everyone":"ARP diffuse à tous","WHO HAS?":"QUI A ?","the global address":"l’adresse globale","Ready, No DHCP":"Prêt, sans DHCP","And no NAT either":"Et sans NAT non plus","The laptop is on the internet with its own global address, and no NAT changes it on the way: the address a website sees is the laptop’s. The home router’s firewall still turns away connections nobody inside asked for. Networks that want to hand out addresses centrally can use DHCPv6 instead.":"L’ordinateur est sur Internet avec sa propre adresse globale, et aucun NAT ne la modifie en route : l’adresse que voit un site web est celle de l’ordinateur. Le pare-feu du routeur de la maison refuse toujours les connexions que personne à l’intérieur n’a demandées. Les réseaux qui veulent distribuer les adresses de façon centralisée peuvent utiliser DHCPv6 à la place.","Not needed":"Inutile",Incoming:"Entrant","Blocked by the firewall":"Bloqué par le pare-feu","Optional (flags M, O)":"Facultatif (drapeaux M, O)","ONLINE OVER IPv6":"EN LIGNE EN IPv6","A multicast MAC address: 33:33, then the last four bytes of the IPv6 address.":"Une adresse MAC multicast : 33:33, puis les quatre derniers octets de l’adresse IPv6.","Version, class, flow":"Version, classe, flux","IPv6, ordinary traffic, no flow label.":"IPv6, trafic ordinaire, sans étiquette de flux.","Payload length":"Longueur des données","What follows this 40-byte header.":"Ce qui suit cet en-tête de 40 octets.","Next header":"En-tête suivant","Hop limit":"Limite de sauts","Neighbour discovery must arrive with 255, proof that no router passed it on: it came from this network.":"La découverte des voisins doit arriver avec 255, preuve qu’aucun routeur ne l’a relayée : elle vient de ce réseau.","Unspecified: the laptop has no address it may use yet.":"Non spécifiée : l’ordinateur n’a encore aucune adresse qu’il puisse utiliser.","Solicited-node multicast: only devices whose address ends in the same 24 bits are listening.":"Multicast de nœud sollicité : seuls écoutent les appareils dont l’adresse se termine par les mêmes 24 bits.","Covers the message and both IPv6 addresses.":"Couvre le message et les deux adresses IPv6.",Target:"Cible","The address the laptop wants to use. If anyone answers, it’s taken.":"L’adresse que l’ordinateur veut utiliser. Si quelqu’un répond, elle est prise.","A link-local address: usable only on this network.":"Une adresse lien-local : utilisable seulement sur ce réseau.","Every router on this network.":"Tous les routeurs de ce réseau.","Source link-layer address":"Adresse de liaison source","The sender’s MAC address, so nobody has to ask for it.":"L’adresse MAC de l’expéditeur, pour que personne n’ait à la demander.","Every device on this network.":"Tous les appareils de ce réseau.","The hop limit devices here should put on their packets.":"La limite de sauts que les appareils d’ici doivent mettre sur leurs paquets.","M: take addresses from DHCPv6. O: take other settings from DHCPv6. Both off: this advertisement has everything.":"M : prendre les adresses auprès de DHCPv6. O : prendre les autres réglages auprès de DHCPv6. Les deux à zéro : cette annonce contient tout.","Router lifetime":"Durée de vie du routeur","How long the laptop may use this router as its way out.":"Combien de temps l’ordinateur peut utiliser ce routeur comme sortie.","Reachable time":"Temps d’accessibilité","0 (not set)":"0 (non défini)","Retransmit timer":"Minuteur de retransmission","The largest packet this network carries.":"Le plus grand paquet que ce réseau transporte.","2001:db8:1234:5678::/64, valid 86,400 s, preferred 14,400 s":"2001:db8:1234:5678::/64, valide 86,400 s, préférée 14,400 s","Flags L and A: addresses in this prefix are on this network, and devices may make their own (SLAAC).":"Drapeaux L et A : les adresses de ce préfixe sont sur ce réseau, et les appareils peuvent créer la leur (SLAAC).","2001:4860:4860::8888, for 3,600 s":"2001:4860:4860::8888, pendant 3,600 s","Recursive DNS server: which resolver to ask, so no DHCP is needed for that either.":"Serveur DNS récursif : quel résolveur interroger, si bien qu’il n’y a pas besoin de DHCP pour cela non plus.","Whose MAC address is wanted.":"L’adresse MAC recherchée.","The device this frame is for.":"L’appareil auquel cette trame est destinée.","0x60000000: solicited, override":"0x60000000 : sollicité, remplacer","Solicited: this answers a question. Override: replace any older entry for this address.":"Sollicité : ceci répond à une question. Remplacer : écraser toute entrée plus ancienne pour cette adresse.","Target link-layer address":"Adresse de liaison de la cible","The answer: the MAC address that goes with the target.":"La réponse : l’adresse MAC qui correspond à la cible.","Setting the Clock":"Mettre à l’heure","Computer clocks drift by seconds a week, and a lot depends on them: certificates have dates, logins and payments expire, logs from different machines must line up. NTP sets a clock from a time server over the internet. One small request and answer carry four timestamps, enough to work out how far off the clock is and how long the network took.":"Les horloges des ordinateurs dérivent de plusieurs secondes par semaine, et beaucoup de choses en dépendent : les certificats ont des dates, les connexions et les paiements expirent, les journaux de différentes machines doivent concorder. NTP règle une horloge auprès d’un serveur de temps via Internet. Une petite requête et sa réponse portent quatre horodatages, assez pour calculer l’écart de l’horloge et le temps qu’a mis le réseau.",Accuracy:"Précision","A few milliseconds online":"Quelques millisecondes via Internet","Clock set":"Horloge réglée","Four timestamps, one answer":"Quatre horodatages, une réponse","One request and one answer gave four timestamps. From them the laptop worked out that its clock was 0.25 s slow and that the network took 24 ms there and back, and it began easing its clock into line. Press REPLAY to watch it again.":"Une requête et une réponse ont donné quatre horodatages. Grâce à eux, l’ordinateur a calculé que son horloge retardait de 0.25 s et que le réseau avait mis 24 ms aller-retour, et il a commencé à recaler son horloge en douceur. Appuyez sur REVOIR pour tout revoir.",Offset:"Écart","250.0 ms (slow)":"250.0 ms (en retard)","Stratum 2":"Strate 2","Next check":"Prochaine vérification","Minutes to days later":"De quelques minutes à quelques jours plus tard","Clocks Drift":"Les horloges dérivent","The laptop’s clock is a little slow":"L’horloge de l’ordinateur retarde un peu","A computer keeps time with a quartz crystal that runs a little fast or slow, so clocks drift apart by seconds a week. This laptop’s clock is a quarter of a second behind. Windows sets it from time.windows.com, whose address it has already looked up by DNS.":"Un ordinateur garde l’heure avec un cristal de quartz qui avance ou retarde un peu, si bien que les horloges s’écartent de plusieurs secondes par semaine. L’horloge de cet ordinateur retarde d’un quart de seconde. Windows la règle auprès de time.windows.com, dont il a déjà cherché l’adresse par DNS.","Laptop clock":"Horloge de l’ordinateur","0.25 s slow":"0.25 s de retard","Time server":"Serveur de temps","Why it matters":"Pourquoi c’est important","Certificates, logins, logs":"Certificats, connexions, journaux","CLOCK 0.250 s SLOW":"HORLOGE EN RETARD DE 0.250 s","Ask for the Time":"Demander l’heure","T1: when the request leaves":"T1 : quand la requête part","The laptop sends a 48-byte request to port 123. It writes in the time by its own clock as the request leaves: T1, 09:40:59.750. Everything else is empty.":"L’ordinateur envoie une requête de 48 octets au port 123. Il y inscrit l’heure de sa propre horloge au moment où la requête part : T1, 09:40:59.750. Tout le reste est vide.","T1 (laptop)":"T1 (ordinateur)",Mode:"Mode","3 (client)":"3 (client)","The Answer":"La réponse","T2 and T3 from the server, T4 on arrival":"T2 et T3 du serveur, T4 à l’arrivée","The server copies T1 back, adds T2, when the request arrived, and T3, when its answer leaves, both by its own accurate clock. When the answer arrives, the laptop notes T4 by its own clock. The server is stratum 2: it sets its clock from a stratum 1 server, which has a GPS receiver or an atomic clock.":"Le serveur recopie T1 et ajoute T2, l’arrivée de la requête, et T3, le départ de sa réponse, toutes deux selon sa propre horloge précise. Quand la réponse arrive, l’ordinateur note T4 selon sa propre horloge. Le serveur est de strate 2 : il règle son horloge sur un serveur de strate 1, qui dispose d’un récepteur GPS ou d’une horloge atomique.","T4 (laptop)":"T4 (ordinateur)",Stratum:"Strate","The Offset":"L’écart","Four times, two answers":"Quatre heures, deux réponses","The time on the network, there and back, is (T4 − T1) − (T3 − T2) = 24.0 ms. The offset assumes the trip takes as long each way: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. The laptop’s clock is a quarter of a second slow. An uneven route (slower one way than the other) would skew the result by up to half the difference.":"Le temps passé sur le réseau, aller et retour, vaut (T4 − T1) − (T3 − T2) = 24.0 ms. L’écart suppose que le trajet dure autant dans chaque sens : ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. L’horloge de l’ordinateur retarde d’un quart de seconde. Un trajet inégal (plus lent dans un sens que dans l’autre) fausserait le résultat de jusqu’à la moitié de la différence.",Assumes:"Suppose","Equal time each way":"Autant de temps dans chaque sens","OFFSET +250.0 ms":"ÉCART +250.0 ms","Ease It In":"En douceur","No jumps backwards":"Jamais de retour en arrière","A small error is not fixed in one jump: the clock is run slightly fast until it catches up, so time never stops or goes backwards for running programs. Only a big error is set straight away. As a clock settles, an NTP client asks less often, from every 64 seconds up to every 17 minutes or so; Windows on its own checks time.windows.com far less often, every several hours or less.":"Une petite erreur ne se corrige pas d’un coup : l’horloge tourne un peu plus vite jusqu’à rattraper l’heure, pour que le temps ne s’arrête ni ne recule jamais pour les programmes en cours. Seule une grosse erreur est corrigée immédiatement. À mesure que l’horloge se stabilise, un client NTP interroge moins souvent, de toutes les 64 secondes jusqu’à toutes les 17 minutes environ ; Windows, de lui-même, consulte time.windows.com bien moins souvent, toutes les quelques heures voire moins.","Small offsets":"Petits écarts","Eased in gradually":"Rattrapés progressivement","Large offsets":"Grands écarts","Set at once":"Corrigés d’un coup","Asks again":"Interroge à nouveau","Less often as it settles":"Moins souvent en se stabilisant","CLOCK IN STEP":"HORLOGE À L’HEURE","Leap, version, mode":"Saut, version, mode","Mode 3: a client asking for the time.":"Mode 3 : un client qui demande l’heure.",Poll:"Intervalle d’interrogation","How often the client means to ask (2 to the power 6 seconds). It grows as the clock settles.":"La fréquence à laquelle le client compte interroger (2 puissance 6 secondes). Elle augmente à mesure que l’horloge se stabilise.",Precision:"Précision","How finely this clock can be read.":"Avec quelle finesse cette horloge peut être lue.","Root delay":"Délai jusqu’à la racine","Root dispersion":"Dispersion jusqu’à la racine","Reference ID":"ID de référence","Reference time":"Heure de référence","Origin time":"Heure d’origine","Receive time":"Heure de réception","Transmit time":"Heure d’émission","T1: when the request left, by the laptop’s own (wrong) clock.":"T1 : quand la requête est partie, selon la propre horloge (fausse) de l’ordinateur.","Mode 4: an answer from a server.":"Mode 4 : une réponse d’un serveur.","Two steps from a reference clock: it follows a stratum 1 server, which has its own GPS or atomic clock.":"À deux niveaux d’une horloge de référence : il suit un serveur de strate 1, qui a son propre GPS ou sa propre horloge atomique.","Round-trip time from this server to the reference clock.":"Temps aller-retour de ce serveur jusqu’à l’horloge de référence.","How far off this server could be, at most.":"L’écart maximal possible de ce serveur.","192.0.2.123 (its own time source)":"192.0.2.123 (sa propre source de temps)","When this server last set its own clock.":"Quand ce serveur a réglé sa propre horloge pour la dernière fois.","T1, copied from the request: the client can match the answer to its question.":"T1, recopié depuis la requête : le client peut associer la réponse à sa question.","T2: when the request arrived, by the server’s clock.":"T2 : quand la requête est arrivée, selon l’horloge du serveur.","T3: when this answer left.":"T3 : quand cette réponse est partie.",Private:"Privé","Plain DNS":"DNS en clair","DNS inside HTTPS":"DNS dans HTTPS","DNS queries inside HTTPS":"Des requêtes DNS dans HTTPS","Ordinary DNS travels in the clear: anyone on the same Wi-Fi, and your internet provider, can read every name you look up and even change the answers. DNS over HTTPS (DoH) sends the same DNS messages inside an encrypted HTTPS connection to the resolver, so on the way they look like any other web traffic. Browsers and operating systems can turn it on.":"Le DNS ordinaire circule en clair : n’importe qui sur le même Wi-Fi, ainsi que votre fournisseur d’accès, peut lire chaque nom que vous cherchez, et même modifier les réponses. DNS sur HTTPS (DoH) envoie les mêmes messages DNS dans une connexion HTTPS chiffrée vers le résolveur, si bien qu’en route ils ressemblent à n’importe quel trafic web. Les navigateurs et les systèmes d’exploitation peuvent l’activer.","Ordinary DNS messages":"Messages DNS ordinaires",Hides:"Cache","Which names you look up":"Les noms que vous cherchez",Similar:"Proche","DNS over TLS (port 853)":"DNS sur TLS (port 853)","Looked up in private":"Recherche privée","Same question, sealed":"La même question, scellée","The plain lookup could be read by anyone on the path. Over HTTPS the same DNS message was sealed inside TLS, readable only by the resolver. The resolver still sees every question, so the trust moves to it, and the site you then visit can still be seen by its address. Press REPLAY to watch it again.":"La recherche en clair pouvait être lue par n’importe qui sur le chemin. Via HTTPS, le même message DNS était scellé dans TLS, lisible seulement par le résolveur. Le résolveur voit toujours chaque question : la confiance se reporte donc sur lui, et le site que vous visitez ensuite reste visible par son adresse. Appuyez sur REVOIR pour tout revoir.","On the way":"En route","Only “HTTPS to dns.google”":"Seulement « HTTPS vers dns.google »","The resolver":"Le résolveur","Still sees every name":"Voit toujours chaque nom","The site’s address you then visit":"L’adresse du site visité ensuite","Can’t be changed on the way":"Impossible à modifier en route","Readable by anyone on the way":"Lisible par tous en route","This is the lookup from the other lessons: a UDP packet to port 53 asking for www.example.com, and the answer. Neither is encrypted, so everyone on the café’s Wi-Fi, and the internet provider, can see which names the laptop looks up, and could even answer with a false address.":"Voici la recherche des autres leçons : un paquet UDP vers le port 53 qui demande www.example.com, et la réponse. Aucun des deux n’est chiffré : tout le monde sur le Wi-Fi du café, ainsi que le fournisseur d’accès, peut voir quels noms l’ordinateur cherche, et même répondre avec une fausse adresse.","UDP port 53":"Port UDP 53","Can be changed":"Modifiable","Yes, on the way":"Oui, en route",readable:"lisible","ANYONE HERE CAN READ IT":"TOUT LE MONDE ICI PEUT LE LIRE","An HTTPS Link":"Un lien HTTPS","TCP and TLS to dns.google":"TCP et TLS vers dns.google","With DNS over HTTPS on, the browser opens an HTTPS connection to the resolver instead: TCP to port 443 and a TLS handshake for dns.google. It keeps this connection open and sends every lookup down it.":"Avec DNS sur HTTPS activé, le navigateur ouvre plutôt une connexion HTTPS vers le résolveur : TCP vers le port 443 et une négociation TLS pour dns.google. Il garde cette connexion ouverte et y fait passer chaque recherche.","dns.google (8.8.8.8)":"dns.google (8.8.8.8)","443, like any website":"443, comme n’importe quel site","Kept open":"Gardée ouverte","For every lookup":"Pour chaque recherche","Sealed Question":"Question scellée","A DNS message in an HTTP request":"Un message DNS dans une requête HTTP","The question is the same DNS message as before. It goes in an HTTP/2 request, GET /dns-query?dns= followed by the message in base64url, asking for an answer in the type application/dns-message. Inside TLS, nobody on the way can read it.":"La question est le même message DNS qu’avant. Il part dans une requête HTTP/2, GET /dns-query?dns= suivi du message en base64url, qui demande une réponse du type application/dns-message. Dans TLS, personne en route ne peut le lire.",Format:"Format","application/dns-message":"application/dns-message","Encrypted (TLS)":"Chiffrée (TLS)","DoH QUERY":"REQUÊTE DoH","inside: GET /dns-query?dns=…":"dedans : GET /dns-query?dns=…","Sealed Answer":"Réponse scellée","The DNS answer in an HTTP response":"La réponse DNS dans une réponse HTTP","The resolver answers 200 with a body of type application/dns-message: the same DNS answer as the plain lookup, A 203.0.113.10. Because it arrives through TLS from dns.google, nobody on the way could have changed it.":"Le résolveur répond 200 avec un corps de type application/dns-message : la même réponse DNS que pour la recherche en clair, A 203.0.113.10. Comme elle arrive par TLS depuis dns.google, personne en route n’a pu la modifier.","200, application/dns-message":"200, application/dns-message","The DNS answer (49 bytes)":"La réponse DNS (49 octets)",Tampering:"Falsification","Impossible on the way":"Impossible en route","DoH ANSWER":"RÉPONSE DoH","inside: A 203.0.113.10":"dedans : A 203.0.113.10","What Still Shows":"Ce qui reste visible","Hidden on the way, not from the resolver":"Caché en route, pas au résolveur","On the way, the lookups now look like any HTTPS traffic to dns.google. But the resolver itself reads every question, so you are trusting it instead of whoever runs your network. And the site you then visit is still seen by its IP address, and by its name in the TLS Client Hello unless it supports Encrypted Client Hello. DNS over TLS does the same job on port 853.":"En route, les recherches ressemblent désormais à n’importe quel trafic HTTPS vers dns.google. Mais le résolveur lui-même lit chaque question : vous lui faites confiance à lui plutôt qu’à celui qui gère votre réseau. Et le site que vous visitez ensuite reste visible par son adresse IP, et par son nom dans le Client Hello TLS, sauf s’il prend en charge Encrypted Client Hello. DNS sur TLS fait le même travail sur le port 853.","Sees every name":"Voit chaque nom","Then visible":"Visible ensuite","The site’s IP, maybe its name":"L’IP du site, peut-être son nom",Alternative:"Alternative","TRUST MOVES TO THE RESOLVER":"LA CONFIANCE PASSE AU RÉSOLVEUR","Application Data (HTTP/2: DNS query)":"Application Data (HTTP/2 : requête DNS)","Application Data (HTTP/2: DNS answer)":"Application Data (HTTP/2 : réponse DNS)","HTTP/2: the connection preface and settings, then the request":"HTTP/2 : le préambule de connexion et les réglages, puis la requête","HTTP/2: settings, the response headers, then the DNS answer":"HTTP/2 : les réglages, les en-têtes de la réponse, puis la réponse DNS","Signed Answers":"Réponses signées","Question and answer":"Question et réponse","To the name servers":"Vers les serveurs de noms","Signed answers":"Réponses signées","DNS Security Extensions":"Extensions de sécurité du DNS","Plain DNS answers can be forged: whoever answers first, or sits in the middle, can send a false address. DNSSEC lets a resolver check that an answer really comes from the domain’s owner. Every set of records is signed; each zone’s key is vouched for by its parent, up to the root, whose key resolvers have built in. DNSSEC proves answers are genuine; it doesn’t hide them.":"Les réponses DNS ordinaires peuvent être falsifiées : celui qui répond le premier, ou qui se trouve au milieu, peut envoyer une fausse adresse. DNSSEC permet à un résolveur de vérifier qu’une réponse vient bien du propriétaire du domaine. Chaque ensemble d’enregistrements est signé ; la clé de chaque zone est garantie par sa zone parente, jusqu’à la racine, dont la clé est intégrée aux résolveurs. DNSSEC prouve que les réponses sont authentiques ; il ne les cache pas.","Adds records":"Ajoute des enregistrements","Checked by":"Vérifié par","Trust anchor":"Ancre de confiance","The root’s key (built in)":"La clé de la racine (intégrée)","Hides queries":"Cache les requêtes","No (that’s DoH)":"Non (c’est le rôle de DoH)","Answer checked":"Réponse vérifiée","A chain of signatures to the root":"Une chaîne de signatures jusqu’à la racine","The resolver followed a chain: the address was signed by example.com’s key, that key by its key-signing key, which .com vouched for with a signed DS record, and .com’s key is vouched for by the root, whose key the resolver has built in. A forged answer would have broken the chain. Press REPLAY to watch it again.":"Le résolveur a suivi une chaîne : l’adresse était signée par la clé d’example.com, cette clé par sa clé de signature de clés, que .com a garantie par un enregistrement DS signé, et la clé de .com est garantie par la racine, dont le résolveur a la clé intégrée. Une réponse falsifiée aurait rompu la chaîne. Appuyez sur REVOIR pour tout revoir.","Signatures checked":"Signatures vérifiées","3 here (plus cached ones)":"3 ici (plus celles en cache)","The AD flag":"Le drapeau AD","Forged answer":"Réponse falsifiée","Fails the check":"Échoue à la vérification","Ask as Usual":"Demander comme d’habitude","The laptop’s question doesn’t change":"La question de l’ordinateur ne change pas","The laptop asks its resolver for www.example.com as always. The checking happens at the resolver, which asks the name servers with the DNSSEC OK flag set: send the signatures too.":"L’ordinateur demande www.example.com à son résolveur, comme toujours. La vérification se fait au résolveur, qui interroge les serveurs de noms avec le drapeau DNSSEC OK : envoyez aussi les signatures.","Checking done by":"Vérification faite par","The resolver (8.8.8.8)":"Le résolveur (8.8.8.8)","Resolver sets":"Le résolveur active","Signed Answer":"Réponse signée","An RRSIG comes with the A record":"Un RRSIG accompagne l’enregistrement A","The resolver already knows example.com’s name server from earlier lookups. That server sends the address with an RRSIG record: a signature over the A record, made with the zone’s private key. The RRSIG says which key signed it (key 47362, the zone-signing key) and when the signature expires. To check it the resolver needs that key.":"Le résolveur connaît déjà le serveur de noms d’example.com grâce à des recherches précédentes. Ce serveur envoie l’adresse avec un enregistrement RRSIG : une signature de l’enregistrement A, faite avec la clé privée de la zone. Le RRSIG indique quelle clé l’a signé (la clé 47362, la clé de signature de zone) et quand la signature expire. Pour la vérifier, le résolveur a besoin de cette clé.","RRSIG by key 47362":"RRSIG par la clé 47362",Valid:"Valide","31 Oct to 21 Nov 2026":"Du 31 oct. au 21 nov. 2026","signed by key 47362":"signé par la clé 47362","The Zone’s Keys":"Les clés de la zone","DNSKEY records, signed too":"Des enregistrements DNSKEY, signés eux aussi","The resolver asks for example.com’s keys. There are two: the zone-signing key (flags 256) that signed the A record, and the key-signing key (flags 257), which signs only the set of keys. With them the resolver checks both signatures. But who says these keys belong to example.com?":"Le résolveur demande les clés d’example.com. Il y en a deux : la clé de signature de zone (drapeaux 256), qui a signé l’enregistrement A, et la clé de signature de clés (drapeaux 257), qui ne signe que l’ensemble des clés. Avec elles, le résolveur vérifie les deux signatures. Mais qui dit que ces clés appartiennent à example.com ?","47362, zone-signing (256)":"47362, signature de zone (256)","61845, key-signing (257)":"61845, signature de clés (257)","Keys signed by":"Clés signées par","The key-signing key":"La clé de signature de clés","two keys":"deux clés","signed by key 61845":"signé par la clé 61845","Vouched by .com":"Garantie par .com","The parent’s DS record":"L’enregistrement DS de la zone parente","The parent zone answers that. The .com servers hold a DS record for example.com: a hash of its key-signing key, signed with .com’s own key. If the hash matches key 61845, the keys are example.com’s, as far as .com is concerned.":"C’est la zone parente qui répond. Les serveurs de .com détiennent un enregistrement DS pour example.com : une empreinte de sa clé de signature de clés, signée avec la propre clé de .com. Si l’empreinte correspond à la clé 61845, les clés sont bien celles d’example.com, du point de vue de .com.","Hash of key 61845":"Empreinte de la clé 61845","Signed by":"Signé par",".com (key 19718)":".com (clé 19718)",Matches:"Correspond à","hash of key 61845":"empreinte de la clé 61845","signed by .com":"signé par .com","Up to the Root":"Jusqu’à la racine","Where the chain ends":"Là où la chaîne s’arrête","The same goes on above: .com’s keys are vouched for by a DS record in the root zone, signed by the root’s key, and that key is built into every validating resolver: the trust anchor. The resolver had those links cached, so the chain is complete: root → .com → example.com → the address.":"Il en va de même plus haut : les clés de .com sont garanties par un enregistrement DS dans la zone racine, signé par la clé de la racine, et cette clé est intégrée à chaque résolveur qui valide : c’est l’ancre de confiance. Le résolveur avait ces maillons en cache, la chaîne est donc complète : racine → .com → example.com → l’adresse.",".com’s key":"Clé de .com","Vouched for by the root":"Garantie par la racine","Root’s key":"Clé de la racine","Built in (trust anchor)":"Intégrée (ancre de confiance)","Root → .com → example.com":"Racine → .com → example.com","CHAIN OF TRUST CHECKED":"CHAÎNE DE CONFIANCE VÉRIFIÉE","A Checked Answer":"Une réponse vérifiée","With the AD flag":"Avec le drapeau AD","The resolver answers the laptop with the address and the AD flag: authenticated data. Had any signature failed, the laptop would have got an error (SERVFAIL) instead of a forged address. DNSSEC doesn’t hide the question or the answer; for that there is DNS over HTTPS.":"Le résolveur répond à l’ordinateur avec l’adresse et le drapeau AD : données authentifiées. Si une signature avait échoué, l’ordinateur aurait reçu une erreur (SERVFAIL) au lieu d’une fausse adresse. DNSSEC ne cache ni la question ni la réponse ; pour cela, il y a DNS sur HTTPS.",Flag:"Drapeau","AD (authenticated data)":"AD (données authentifiées)","Bad signature":"Signature invalide","SERVFAIL, no address":"SERVFAIL, pas d’adresse","AD: checked":"AD : vérifiée","UDP size 1232, DNSSEC OK = 1":"Taille UDP 1232, DNSSEC OK = 1","Says how big a UDP answer can be, and DNSSEC OK: send the signatures too.":"Indique la taille maximale d’une réponse UDP, et DNSSEC OK : envoyez aussi les signatures.","www.example.com RRSIG A, signed by example.com key 47362, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"www.example.com RRSIG A, signé par la clé 47362 d’example.com, valide du 2026-10-31 au 2026-11-21 (TTL 3,600 s)","A signature over the records above it, made with the zone’s private key.":"Une signature des enregistrements au-dessus, faite avec la clé privée de la zone.","example.com, type DNSKEY, class IN":"example.com, type DNSKEY, classe IN","example.com DNSKEY 256 (zone-signing key 47362), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 256 (clé de signature de zone 47362), ECDSA P-256 (TTL 3,600 s)","One of the zone’s public keys; whoever checks a signature needs it.":"L’une des clés publiques de la zone ; quiconque vérifie une signature en a besoin.","example.com DNSKEY 257 (key-signing key 61845), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 257 (clé de signature de clés 61845), ECDSA P-256 (TTL 3,600 s)","example.com RRSIG DNSKEY, signed by example.com key 61845, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"example.com RRSIG DNSKEY, signé par la clé 61845 d’example.com, valide du 2026-10-31 au 2026-11-21 (TTL 3,600 s)","example.com, type DS, class IN":"example.com, type DS, classe IN","example.com DS key 61845, SHA-256 digest (TTL 86,400 s)":"example.com DS clé 61845, condensé SHA-256 (TTL 86,400 s)","A hash of the child zone’s key-signing key, kept and signed by the parent zone.":"Une empreinte de la clé de signature de clés de la zone enfant, conservée et signée par la zone parente.","example.com RRSIG DS, signed by com key 19718, valid 2026-10-31 to 2026-11-21 (TTL 86,400 s)":"example.com RRSIG DS, signé par la clé 19718 de com, valide du 2026-10-31 au 2026-11-21 (TTL 86,400 s)","0x81a0: response, RD (recursion desired), RA (recursion available), AD (authenticated data)":"0x81a0 : réponse, RD (récursion souhaitée), RA (récursion disponible), AD (données authentifiées)","Wi-Fi Logins":"Connexion Wi-Fi","EAP over Wi-Fi":"EAP sur le Wi-Fi","RADIUS Server":"Serveur RADIUS","RADIUS and 802.1X (Enterprise Wi-Fi)":"RADIUS et 802.1X (Wi-Fi d’entreprise)","At home everyone shares one Wi-Fi password. Offices, universities and eduroam use WPA2- or WPA3-Enterprise instead: each person or device logs in with its own account or certificate, checked by a RADIUS server. The access point knows no passwords. It passes the login, a series of EAP messages, between the laptop and the server, and lets the laptop in only when the server says yes.":"À la maison, tout le monde partage un mot de passe Wi-Fi. Les bureaux, les universités et eduroam utilisent plutôt WPA2- ou WPA3-Enterprise : chaque personne ou appareil se connecte avec son propre compte ou certificat, vérifié par un serveur RADIUS. Le point d’accès ne connaît aucun mot de passe. Il transmet la connexion, une série de messages EAP, entre l’ordinateur et le serveur, et ne laisse entrer l’ordinateur que lorsque le serveur dit oui.","EAP (here EAP-TLS)":"EAP (ici EAP-TLS)",Keys:"Clés","Different for every login":"Différentes à chaque connexion","Let in":"Admis","Its own login, its own keys":"Sa propre connexion, ses propres clés","The laptop proved who it was with its certificate. The RADIUS server checked it and told the access point to let it in, on VLAN 20, with a key for this login alone. The access point never saw a password: it only passed the messages on. Press REPLAY to watch it again.":"L’ordinateur a prouvé qui il était avec son certificat. Le serveur RADIUS l’a vérifié et a dit au point d’accès de le laisser entrer, sur le VLAN 20, avec une clé réservée à cette connexion. Le point d’accès n’a jamais vu de mot de passe : il n’a fait que transmettre les messages. Appuyez sur REVOIR pour tout revoir.","EAP-TLS (certificates)":"EAP-TLS (certificats)","17, then the 4-way handshake":"17, puis la négociation en 4 temps","20 (staff)":"20 (personnel)","A user leaves":"Quelqu’un part","Disable one account":"On désactive un compte","Who Are You?":"Qui êtes-vous ?","The access point asks for an identity":"Le point d’accès demande une identité","The laptop has joined “Office”, a WPA2-Enterprise network, but until it has logged in the access point passes on nothing except login messages. It asks who the laptop is with an EAP Identity request, and the laptop answers alex@example.org. The access point knows no accounts: it will pass the answer on to the RADIUS server.":"L’ordinateur a rejoint « Office », un réseau WPA2-Enterprise, mais tant qu’il ne s’est pas connecté, le point d’accès ne laisse passer que des messages de connexion. Il demande qui est l’ordinateur avec une requête EAP Identity, et l’ordinateur répond alex@example.org. Le point d’accès ne connaît aucun compte : il transmettra la réponse au serveur RADIUS.","Before login":"Avant la connexion","Only EAP gets through":"Seul EAP passe","IDENTITY?":"IDENTITÉ ?","EAP Identity request":"Requête EAP Identity",IDENTITY:"IDENTITÉ","Ask RADIUS":"Demander à RADIUS","The login goes to the server":"La connexion part vers le serveur","The access point copies the EAP message into a RADIUS Access-Request and sends it to the RADIUS server on UDP port 1812, with the laptop’s MAC address and the network’s name. A secret that only the two of them share protects every packet. The server answers with an Access-Challenge: the next message for the laptop, which is “start EAP-TLS”.":"Le point d’accès recopie le message EAP dans un Access-Request RADIUS et l’envoie au serveur RADIUS sur le port UDP 1812, avec l’adresse MAC de l’ordinateur et le nom du réseau. Un secret que seuls ces deux-là partagent protège chaque paquet. Le serveur répond par un Access-Challenge : le prochain message pour l’ordinateur, à savoir « démarrer EAP-TLS ».","RADIUS server, UDP 1812":"Serveur RADIUS, UDP 1812","A shared secret":"Un secret partagé","from the access point":"depuis le point d’accès","EAP-TLS start":"démarrage d’EAP-TLS","TLS START":"DÉMARRAGE TLS","TLS Inside EAP":"TLS dans EAP","The server proves who it is":"Le serveur prouve qui il est","The laptop and the server now run a TLS 1.3 handshake inside EAP; the access point repacks each message, EAPOL over the air and RADIUS on the wire. The server sends its certificate and asks for the laptop’s. The laptop checks that it was issued by the company’s own certificate authority to radius.example.org. That check is what stops a fake access point from catching the login.":"L’ordinateur et le serveur font maintenant une négociation TLS 1.3 dans EAP ; le point d’accès réemballe chaque message, en EAPOL dans les airs et en RADIUS sur le câble. Le serveur envoie son certificat et demande celui de l’ordinateur. L’ordinateur vérifie qu’il a été émis par l’autorité de certification de l’entreprise pour radius.example.org. C’est cette vérification qui empêche un faux point d’accès de capturer la connexion.","TLS 1.3, inside EAP":"TLS 1.3, dans EAP","Its certificate":"Son certificat","Laptop checks":"L’ordinateur vérifie","Issuer and name":"L’émetteur et le nom","TLS inside EAP":"TLS dans EAP","certificate (encrypted)":"certificat (chiffré)","Laptop’s Proof":"La preuve de l’ordinateur","Its own certificate":"Son propre certificat","The laptop answers with its own certificate, which the company issued for this user, and a signature made with its private key; the key never leaves the laptop. No password is involved. The server checks the certificate and the signature and looks up the account. Many networks, eduroam among them, use a password instead, sent inside the TLS tunnel (PEAP or EAP-TTLS).":"L’ordinateur répond avec son propre certificat, que l’entreprise a émis pour cet utilisateur, et une signature faite avec sa clé privée ; la clé ne quitte jamais l’ordinateur. Aucun mot de passe n’intervient. Le serveur vérifie le certificat et la signature, puis cherche le compte. Beaucoup de réseaux, dont eduroam, utilisent plutôt un mot de passe, envoyé dans le tunnel TLS (PEAP ou EAP-TTLS).","Its certificate, a signature":"Son certificat, une signature","None with EAP-TLS":"Aucun avec EAP-TLS","Or instead":"Ou à la place","PEAP: a password in TLS":"PEAP : un mot de passe dans TLS",CERTIFICATE:"CERTIFICAT","laptop’s certificate":"certificat de l’ordinateur","Handshake Done":"Négociation terminée","Nothing more to send":"Plus rien à envoyer","With TLS 1.3 the server then sends one tiny encrypted message, a single zero byte, to say the handshake is over, and the laptop answers with an empty EAP message. Both ends now hold the same 64 bytes of key material, worked out during the handshake. Nobody on the way has seen it, not even the access point.":"Avec TLS 1.3, le serveur envoie alors un minuscule message chiffré, un seul octet nul, pour dire que la négociation est terminée, et l’ordinateur répond par un message EAP vide. Les deux extrémités détiennent maintenant les mêmes 64 octets de matériel de clé, calculés pendant la négociation. Personne en route ne l’a vu, pas même le point d’accès.","Server sends":"Le serveur envoie","One encrypted 0 byte":"Un octet 0 chiffré","An empty EAP-TLS reply":"Une réponse EAP-TLS vide","Both hold":"Les deux détiennent","64 bytes of key material":"64 octets de matériel de clé","handshake over":"négociation terminée","one encrypted byte":"un octet chiffré",EMPTY:"VIDE","nothing more":"plus rien","empty EAP-TLS":"EAP-TLS vide","And a key for the access point":"Et une clé pour le point d’accès","The server answers Access-Accept. Inside are EAP Success for the laptop; the first 32 bytes of the key material for the access point, encrypted with the shared secret (MS-MPPE-Recv-Key); and VLAN 20, so this user lands on the staff network. The same access point could put another user on another VLAN.":"Le serveur répond Access-Accept. On y trouve EAP Success pour l’ordinateur ; les 32 premiers octets du matériel de clé pour le point d’accès, chiffrés avec le secret partagé (MS-MPPE-Recv-Key) ; et le VLAN 20, pour que cet utilisateur arrive sur le réseau du personnel. Le même point d’accès pourrait placer un autre utilisateur sur un autre VLAN.","AP gets":"Le point d’accès reçoit","The key (MS-MPPE-Recv-Key)":"La clé (MS-MPPE-Recv-Key)","key, VLAN 20":"clé, VLAN 20","4-Way Handshake":"Négociation en 4 temps","As at home, from a different key":"Comme à la maison, à partir d’une autre clé","The access point and the laptop now hold the same 32-byte key, the PMK. What follows is the 4-way handshake from the Wi-Fi lesson; only the PMK’s origin differs. At home it comes from the shared password, here from this one login, so every user gets different keys.":"Le point d’accès et l’ordinateur détiennent maintenant la même clé de 32 octets, la PMK. La suite est la négociation en 4 temps de la leçon sur le Wi-Fi ; seule l’origine de la PMK change. À la maison, elle vient du mot de passe partagé ; ici, de cette connexion précise, si bien que chaque utilisateur reçoit des clés différentes.","PMK from":"PMK issue de","This login":"Cette connexion","At home":"À la maison","From the shared password":"Du mot de passe partagé","Encrypted data (CCMP)":"Données chiffrées (CCMP)","group key, MIC":"clé de groupe, MIC","Why Enterprise":"Pourquoi Enterprise","One account per person":"Un compte par personne","When someone leaves, their account is disabled and nobody else changes a password. Every login gets its own keys, so users can’t read each other’s traffic, and the RADIUS server records who connected and when. eduroam works the same way: a visitor’s login for user@their-university is passed from RADIUS server to RADIUS server until it reaches their own university.":"Quand quelqu’un part, son compte est désactivé et personne d’autre n’a à changer de mot de passe. Chaque connexion reçoit ses propres clés : les utilisateurs ne peuvent pas lire le trafic des autres, et le serveur RADIUS enregistre qui s’est connecté et quand. eduroam fonctionne de la même façon : la connexion d’un visiteur sous user@their-university passe de serveur RADIUS en serveur RADIUS jusqu’à atteindre sa propre université.","Different for every user":"Différentes pour chaque utilisateur",eduroam:"eduroam","Login passed home":"La connexion rentre à la maison","ONE ACCOUNT PER PERSON":"UN COMPTE PAR PERSONNE","Access-Challenge id=82: Server Hello, certificate":"Access-Challenge id=82 : Server Hello, certificat","Request, TLS EAP: Server Hello, encrypted handshake":"Request, TLS EAP : Server Hello, négociation chiffrée","Response, TLS EAP: encrypted handshake":"Response, TLS EAP : négociation chiffrée","Access-Request id=83: encrypted handshake":"Access-Request id=83 : négociation chiffrée","0 (EAP packet)":"0 (paquet EAP)","Carries an EAP message. The access point copies it into a RADIUS packet for the server, and back.":"Transporte un message EAP. Le point d’accès le recopie dans un paquet RADIUS pour le serveur, et inversement.","A response carries the same number as the request it answers.":"Une réponse porte le même numéro que la requête à laquelle elle répond.","Who are you?":"Qui êtes-vous ?","Who is logging in. The realm after the @ tells the RADIUS server (or the servers that pass requests on) where the account lives.":"Qui se connecte. Le domaine après le @ indique au serveur RADIUS (ou aux serveurs qui relaient les requêtes) où se trouve le compte.","Seen on the office network":"Vu sur le réseau du bureau","The server. It is on the same network, so the frame goes straight to it, not through the router.":"Le serveur. Il est sur le même réseau, donc la trame va directement à lui, sans passer par le routeur.","The access point’s wired port.":"Le port filaire du point d’accès.","Should this device be let in?":"Faut-il laisser entrer cet appareil ?","A reply carries the number of the request it answers.":"Une réponse porte le numéro de la requête à laquelle elle répond.",Authenticator:"Authentificateur","Random, new in every request.":"Aléatoire, nouveau à chaque requête.",Attributes:"Attributs","An HMAC-MD5 of the whole packet, keyed with the shared secret. Every packet that carries EAP must have one; since the Blast-RADIUS attack of 2024, it goes first.":"Un HMAC-MD5 de tout le paquet, avec le secret partagé comme clé. Tout paquet qui transporte de l’EAP doit en avoir un ; depuis l’attaque Blast-RADIUS de 2024, il vient en premier.","The identity the laptop gave.":"L’identité donnée par l’ordinateur.","The access point asking.":"Le point d’accès qui demande.","The access point’s MAC address and the network’s name.":"L’adresse MAC du point d’accès et le nom du réseau.","The laptop’s MAC address.":"L’adresse MAC de l’ordinateur.","Keep each EAP message small enough for one frame.":"Garder chaque message EAP assez petit pour une trame.","The EAP packet, passed on unchanged.":"Le paquet EAP, transmis tel quel.","The server’s network card.":"La carte réseau du serveur.","Not yet: here is the next message for the device.":"Pas encore : voici le prochain message pour l’appareil.","A hash of this reply, the request’s authenticator and the shared secret: only the real server could have made it.":"Une empreinte de cette réponse, de l’authentificateur de la requête et du secret partagé : seul le vrai serveur a pu la produire.","A TLS handshake, carried inside EAP.":"Une négociation TLS, transportée dans EAP.","0x20 (start)":"0x20 (début)","Start: the server is ready for the laptop’s Client Hello.":"Début : le serveur est prêt pour le Client Hello de l’ordinateur.","The server’s bookmark for this login: the access point sends it back with the next request.":"Le marque-page du serveur pour cette connexion : le point d’accès le renvoie avec la requête suivante.","0x80 (length included)":"0x80 (longueur incluse)","TLS length":"Longueur TLS","Longer TLS messages are split into pieces of about 1,000 bytes, each one acknowledged.":"Les messages TLS plus longs sont découpés en morceaux d’environ 1,000 octets, chacun acquitté.","TLS records":"Enregistrements TLS","The same TLS records as over TCP, only carried in EAP.":"Les mêmes enregistrements TLS que sur TCP, simplement transportés dans EAP.","Client Hello: TLS 1.3, the laptop’s key share":"Client Hello : TLS 1.3, le partage de clé de l’ordinateur","The EAP packet (1,008 bytes), split over 4 attributes of up to 253 bytes.":"Le paquet EAP (1,008 octets), réparti sur 4 attributs de 253 octets au plus.","EAP-Message, continued":"EAP-Message, suite","TLS records, continued":"Enregistrements TLS, suite","Server Hello: TLS 1.3, the server’s key share":"Server Hello : TLS 1.3, le partage de clé du serveur","Encrypted: certificate for radius.example.org, a request for the laptop’s certificate, signature, Finished":"Chiffré : certificat de radius.example.org, une demande du certificat de l’ordinateur, signature, Finished","Encrypted: the laptop’s certificate (for alex@example.org), its signature, Finished":"Chiffré : le certificat de l’ordinateur (pour alex@example.org), sa signature, Finished","The EAP packet (822 bytes), split over 4 attributes of up to 253 bytes.":"Le paquet EAP (822 octets), réparti sur 4 attributs de 253 octets au plus.","Encrypted: one 0 byte, the “commitment message”: no more handshake messages":"Chiffré : un octet 0, le « message d’engagement » : plus aucun message de négociation","0x00 (no data)":"0x00 (pas de données)","Nothing to send: an empty answer that keeps the conversation going.":"Rien à envoyer : une réponse vide qui fait avancer l’échange.","Yes: let it in.":"Oui : le laisser entrer.","Put this device on VLAN 20, the staff network.":"Placer cet appareil sur le VLAN 20, le réseau du personnel.","The first 32 bytes of the key material that both ends of the TLS handshake worked out. The access point uses it as the PMK, the starting key for the 4-way handshake.":"Les 32 premiers octets du matériel de clé calculé par les deux extrémités de la négociation TLS. Le point d’accès l’utilise comme PMK, la clé de départ de la négociation en 4 temps.","Salt, encrypted key":"Sel, clé chiffrée","Encrypted with the shared secret, so only the access point can read the key.":"Chiffrée avec le secret partagé, pour que seul le point d’accès puisse lire la clé.","The next 32 bytes of the key material. Wi-Fi doesn’t need them.":"Les 32 octets suivants du matériel de clé. Le Wi-Fi n’en a pas besoin.","The RADIUS server accepted the login.":"Le serveur RADIUS a accepté la connexion.","1: 802.1X (logins checked by a RADIUS server)":"1 : 802.1X (connexions vérifiées par un serveur RADIUS)","Shared Folders":"Dossiers partagés",Responses:"Réponses","nas (File Server)":"nas (serveur de fichiers)","Server Message Block (SMB 3)":"Server Message Block (SMB 3)","SMB is how Windows shares files and printers: \\\\server\\share in File Explorer, a mapped network drive, a NAS at home. macOS and Linux speak it too. Over one TCP connection to port 445 the client agrees on a version, logs in and connects to a share, then opens, reads, writes and closes files with numbered requests.":"SMB est la façon dont Windows partage fichiers et imprimantes : \\\\server\\share dans l’Explorateur de fichiers, un lecteur réseau, un NAS à la maison. macOS et Linux le parlent aussi. Sur une seule connexion TCP vers le port 445, le client s’accorde sur une version, se connecte et ouvre un partage, puis ouvre, lit, écrit et ferme des fichiers avec des requêtes numérotées.","TCP 445":"TCP 445","NTLM or Kerberos":"NTLM ou Kerberos",Protection:"Protection","Signing, optional encryption":"Signature, chiffrement facultatif","File read":"Fichier lu","Seven requests, one connection":"Sept requêtes, une connexion","Over one TCP connection the laptop agreed on SMB 3.1.1, logged in with NTLM without sending its password, connected to the share and read a 240 KB file with a single request. Every message after the login was signed. Press REPLAY to watch it again.":"Sur une seule connexion TCP, l’ordinateur s’est accordé sur SMB 3.1.1, s’est connecté avec NTLM sans envoyer son mot de passe, a ouvert le partage et a lu un fichier de 240 Ko en une seule requête. Chaque message après la connexion était signé. Appuyez sur REVOIR pour tout revoir.","7 on one connection":"7 sur une connexion","NTLMv2, no password sent":"NTLMv2, sans envoyer le mot de passe","240 KB in 169 segments":"240 Ko en 169 segments",Signed:"Signés","Every message after login":"Chaque message après la connexion","Port 445":"Port 445","A TCP connection to the NAS":"Une connexion TCP vers le NAS","The laptop opens \\\\nas\\Documents, a shared folder on the NAS. It finds nas’s address with a local name lookup and opens a TCP connection to port 445. The packets pass through the home router to the NAS and never leave the home network.":"L’ordinateur ouvre \\\\nas\\Documents, un dossier partagé sur le NAS. Il trouve l’adresse de nas par une recherche de nom locale et ouvre une connexion TCP vers le port 445. Les paquets passent par le routeur de la maison jusqu’au NAS et ne quittent jamais le réseau de la maison.","nas, 192.168.1.20":"nas, 192.168.1.20",Stays:"Reste","On the home network":"Sur le réseau de la maison",Negotiate:"Négociation","Agree on a version":"S’accorder sur une version","The laptop lists every SMB version it speaks, from 2.0.2 to 3.1.1, and says it requires signing. The NAS picks 3.1.1, the newest. Both sides keep a SHA-512 hash of everything exchanged from here until the login is done. It goes into the keys, so if anyone changed these messages on the way, to force an older version for instance, the login would fail.":"L’ordinateur énumère toutes les versions de SMB qu’il parle, de 2.0.2 à 3.1.1, et indique qu’il exige la signature. Le NAS choisit 3.1.1, la plus récente. Les deux côtés gardent une empreinte SHA-512 de tout ce qui s’échange d’ici la fin de la connexion. Elle entre dans les clés : si quelqu’un modifiait ces messages en route, pour imposer une version plus ancienne par exemple, la connexion échouerait.",Chosen:"Choisie","Tamper check":"Contrôle d’intégrité","SHA-512 of the exchange":"SHA-512 de l’échange","signing required":"signature obligatoire","NTLM Challenge":"Défi NTLM","The NAS sends a random number":"Le NAS envoie un nombre aléatoire","A home NAS has no domain, so there is no Kerberos: the laptop logs in with NTLM. Its first SESSION_SETUP says it wants to log in, and the NAS answers “more processing required” with a challenge of 8 random bytes. It also gives this login a session ID.":"Un NAS domestique n’a pas de domaine, donc pas de Kerberos : l’ordinateur se connecte avec NTLM. Son premier SESSION_SETUP indique qu’il veut se connecter, et le NAS répond « traitement supplémentaire nécessaire » avec un défi de 8 octets aléatoires. Il attribue aussi un ID de session à cette connexion.","NTLMv2 (in a domain: Kerberos)":"NTLMv2 (dans un domaine : Kerberos)",Challenge:"Défi","More processing required":"Traitement supplémentaire nécessaire","NTLM: let me log in":"NTLM : je veux me connecter","a session ID":"un ID de session","NTLM Response":"Réponse NTLM","Proof, not the password":"Une preuve, pas le mot de passe","The laptop answers with the user name, alex, and an NTLMv2 response: an HMAC of the challenge and a few other values, keyed with a hash of the password. The NAS has the same hash and works out the same value. The password itself never crosses the network, and both sides now have a session key to sign messages with.":"L’ordinateur répond avec le nom d’utilisateur, alex, et une réponse NTLMv2 : un HMAC du défi et de quelques autres valeurs, avec une empreinte du mot de passe comme clé. Le NAS a la même empreinte et calcule la même valeur. Le mot de passe lui-même ne traverse jamais le réseau, et les deux côtés ont maintenant une clé de session pour signer les messages.",User:"Utilisateur",alex:"alex",Sends:"Envoie","An HMAC of the challenge":"Un HMAC du défi","Never sent":"Jamais envoyé","user alex":"utilisateur alex","NTLMv2 response":"réponse NTLMv2","LOGGED IN":"CONNECTÉ",signed:"signé","Connect a Share":"Ouvrir un partage","\\\\nas\\Documents":"\\\\nas\\Documents","TREE_CONNECT asks for the share by its full name, \\\\nas\\Documents. The answer gives it a tree ID and says what this user may do there. Every message is now signed: each carries a tag over the whole message, made with a key from the login, so a changed or forged message would be caught.":"TREE_CONNECT demande le partage par son nom complet, \\\\nas\\Documents. La réponse lui attribue un ID d’arborescence et indique ce que cet utilisateur peut y faire. Chaque message est désormais signé : chacun porte une étiquette calculée sur tout le message avec une clé issue de la connexion, si bien qu’un message modifié ou falsifié serait détecté.",Share:"Partage","Every message":"Chaque message","Signed (AES-GMAC)":"Signé (AES-GMAC)","tree ID 0x2a51":"ID d’arborescence 0x2a51","Open the File":"Ouvrir le fichier","With CREATE":"Avec CREATE","SMB opens files with CREATE, which can also make new ones. This one opens report.pdf to read it, and fails if it doesn’t exist. The answer gives the file’s size and dates, and a file ID that the read and the close will use.":"SMB ouvre les fichiers avec CREATE, qui peut aussi en créer de nouveaux. Celui-ci ouvre report.pdf en lecture, et échoue s’il n’existe pas. La réponse donne la taille et les dates du fichier, et un ID de fichier que la lecture et la fermeture utiliseront.",Handle:"Handle","A 16-byte file ID":"Un ID de fichier de 16 octets","open to read":"ouvrir en lecture","file ID":"ID de fichier","Read It":"Le lire","The whole file in one request":"Tout le fichier en une requête","One READ asks for the whole file, 245,760 bytes from offset 0. It costs 4 credits, one for every 64 KB. The answer is 80 bytes of headers and then the file, in 169 TCP segments. A bigger file is read with several requests, many on their way at once, as far as the credits allow.":"Un seul READ demande tout le fichier, 245,760 octets à partir du décalage 0. Il coûte 4 crédits, un par tranche de 64 Ko. La réponse fait 80 octets d’en-têtes, puis le fichier, en 169 segments TCP. Un fichier plus gros se lit en plusieurs requêtes, dont beaucoup en route en même temps, dans la limite des crédits.","245,760 bytes from 0":"245,760 octets à partir de 0",Credits:"Crédits","4 (one per 64 KB)":"4 (un par 64 Ko)","Arrives in":"Arrive en","from offset 0":"à partir du décalage 0","Close the File":"Fermer le fichier","And keep 445 at home":"Et garder le 445 à la maison","CLOSE hands the file ID back; the connection stays open for the next file. SMB 3 can also encrypt every message with AES-GCM, for one share or a whole server. Here only signing protects the messages, so anyone on the network could read the file as it passed. Port 445 should never be reachable from the internet: the WannaCry worm (2017) spread through a flaw in the old SMB1.":"CLOSE rend l’ID de fichier ; la connexion reste ouverte pour le fichier suivant. SMB 3 peut aussi chiffrer chaque message avec AES-GCM, pour un partage ou tout un serveur. Ici, seule la signature protège les messages : n’importe qui sur le réseau pourrait lire le fichier au passage. Le port 445 ne devrait jamais être accessible depuis Internet : le ver WannaCry (2017) s’est propagé grâce à une faille de l’ancien SMB1.","SMB 3: AES-GCM, optional":"SMB 3 : AES-GCM, facultatif","Switched off: old, unsafe":"Désactivé : ancien, dangereux","Never open to the internet":"Jamais ouvert sur Internet",done:"terminé","KEEP PORT 445 OFF THE INTERNET":"GARDEZ LE PORT 445 HORS D’INTERNET","On port 445 every SMB message starts with its length, a leftover from NetBIOS.":"Sur le port 445, chaque message SMB commence par sa longueur, un reste de NetBIOS.",'0xFE "SMB" (SMB2 or 3)':'0xFE "SMB" (SMB2 ou 3)','SMB1 messages started 0xFF "SMB". SMB1 is switched off in Windows today.':'Les messages SMB1 commençaient par 0xFF "SMB". SMB1 est désactivé dans Windows aujourd’hui.',"Header size":"Taille de l’en-tête","Credit charge":"Coût en crédits","Channel sequence":"Séquence de canal","Credits asked for":"Crédits demandés","Credits limit how many requests the laptop may have waiting at once. The server hands them out.":"Les crédits limitent le nombre de requêtes que l’ordinateur peut avoir en attente à la fois. C’est le serveur qui les distribue.","Next command":"Commande suivante","0 (none chained)":"0 (aucune enchaînée)","Counts up with each request; the response carries the same number.":"Augmente à chaque requête ; la réponse porte le même numéro.","0 (no share yet)":"0 (pas encore de partage)","Session ID":"ID de session","0 (not logged in yet)":"0 (pas encore connecté)","zeros (not signed)":"zéros (non signé)","Structure size":"Taille de la structure","Dialect count":"Nombre de dialectes","Security mode":"Mode de sécurité","0x0002 (signing required)":"0x0002 (signature obligatoire)","Recent versions of Windows 11 require signing by default.":"Les versions récentes de Windows 11 exigent la signature par défaut.","DFS, leases, large reads and writes, multichannel, persistent handles, directory leases, encryption.":"DFS, baux, grandes lectures et écritures, multicanal, handles persistants, baux de répertoire, chiffrement.","Client GUID":"GUID du client","A random ID for this computer.":"Un ID aléatoire pour cet ordinateur.","Negotiate contexts":"Contextes de négociation","at offset 112, 4 of them":"au décalage 112, au nombre de 4",Dialects:"Dialectes","Every version the laptop speaks. The server picks the newest it also knows.":"Toutes les versions que parle l’ordinateur. Le serveur choisit la plus récente qu’il connaît aussi.",Contexts:"Contextes","SMB 3.1.1 extras, each in its own small block.":"Compléments de SMB 3.1.1, chacun dans son petit bloc.","Pre-authentication integrity: SHA-512, and a 32-byte random salt":"Intégrité de pré-authentification : SHA-512 et un sel aléatoire de 32 octets","Encryption: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM":"Chiffrement : AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM","Signing: AES-GMAC, AES-CMAC, HMAC-SHA256":"Signature : AES-GMAC, AES-CMAC, HMAC-SHA256","The server’s name: nas":"Le nom du serveur : nas","Credits granted":"Crédits accordés","0x00000001 (response)":"0x00000001 (réponse)","0x0001 (signing enabled)":"0x0001 (signature activée)",Dialect:"Dialecte","The newest version both sides speak.":"La version la plus récente que parlent les deux côtés.","Context count":"Nombre de contextes","Server GUID":"GUID du serveur","Leases, large reads and writes.":"Baux, grandes lectures et écritures.","Largest read, write":"Lecture et écriture maximales","8 MB each":"8 Mo chacune","The most data one request may carry: transactions, reads and writes.":"Le plus de données qu’une requête peut porter : transactions, lectures et écritures.","System time":"Heure système","7 Nov 2026, 09:41:00":"7 nov. 2026, 09:41:00","Security buffer":"Tampon de sécurité","Context offset":"Décalage des contextes","Security blob":"Blob de sécurité","GSS-API and SPNEGO wrapping, around NTLMSSP.":"Enveloppe GSS-API et SPNEGO autour de NTLMSSP.","The login methods the server accepts: NTLMSSP":"Les méthodes de connexion acceptées par le serveur : NTLMSSP","Pre-authentication integrity: SHA-512, and the server’s own salt":"Intégrité de pré-authentification : SHA-512 et le sel du serveur","Encryption: AES-128-GCM":"Chiffrement : AES-128-GCM","Signing: AES-GMAC":"Signature : AES-GMAC","0x02 (signing required)":"0x02 (signature obligatoire)","Previous session":"Session précédente","NTLMSSP NEGOTIATE: the NTLM options the laptop supports":"NTLMSSP NEGOTIATE : les options NTLM que l’ordinateur prend en charge","Not an error: the login needs another round.":"Ce n’est pas une erreur : la connexion demande un tour de plus.","The server’s number for this login, from now on in every message.":"Le numéro du serveur pour cette connexion, désormais dans chaque message.","Session flags":"Drapeaux de session","NTLMSSP CHALLENGE: an 8-byte random challenge":"NTLMSSP CHALLENGE : un défi aléatoire de 8 octets","The NAS’s names and its clock":"Les noms du NAS et son horloge","NTLMSSP AUTH: user alex, computer ALEX-PC":"NTLMSSP AUTH : utilisateur alex, ordinateur ALEX-PC","NTLMv2 response: an HMAC of the challenge, keyed with a hash of the password":"Réponse NTLMv2 : un HMAC du défi, avec une empreinte du mot de passe comme clé","A key for signing, encrypted":"Une clé de signature, chiffrée","0x00000009 (response, signed)":"0x00000009 (réponse, signée)","AES-GMAC over the whole message, with a key from the login: a changed or forged message would be caught.":"AES-GMAC sur tout le message, avec une clé issue de la connexion : un message modifié ou falsifié serait détecté.","The login is complete.":"La connexion est terminée.","0x00000008 (signed)":"0x00000008 (signé)","Server and share name, in UTF-16.":"Nom du serveur et du partage, en UTF-16.","The number for this share; later requests carry it.":"Le numéro de ce partage ; les requêtes suivantes le portent.","Share type":"Type de partage","1 (disk)":"1 (disque)","Share flags":"Drapeaux du partage","Encryption not required for this share; signing still protects every message.":"Chiffrement non exigé pour ce partage ; la signature protège toujours chaque message.","0x001f01ff (full control)":"0x001f01ff (contrôle total)","What this user may do in the share.":"Ce que cet utilisateur peut faire dans le partage.","Oplock, impersonation":"Oplock, emprunt d’identité","none, 2 (impersonation)":"aucun, 2 (emprunt d’identité)","Desired access":"Accès demandé","0x00120089 (read)":"0x00120089 (lecture)","Read the data, its attributes and its permissions.":"Lire les données, leurs attributs et leurs autorisations.","File attributes":"Attributs du fichier","Share access":"Accès partagé","0x00000001 (read)":"0x00000001 (lecture)","Others may read the file while it is open, but not change it.":"D’autres peuvent lire le fichier tant qu’il est ouvert, mais pas le modifier.",Disposition:"Disposition","1 (open, fail if missing)":"1 (ouvrir, échouer s’il manque)","0x00000040 (a file, not a folder)":"0x00000040 (un fichier, pas un dossier)",Name:"Nom","Create contexts":"Contextes de création","File name":"Nom du fichier","Relative to the share.":"Relatif au partage.","Oplock, flags":"Oplock, drapeaux","none, 0":"aucun, 0",Action:"Action","1 (opened)":"1 (ouvert)",Times:"Dates","created, accessed, written, changed":"création, accès, écriture, modification","Windows FILETIME: 100-nanosecond steps since 1601.":"FILETIME Windows : pas de 100 nanosecondes depuis 1601.","Allocation size":"Taille allouée","File size":"Taille du fichier","0x00000020 (archive)":"0x00000020 (archive)","File ID":"ID de fichier","The handle for the open file: reads and the close name it.":"Le handle du fichier ouvert : les lectures et la fermeture le désignent.","A big read costs one credit per 64 KB.":"Une grosse lecture coûte un crédit par tranche de 64 Ko.","Padding, flags":"Remplissage, drapeaux","Where the server should put the data in its answer: 80 bytes in, right after the headers.":"Où le serveur doit placer les données dans sa réponse : à 80 octets, juste après les en-têtes.","The whole file in one request.":"Tout le fichier en une requête.","Minimum, channel, remaining":"Minimum, canal, restant","Channel info":"Infos de canal","Data offset":"Décalage des données","Data length":"Longueur des données","Remaining, flags":"Restant, drapeaux","The file itself; its contents are not part of the lesson.":"Le fichier lui-même ; son contenu ne fait pas partie de la leçon.","The laptop didn’t ask for the file’s details, so the rest is zeros.":"L’ordinateur n’a pas demandé les détails du fichier, le reste est donc à zéro.","Times, sizes, attributes":"Dates, tailles, attributs","Talking to a PLC":"Piloter l’automate",Switch:"Commutateur","Plant network":"Réseau de l’usine","Modbus/TCP, for industrial control":"Modbus/TCP, pour le contrôle industriel","Modbus is one of the oldest and most widely used protocols in industrial control (OT, operational technology): PLCs, sensors, motor drives and meters in factories, water works and buildings speak it. A client reads and writes numbered registers and coils on a device. Modbus/TCP carries the same small messages over TCP port 502, with no login and no encryption.":"Modbus est l’un des protocoles les plus anciens et les plus répandus du contrôle industriel (OT, technologies opérationnelles) : automates, capteurs, variateurs et compteurs le parlent dans les usines, les stations d’eau et les bâtiments. Un client lit et écrit des registres et des bobines numérotés sur un appareil. Modbus/TCP transporte les mêmes petits messages sur le port TCP 502, sans connexion ni chiffrement.","1979, by Modicon":"1979, par Modicon","16-bit registers, on/off coils":"Registres de 16 bits, bobines tout-ou-rien","None built in":"Aucune intégrée","Modbus.org specifications":"Spécifications de Modbus.org","Pump running":"Pompe en marche","Simple, and wide open":"Simple, et grand ouvert","The laptop read four registers, changed a setpoint and started a pump, each with a 12-byte request and a short answer. No message carried a password and none was encrypted: Modbus trusts whoever can reach it, so the network around it has to do the protecting. Press REPLAY to watch it again.":"L’ordinateur a lu quatre registres, modifié une consigne et démarré une pompe, à chaque fois avec une requête de 12 octets et une courte réponse. Aucun message ne portait de mot de passe et aucun n’était chiffré : Modbus fait confiance à quiconque peut l’atteindre, c’est donc au réseau qui l’entoure de le protéger. Appuyez sur REVOIR pour tout revoir.","4 requests, 4 answers":"4 requêtes, 4 réponses",Biggest:"La plus grosse","17 bytes (the read answer)":"17 octets (la réponse de lecture)","Protect with":"Protéger par","Separate networks":"Des réseaux séparés","Port 502":"Port 502","A TCP connection to the PLC":"Une connexion TCP vers l’automate","A PLC (programmable logic controller) runs a small pumping station: it reads the sensors and switches the pumps. An engineer’s laptop on the plant network talks to it in Modbus/TCP, so it opens a TCP connection to port 502. In Modbus terms the laptop is the client and the PLC the server.":"Un automate (automate programmable industriel) pilote une petite station de pompage : il lit les capteurs et commande les pompes. L’ordinateur d’un ingénieur sur le réseau de l’usine lui parle en Modbus/TCP ; il ouvre donc une connexion TCP vers le port 502. Dans le vocabulaire Modbus, l’ordinateur est le client et l’automate le serveur.",Roles:"Rôles","Client asks, server answers":"Le client demande, le serveur répond","Read Registers":"Lire des registres","Function 3: four numbers":"Fonction 3 : quatre nombres","The laptop asks for 4 holding registers starting at address 0, with function code 3. The PLC answers with 8 bytes: four 16-bit numbers. What they mean (the tank level in centimetres, the temperature in tenths of a degree) is written only in the PLC’s documentation; the message carries no names and no units. An HMI screen sends reads like this every second or so.":"L’ordinateur demande 4 registres de maintien à partir de l’adresse 0, avec le code de fonction 3. L’automate répond par 8 octets : quatre nombres de 16 bits. Leur signification (le niveau de la cuve en centimètres, la température en dixièmes de degré) n’est écrite que dans la documentation de l’automate ; le message ne porte ni noms ni unités. Un écran de supervision envoie de telles lectures à peu près chaque seconde.",Function:"Fonction","4 registers from 0":"4 registres à partir de 0","function 3":"fonction 3","registers 0–3":"registres 0–3",VALUES:"VALEURS","Write a Setpoint":"Écrire une consigne","Function 6: one register":"Fonction 6 : un registre","The engineer raises the tank’s level setpoint from 4.50 m to 5.00 m: function 6, write single register, register 3, value 500. The PLC answers by repeating the request, which means done. From now on its program keeps the tank fuller.":"L’ingénieur relève la consigne de niveau de la cuve de 4.50 m à 5.00 m : fonction 6, écriture d’un registre, registre 3, valeur 500. L’automate répond en répétant la requête, ce qui veut dire « fait ». Désormais, son programme garde la cuve plus pleine.","Register 3":"Registre 3","The request, repeated":"La requête, répétée",WRITE:"ÉCRITURE","register 3 = 500":"registre 3 = 500","Start a Pump":"Démarrer une pompe","Function 5: a coil":"Fonction 5 : une bobine","Coils are single on/off outputs. Function 5 writes one: coil 0, pump 2, value 0xFF00, which means on. The PLC switches the pump on and echoes the request. In a real plant the PLC’s own program usually decides this, with safety interlocks.":"Les bobines sont des sorties tout-ou-rien individuelles. La fonction 5 en écrit une : bobine 0, pompe 2, valeur 0xFF00, qui veut dire marche. L’automate met la pompe en marche et renvoie la requête. Dans une vraie usine, c’est en général le programme de l’automate qui décide, avec des verrouillages de sécurité.","Coil 0":"Bobine 0","Pump 2: on":"Pompe 2 : marche","0xFF00 (off: 0x0000)":"0xFF00 (arrêt : 0x0000)","COIL ON":"BOBINE ACTIVÉE","coil 0: pump 2":"bobine 0 : pompe 2","pump 2 on":"pompe 2 en marche","PUMP 2 RUNNING":"POMPE 2 EN MARCHE","An Exception":"Une exception","No such register":"Registre inexistant","A request for registers that don’t exist, here 100 and 101, gets an exception: the function code with its top bit set (3 + 128 = 131) and exception code 2, illegal data address. Other codes say the function isn’t supported or the device is busy.":"Une requête sur des registres qui n’existent pas, ici 100 et 101, reçoit une exception : le code de fonction avec son bit de poids fort à 1 (3 + 128 = 131) et le code d’exception 2, adresse de données illégale. D’autres codes indiquent que la fonction n’est pas prise en charge ou que l’appareil est occupé.",Exception:"Exception",Means:"Signifie","No register there":"Pas de registre à cette adresse","registers 100–101":"registres 100–101",EXCEPTION:"EXCEPTION","code 2: no such register":"code 2 : registre inexistant","No Security":"Aucune sécurité","Anyone who can reach it":"Quiconque peut l’atteindre","Nothing in these messages says who sent them: Modbus, from 1979, has no login and no encryption, so any device that can reach port 502 can read the values and start the pump. Plants protect it with separate networks, firewalls between office and plant, lists of who may talk to each PLC, and monitoring. Modbus/TCP Security wraps the same messages in TLS, on port 802.":"Rien dans ces messages n’indique qui les a envoyés : Modbus, qui date de 1979, n’a ni connexion ni chiffrement, si bien que tout appareil qui atteint le port 502 peut lire les valeurs et démarrer la pompe. Les usines le protègent par des réseaux séparés, des pare-feu entre bureaux et usine, des listes de qui peut parler à chaque automate, et de la surveillance. Modbus/TCP Security enveloppe les mêmes messages dans TLS, sur le port 802.","Separate networks, TLS":"Réseaux séparés, TLS","NO LOGIN, NO ENCRYPTION":"NI CONNEXION NI CHIFFREMENT","Seen on the plant network":"Vu sur le réseau de l’usine","Picked by the client; the answer carries the same number.":"Choisi par le client ; la réponse porte le même numéro.","Protocol ID":"ID de protocole","The unit ID and everything after it.":"L’ID d’unité et tout ce qui suit.","Unit ID":"ID d’unité","Which device. It matters when a gateway passes requests on to devices on a serial line.":"Quel appareil. Utile quand une passerelle relaie les requêtes vers des appareils sur une ligne série.","Function code":"Code de fonction","Starting address":"Adresse de départ","Modbus counts from 0, though manuals often number the same register 40001 and up.":"Modbus compte à partir de 0, même si les manuels numérotent souvent le même registre à partir de 40001.",Quantity:"Quantité","Modbus/TCP · Read Holding Registers, answer":"Modbus/TCP · Read Holding Registers, réponse","The same number as the request.":"Le même numéro que la requête.","Byte count":"Nombre d’octets","Register 0":"Registre 0","412 (tank level, 4.12 m)":"412 (niveau de la cuve, 4.12 m)","Plain 16-bit numbers. What each one means is written in the PLC’s documentation, not in the message.":"De simples nombres de 16 bits. La signification de chacun est écrite dans la documentation de l’automate, pas dans le message.","Register 1":"Registre 1","183 (temperature, 18.3 °C)":"183 (température, 18.3 °C)","Register 2":"Registre 2","1450 (pump speed, 1,450 rpm)":"1450 (vitesse de la pompe, 1,450 tr/min)","450 (level setpoint, 4.50 m)":"450 (consigne de niveau, 4.50 m)","Register address":"Adresse du registre","3 (level setpoint)":"3 (consigne de niveau)",Value:"Valeur","Modbus/TCP · Write Single Register, answer":"Modbus/TCP · Write Single Register, réponse","The answer repeats the request: done.":"La réponse répète la requête : c’est fait.","Coil address":"Adresse de la bobine","0 (pump 2)":"0 (pompe 2)","A coil is a single on/off output. 0xFF00 switches it on.":"Une bobine est une sortie tout-ou-rien. 0xFF00 l’active.","Modbus/TCP · Write Single Coil, answer":"Modbus/TCP · Write Single Coil, réponse","Modbus/TCP · exception":"Modbus/TCP · exception","131 (3 + 128: an exception)":"131 (3 + 128 : une exception)","The top bit set: the request failed.":"Le bit de poids fort à 1 : la requête a échoué.","Exception code":"Code d’exception","There is no register at that address.":"Il n’y a aucun registre à cette adresse.","Internet Routes":"Routes d’Internet",Routes:"Routes","The laptop’s packets":"Les paquets de l’ordinateur","Border Gateway Protocol":"Protocole de passerelle de bordure","The internet is a network of networks: tens of thousands of them, run by internet providers, clouds, universities and companies, each with its own AS number. BGP is how their border routers tell each other which addresses they can reach. Every router passes on what it learns with its own number added, so each network builds its own map of the paths to every address on the internet.":"Internet est un réseau de réseaux : des dizaines de milliers, exploités par des fournisseurs d’accès, des clouds, des universités et des entreprises, chacun avec son propre numéro d’AS. BGP permet à leurs routeurs de bordure de se dire quelles adresses ils peuvent atteindre. Chaque routeur transmet ce qu’il apprend en y ajoutant son propre numéro, si bien que chaque réseau construit sa propre carte des chemins vers chaque adresse d’Internet.",Between:"Entre","Networks (ASes)":"Réseaux (AS)",Table:"Table","About a million IPv4 routes":"Environ un million de routes IPv4","Path choice":"Choix du chemin","Policy, then shortest":"La politique, puis le plus court","Route learned":"Route apprise","Announced, passed on, used":"Annoncée, relayée, utilisée","The hosting network announced its addresses, the transit network passed them on with its own number added, and the ISP’s router used that path for the laptop’s packets. When the route was withdrawn, the news spread the same way. There is no central map: every network builds its own from what its neighbours say. Press REPLAY to watch it again.":"Le réseau d’hébergement a annoncé ses adresses, le réseau de transit les a relayées en ajoutant son numéro, et le routeur du FAI a utilisé ce chemin pour les paquets de l’ordinateur. Quand la route a été retirée, la nouvelle s’est propagée de la même façon. Il n’y a pas de carte centrale : chaque réseau construit la sienne à partir de ce que disent ses voisins. Appuyez sur REVOIR pour tout revoir.",Map:"Carte","Each network makes its own":"Chaque réseau fait la sienne","RPKI and filters":"RPKI et filtres","Many Networks":"De nombreux réseaux","Each with its own number":"Chacun avec son numéro","The internet is more than 75,000 separate networks, called autonomous systems (ASes): internet providers, clouds, universities, big companies, each with a number. Here are three: the laptop’s ISP (AS 64500), a transit network that carries others’ traffic (AS 64510), and the hosting network of www.example.com (AS 64511). BGP is how their routers tell each other where every address can be reached.":"Internet compte plus de 75,000 réseaux distincts, appelés systèmes autonomes (AS) : fournisseurs d’accès, clouds, universités, grandes entreprises, chacun avec un numéro. En voici trois : le FAI de l’ordinateur (AS 64500), un réseau de transit qui achemine le trafic des autres (AS 64510) et le réseau d’hébergement de www.example.com (AS 64511). BGP permet à leurs routeurs de se dire où chaque adresse peut être atteinte.",Networks:"Réseaux","More than 75,000 ASes":"Plus de 75,000 AS",Here:"Ici","3 ASes, a router each":"3 AS, un routeur chacun",Numbers:"Numéros","TCP to port 179":"TCP vers le port 179","BGP routers don’t discover each other: engineers at both ends set each other up as neighbours. The ISP’s router opens a TCP connection to the transit router on port 179. They are directly connected, so their packets go out with a TTL of 1: they can’t cross even one more router, so the session only works between direct neighbours.":"Les routeurs BGP ne se découvrent pas tout seuls : des ingénieurs aux deux bouts les configurent comme voisins. Le routeur du FAI ouvre une connexion TCP vers le routeur de transit sur le port 179. Ils sont directement reliés, donc leurs paquets partent avec un TTL de 1 : ils ne peuvent pas franchir un seul routeur de plus, et la session ne fonctionne qu’entre voisins directs.",Neighbours:"Voisins","Set up by hand":"Configurés à la main","1: the next router only":"1 : le routeur suivant seulement","OPEN, then KEEPALIVE":"OPEN, puis KEEPALIVE","Each router sends an OPEN: its AS number, a hold time of 180 seconds, its router ID and what it supports, such as 4-byte AS numbers. Each answers with a KEEPALIVE, and the session is established. From now on a KEEPALIVE goes every 60 seconds when there’s nothing else to send; after 180 silent seconds the session would be dropped.":"Chaque routeur envoie un OPEN : son numéro d’AS, un temps de maintien de 180 secondes, son ID de routeur et ce qu’il prend en charge, comme les numéros d’AS sur 4 octets. Chacun répond par un KEEPALIVE, et la session est établie. Désormais, un KEEPALIVE part toutes les 60 secondes quand il n’y a rien d’autre à envoyer ; après 180 secondes de silence, la session serait coupée.","AS, hold time, ID":"AS, temps de maintien, ID","KEEPALIVE: established":"KEEPALIVE : établie","Hold time":"Temps de maintien","hold 180 s":"maintien 180 s","SESSION ESTABLISHED":"SESSION ÉTABLIE","Announce a Route":"Annoncer une route","The hosting network: “I have these”":"Le réseau d’hébergement : « j’ai celles-ci »","The hosting network’s router announces 203.0.113.0/24, the 256 addresses that include www.example.com, to the transit network, which it pays to carry its traffic. The UPDATE says how to get there: AS_PATH 64511, only its own network so far, and NEXT_HOP, its own address on the link between them.":"Le routeur du réseau d’hébergement annonce 203.0.113.0/24, les 256 adresses qui incluent www.example.com, au réseau de transit, qu’il paie pour acheminer son trafic. L’UPDATE dit comment y aller : AS_PATH 64511, son seul réseau pour l’instant, et NEXT_HOP, sa propre adresse sur le lien entre eux.","path 64511":"chemin 64511","Passed On":"Relayée","Each network adds its number":"Chaque réseau ajoute son numéro","The transit router accepts the route and passes it to its other neighbours, the ISP among them, with its own number added to the front: AS_PATH 64510 64511, and itself as the next hop. The ISP’s router may hear of the same prefix from several neighbours. It picks one by its own policy first (routes through paying customers before others, say), then by the shortest AS path.":"Le routeur de transit accepte la route et la transmet à ses autres voisins, dont le FAI, en ajoutant son propre numéro devant : AS_PATH 64510 64511, et lui-même comme prochain saut. Le routeur du FAI peut entendre parler du même préfixe par plusieurs voisins. Il en choisit un d’abord selon sa propre politique (par exemple les routes passant par des clients payants avant les autres), puis selon l’AS_PATH le plus court.","Best path":"Meilleur chemin","path 64510 64511":"chemin 64510 64511","ROUTE TO 203.0.113.0/24":"ROUTE VERS 203.0.113.0/24","Follow the Route":"Suivre la route","Packets go where BGP said":"Les paquets vont là où BGP l’a dit","When the laptop connects to www.example.com (its address found by DNS as usual), its packets reach the ISP, whose router now sends anything for 203.0.113.0/24 to the transit router, and the transit router sends it on to the hosting network. The answer comes back by whatever route the hosting network chose towards the laptop’s ISP: on the internet the way back is often different from the way there.":"Quand l’ordinateur se connecte à www.example.com (dont l’adresse a été trouvée par DNS comme d’habitude), ses paquets atteignent le FAI, dont le routeur envoie désormais tout ce qui va vers 203.0.113.0/24 au routeur de transit, qui le transmet au réseau d’hébergement. La réponse revient par la route que le réseau d’hébergement a choisie vers le FAI de l’ordinateur : sur Internet, le chemin du retour diffère souvent de celui de l’aller.","Way back":"Chemin du retour","Chosen separately":"Choisi séparément","the way back":"le chemin du retour",Withdrawn:"Retirée","Routes can be taken back":"Les routes peuvent être retirées","Later the hosting network takes the prefix back, as it would if a link failed: an UPDATE listing it under withdrawn routes. The transit router passes it on, and within seconds to minutes networks everywhere forget the path. A session that goes quiet past its hold time loses all its routes at once. In 2021 Facebook withdrew the routes to its own DNS servers and vanished from the internet for six hours.":"Plus tard, le réseau d’hébergement retire le préfixe, comme il le ferait si un lien tombait : un UPDATE qui le range parmi les routes retirées. Le routeur de transit le relaie, et en quelques secondes ou minutes les réseaux du monde entier oublient le chemin. Une session silencieuse au-delà de son temps de maintien perd toutes ses routes d’un coup. En 2021, Facebook a retiré les routes vers ses propres serveurs DNS et a disparu d’Internet pendant six heures.","Spreads in":"Se propage en","Seconds to minutes":"Quelques secondes à minutes","Session lost":"Session perdue","All its routes go":"Toutes ses routes disparaissent",WITHDRAW:"RETRAIT","Trust Problems":"Problèmes de confiance","BGP believes its neighbours":"BGP croit ses voisins","A router accepts what its neighbours announce. A network that announces addresses that aren’t its own, by mistake or on purpose, pulls their traffic towards it: in 2008 a Pakistani ISP took YouTube offline worldwide this way. With RPKI the holder of a prefix signs which AS may announce it, and routers that check drop any other. Filters on what each neighbour may announce do the rest.":"Un routeur accepte ce que ses voisins annoncent. Un réseau qui annonce des adresses qui ne sont pas les siennes, par erreur ou exprès, attire leur trafic vers lui : en 2008, un FAI pakistanais a ainsi mis YouTube hors ligne dans le monde entier. Avec RPKI, le détenteur d’un préfixe signe quel AS peut l’annoncer, et les routeurs qui vérifient rejettent tout autre. Des filtres sur ce que chaque voisin peut annoncer font le reste.",Risk:"Risque","Hijacks and leaks":"Détournements et fuites","Signed: who may announce":"Signé : qui peut annoncer",Also:"Aussi","Filters per neighbour":"Filtres par voisin","CHECK WHO MAY ANNOUNCE":"VÉRIFIER QUI PEUT ANNONCER","UPDATE Message: withdrawn 203.0.113.0/24":"UPDATE Message : retrait 203.0.113.0/24",Marker:"Marqueur","16 bytes of 0xFF":"16 octets de 0xFF","All ones: where a message starts.":"Que des uns : le début d’un message.","The first message on a session: who this router is and what it supports.":"Le premier message d’une session : qui est ce routeur et ce qu’il prend en charge.","This router’s network. (A 4-byte AS number goes in the capability below, with 23456 here.)":"Le réseau de ce routeur. (Un numéro d’AS sur 4 octets figure dans la capacité ci-dessous, avec 23456 ici.)","If nothing at all arrives for this long, the session is dropped. Both sides use the lower offer.":"Si rien du tout n’arrive pendant ce temps, la session est coupée. Les deux côtés retiennent l’offre la plus basse.","BGP identifier":"Identifiant BGP","The router’s ID, usually one of its addresses.":"L’ID du routeur, en général l’une de ses adresses.","Optional parameters":"Paramètres facultatifs","parameter 2, 14 bytes":"paramètre 2, 14 octets","What this router can do beyond the basics.":"Ce que ce routeur sait faire au-delà de l’essentiel.",Multiprotocol:"Multiprotocole","Which kinds of routes it will exchange on this session.":"Les types de routes qu’il échangera sur cette session.","Route refresh":"Rafraîchissement des routes","It can ask the other side to send all its routes again.":"Il peut demander à l’autre côté de lui renvoyer toutes ses routes.","4-byte AS numbers":"Numéros d’AS sur 4 octets","2-byte AS numbers ran short, so newer ones are 4 bytes long.":"Les numéros d’AS sur 2 octets ont manqué ; les nouveaux font donc 4 octets.","Only the header: “still here”. Sent when there’s nothing else to say, every third of the hold time.":"Seulement l’en-tête : « toujours là ». Envoyé quand il n’y a rien d’autre à dire, tous les tiers du temps de maintien.","Routes: paths to new addresses, and ones taken back.":"Routes : chemins vers de nouvelles adresses, et celles qui sont retirées.","Withdrawn routes":"Routes retirées","Path attributes":"Attributs de chemin","0 (IGP: from inside the network that announced it)":"0 (IGP : depuis l’intérieur du réseau qui l’a annoncée)","Every network the route has passed through, the latest first. Other things being equal, the shorter path wins; a router that finds its own number here drops the route, so routes can’t loop.":"Chaque réseau que la route a traversé, le plus récent d’abord. À égalité sur le reste, le chemin le plus court l’emporte ; un routeur qui trouve ici son propre numéro rejette la route, si bien que les routes ne peuvent pas boucler.","Send packets for these addresses to this router.":"Envoyez les paquets pour ces adresses à ce routeur.",Reachable:"Joignables","The addresses this route leads to: a prefix, here 256 addresses.":"Les adresses auxquelles mène cette route : un préfixe, ici 256 adresses.","BGP · UPDATE (withdrawal)":"BGP · UPDATE (retrait)","These addresses can no longer be reached through this router.":"Ces adresses ne sont plus joignables par ce routeur.","A Video Call":"Un appel vidéo",Signalling:"Signalisation","STUN and ICE":"STUN et ICE",Media:"Médias","STUN Server":"Serveur STUN","Sam’s Router":"Routeur de Sam","Sam’s Laptop":"Ordinateur de Sam","Web Real-Time Communication":"Communication web en temps réel","WebRTC lets two browsers call each other, with audio, video and data going straight between them, not through a server. A server only introduces them: they swap descriptions of what they can send and where they can be reached (signalling), find a way through both home routers with ICE and STUN, encrypt with DTLS, and send the media over UDP as SRTP.":"WebRTC permet à deux navigateurs de s’appeler, l’audio, la vidéo et les données allant directement de l’un à l’autre, sans passer par un serveur. Un serveur ne fait que les présenter : ils échangent des descriptions de ce qu’ils peuvent envoyer et de l’endroit où on peut les joindre (signalisation), trouvent un chemin à travers les deux routeurs domestiques avec ICE et STUN, chiffrent avec DTLS et envoient les médias sur UDP en SRTP.","Media over":"Médias sur","Always on":"Toujours actif","Works in":"Fonctionne dans","Every major browser":"Tous les grands navigateurs","W3C; RFC 8825 and others":"W3C ; RFC 8825 et d’autres","On the call":"En appel","Introduced by a server, then direct":"Présentés par un serveur, puis en direct","The signalling server passed the offer and the answer between the two browsers, a STUN server told the laptop its public address, and an ICE check found a way through both home routers. After a DTLS handshake, encrypted audio and video went straight from one laptop to the other. Press REPLAY to watch it again.":"Le serveur de signalisation a transmis l’offre et la réponse entre les deux navigateurs, un serveur STUN a indiqué à l’ordinateur son adresse publique, et une vérification ICE a trouvé un chemin à travers les deux routeurs domestiques. Après une négociation DTLS, l’audio et la vidéo chiffrés sont allés directement d’un ordinateur à l’autre. Appuyez sur REVOIR pour tout revoir.","Via call.example.com":"Via call.example.com","Media path":"Chemin des médias","Direct, through 2 NATs":"Direct, à travers 2 NAT","DTLS, then SRTP":"DTLS, puis SRTP","If blocked":"Si c’est bloqué","A TURN relay":"Un relais TURN","Join the Call":"Rejoindre l’appel","Through a signalling server":"Par un serveur de signalisation","The laptop opens a call page on call.example.com, and the page keeps a WebSocket open to the server, inside TLS. It joins room 42, where Sam is already waiting. The server will pass messages between the two browsers. WebRTC doesn’t say how: every app does this signalling its own way.":"L’ordinateur ouvre une page d’appel sur call.example.com, et la page garde un WebSocket ouvert vers le serveur, dans TLS. Il rejoint le salon 42, où Sam attend déjà. Le serveur transmettra les messages entre les deux navigateurs. WebRTC ne dit pas comment : chaque application fait cette signalisation à sa façon.","The app’s own server":"Le serveur propre à l’application","A WebSocket in TLS":"Un WebSocket dans TLS",Room:"Salon","42, with Sam":"42, avec Sam",JOIN:"REJOINDRE","room 42":"salon 42","SAM IS HERE":"SAM EST LÀ","peer: Sam":"pair : Sam","Public Address?":"Adresse publique ?","Ask a STUN server":"Demander à un serveur STUN","Behind its home router the laptop knows only its private address, 192.168.1.10, which nobody on the internet can reach. So it asks a STUN server named in the call page’s settings, with one small UDP request. The answer says where the request seemed to come from, 198.51.100.7 port 61022: the router’s public address and the port its NAT opened for this conversation.":"Derrière son routeur domestique, l’ordinateur ne connaît que son adresse privée, 192.168.1.10, que personne sur Internet ne peut joindre. Il interroge donc un serveur STUN indiqué dans les réglages de la page d’appel, par une petite requête UDP. La réponse dit d’où la requête semblait venir, 198.51.100.7 port 61022 : l’adresse publique du routeur et le port que son NAT a ouvert pour cette conversation.",Public:"Publique","what is my address?":"quelle est mon adresse ?","YOUR ADDRESS":"VOTRE ADRESSE","The Offer":"L’offre","An SDP description, via the server":"Une description SDP, via le serveur","The browser writes an offer in SDP: the media it wants to send (Opus audio; video in VP8, H.264 and others), the fingerprint of its DTLS certificate, its ICE user name and password, and its candidates, the addresses it might be reached at. Its private address is hidden behind a random .local name. The signalling server passes the offer on to Sam.":"Le navigateur rédige une offre en SDP : les médias qu’il veut envoyer (audio Opus ; vidéo en VP8, H.264 et autres), l’empreinte de son certificat DTLS, son nom d’utilisateur et son mot de passe ICE, et ses candidats, les adresses où on pourrait le joindre. Son adresse privée est cachée derrière un nom .local aléatoire. Le serveur de signalisation transmet l’offre à Sam.","SDP, in a JSON message":"SDP, dans un message JSON",Candidates:"Candidats",".local name, 198.51.100.7":"nom .local, 198.51.100.7","About 4.7 KB":"Environ 4.7 Ko","SDP: audio, video":"SDP : audio, vidéo",candidates:"candidats","to Sam":"vers Sam","Sam’s browser replies":"Le navigateur de Sam répond","Sam accepts the call. Sam’s browser answers with SDP of its own: the codecs it picked from the offer, its certificate fingerprint, its ICE user name and password, and its candidates, including its public address, 198.51.100.200 port 49170, which it learned from a STUN server the same way. It also says it will start the encryption handshake. Now each browser knows where the other might be reached.":"Sam accepte l’appel. Le navigateur de Sam répond par son propre SDP : les codecs choisis parmi l’offre, l’empreinte de son certificat, son nom d’utilisateur et son mot de passe ICE, et ses candidats, dont son adresse publique, 198.51.100.200 port 49170, apprise d’un serveur STUN de la même manière. Il indique aussi qu’il lancera la négociation de chiffrement. Chaque navigateur sait maintenant où l’autre pourrait être joint.",Codecs:"Codecs","Sam’s address":"Adresse de Sam","Starts DTLS":"Lance DTLS","Sam’s browser":"Navigateur de Sam","from Sam":"de Sam","Punch Through":"Percer le NAT","Checks straight to each other":"Des vérifications directes de l’un à l’autre","Now the browsers try pairs of addresses with STUN checks sent straight to each other (ICE). Each check also opens a way back through the sender’s own router, so once both sides have sent one, checks get through both NATs. This one is answered: the direct path works. The laptop then repeats the check with USE-CANDIDATE, choosing this pair for the call.":"Les navigateurs essaient maintenant des paires d’adresses avec des vérifications STUN envoyées directement de l’un à l’autre (ICE). Chaque vérification ouvre aussi un chemin de retour à travers le routeur de l’expéditeur ; dès que les deux côtés en ont envoyé une, les vérifications traversent les deux NAT. Celle-ci reçoit une réponse : le chemin direct fonctionne. L’ordinateur répète alors la vérification avec USE-CANDIDATE, choisissant cette paire pour l’appel.",Checks:"Vérifications","STUN, peer to peer":"STUN, de pair à pair","The ICE password":"Le mot de passe ICE","A direct path":"Un chemin direct",CHECK:"VÉRIFICATION","IT WORKS":"ÇA MARCHE","direct path":"chemin direct","THROUGH BOTH ROUTERS":"À TRAVERS LES DEUX ROUTEURS","DTLS Handshake":"Négociation DTLS","Keys for the media":"Des clés pour les médias","Over the same path the browsers run a DTLS handshake: TLS for UDP. Their certificates are self-signed, so each checks the other’s against the fingerprint in the SDP, which came through the signalling server inside TLS. The handshake also agrees the keys for SRTP, which encrypts the audio and video. WebRTC never sends media unencrypted.":"Sur le même chemin, les navigateurs font une négociation DTLS : du TLS pour UDP. Leurs certificats sont autosignés, donc chacun vérifie celui de l’autre grâce à l’empreinte du SDP, arrivée par le serveur de signalisation dans TLS. La négociation convient aussi des clés de SRTP, qui chiffre l’audio et la vidéo. WebRTC n’envoie jamais de médias en clair.","1.2, TLS over UDP":"1.2, TLS sur UDP","Checked by fingerprint":"Vérifiés par empreinte",Gives:"Fournit","The SRTP keys":"Les clés SRTP",certificate:"certificat","Media Flows":"Les médias circulent","Audio and video, direct":"Audio et vidéo, en direct","Audio goes in an SRTP packet every 20 ms, and video as frames split over several packets. Each packet has a readable RTP header (sequence number, timestamp, stream ID) and encrypted media. None of it passes through call.example.com. Both browsers watch delay and loss and adjust the video quality to suit, and a data channel for chat or files can share the same path.":"L’audio part dans un paquet SRTP toutes les 20 ms, et la vidéo en images réparties sur plusieurs paquets. Chaque paquet a un en-tête RTP lisible (numéro de séquence, horodatage, ID de flux) et des médias chiffrés. Rien de tout cela ne passe par call.example.com. Les deux navigateurs surveillent le délai et les pertes et ajustent la qualité vidéo en conséquence, et un canal de données pour le chat ou des fichiers peut partager le même chemin.","Opus, a packet per 20 ms":"Opus, un paquet toutes les 20 ms",Video:"Vidéo","VP8, adapts to the network":"VP8, s’adapte au réseau","None of it":"Rien",AUDIO:"AUDIO","Opus, every 20 ms":"Opus, toutes les 20 ms",VIDEO:"VIDÉO","VP8, a frame in 3 packets":"VP8, une image en 3 paquets","Peer to Peer":"De pair à pair","And when it can’t be":"Et quand c’est impossible","The server helped the two browsers find each other, then stepped aside: the call goes straight between the two homes. When a network won’t let direct packets through (some company firewalls, some mobile networks), ICE falls back to a TURN server that relays the encrypted media without being able to read it. Group calls usually send media through a server too, called an SFU.":"Le serveur a aidé les deux navigateurs à se trouver, puis s’est effacé : l’appel va directement d’un domicile à l’autre. Quand un réseau ne laisse pas passer les paquets directs (certains pare-feu d’entreprise, certains réseaux mobiles), ICE se rabat sur un serveur TURN qui relaie les médias chiffrés sans pouvoir les lire. Les appels de groupe passent en général eux aussi par un serveur, appelé SFU.","Laptop to laptop":"D’ordinateur à ordinateur",Fallback:"Solution de repli","TURN relay (encrypted)":"Relais TURN (chiffré)","Group calls":"Appels de groupe","Usually via an SFU":"En général via un SFU","NO SERVER IN THE MIDDLE":"AUCUN SERVEUR AU MILIEU","A WebSocket text message":"Un message texte WebSocket","The attributes; the 20-byte header isn’t counted.":"Les attributs ; l’en-tête de 20 octets n’est pas compté.","Always this value: tells STUN apart from the other traffic on the same port.":"Toujours cette valeur : distingue STUN du reste du trafic sur le même port.","Random; the response carries the same ID.":"Aléatoire ; la réponse porte le même ID.","Where the request came from, as the server saw it: the home router’s public address, and the port its NAT picked for this conversation.":"D’où venait la requête, vue par le serveur : l’adresse publique du routeur domestique et le port que son NAT a choisi pour cette conversation.","Their internet provider’s router, the next hop.":"Le routeur du fournisseur d’accès de Sam, le saut suivant.","Their router’s internet-facing port.":"Le port du routeur de Sam côté Internet.","The ICE user names from the offer and the answer, the other side’s first: proves the check belongs to this call.":"Les noms d’utilisateur ICE de l’offre et de la réponse, celui de l’autre côté d’abord : prouve que la vérification appartient à cet appel.","The priority a new candidate found by this check would get.":"La priorité qu’aurait un nouveau candidat trouvé par cette vérification.","This side, the caller, makes the final choice of path. The random number settles a tie.":"Ce côté, l’appelant, fait le choix final du chemin. Le nombre aléatoire départage une égalité.","HMAC-SHA1 of the message, keyed with an ICE password swapped through the signalling server, so a stranger can’t fake a check or its answer.":"HMAC-SHA1 du message, avec pour clé un mot de passe ICE échangé via le serveur de signalisation, pour qu’un inconnu ne puisse pas falsifier une vérification ni sa réponse.","A CRC-32 of the message: marks it clearly as STUN.":"Un CRC-32 du message : le marque clairement comme STUN.","Where the check came from, as the other laptop saw it: the home router’s public address and port.":"D’où venait la vérification, vue par l’autre ordinateur : l’adresse publique et le port du routeur domestique.",Epoch:"Époque","Counts this side’s records, so repeats and stale ones can be spotted.":"Compte les enregistrements de ce côté, pour repérer les doublons et les périmés.","Message length":"Longueur du message","Message sequence":"Séquence du message","Handshake messages are numbered, so they can be put back in order.":"Les messages de négociation sont numérotés, pour pouvoir être remis dans l’ordre.",Fragment:"Fragment","Cipher suites: ECDHE-ECDSA with AES-GCM, and others":"Suites de chiffrement : ECDHE-ECDSA avec AES-GCM, et d’autres","use_srtp: the SRTP protection it supports":"use_srtp : la protection SRTP qu’il prend en charge","Chosen: ECDHE-ECDSA-AES128-GCM-SHA256":"Choisie : ECDHE-ECDSA-AES128-GCM-SHA256","A self-signed certificate the browser made; its fingerprint was in the offer":"Un certificat autosigné créé par le navigateur ; son empreinte figurait dans l’offre","Its half of an X25519 key exchange, signed":"Sa moitié d’un échange de clés X25519, signée","Asks Sam’s browser for its certificate too":"Demande aussi son certificat au navigateur de Sam","Sam’s self-signed certificate; its fingerprint was in the answer":"Le certificat autosigné de Sam ; son empreinte figurait dans la réponse","Its half of the X25519 key exchange":"Sa moitié de l’échange de clés X25519","A signature that proves it holds the certificate’s key":"Une signature qui prouve qu’il détient la clé du certificat","From the next record on, this side encrypts.":"À partir de l’enregistrement suivant, ce côté chiffre.","Finished (encrypted)":"Finished (chiffré)","Epoch 1: protected with the keys just agreed.":"Époque 1 : protégé avec les clés tout juste convenues.","An 8-byte nonce, the Finished message and a 16-byte tag (AES-128-GCM).":"Un nonce de 8 octets, le message Finished et une étiquette de 16 octets (AES-128-GCM).","SRTP · audio":"SRTP · audio","2, no padding, extension, no CSRCs":"2, pas de bourrage, extension, pas de CSRC","X set: a header extension follows the fixed header.":"X activé : une extension d’en-tête suit l’en-tête fixe.","One more for each packet, so a lost or late one shows.":"Un de plus à chaque paquet, pour qu’un paquet perdu ou en retard se voie.","Audio clock, 48,000 ticks a second: +960 per 20 ms.":"Horloge audio, 48,000 tops par seconde : +960 toutes les 20 ms.","Which stream this is; announced in the SDP.":"De quel flux il s’agit ; annoncé dans le SDP.","Header extension":"Extension d’en-tête","0xbede, 2 words":"0xbede, 2 mots","One-byte elements: an ID (from the SDP’s a=extmap lines) and a length.":"Éléments d’un octet : un ID (tiré des lignes a=extmap du SDP) et une longueur.","Audio level":"Niveau audio","How loud this packet is, so a group call can show who is talking without decrypting.":"Le volume de ce paquet, pour qu’un appel de groupe puisse montrer qui parle sans déchiffrer.","Transport sequence":"Séquence de transport","Numbers every packet of the call; the receiver reports what arrived when, for congestion control.":"Numérote chaque paquet de l’appel ; le destinataire indique ce qui est arrivé et quand, pour le contrôle de congestion.","Encrypted media":"Médias chiffrés","20 ms of Opus audio, encrypted with keys from the DTLS handshake (AES-128-GCM).":"20 ms d’audio Opus, chiffrés avec des clés issues de la négociation DTLS (AES-128-GCM).","Authentication tag":"Étiquette d’authentification","Proves the packet came from the other side unchanged; the header is covered too.":"Prouve que le paquet vient de l’autre côté sans modification ; l’en-tête est couvert aussi.","SRTP · video":"SRTP · vidéo","Video clock, 90,000 ticks a second: +3,000 per frame at 30 frames a second.":"Horloge vidéo, 90,000 tops par seconde : +3,000 par image à 30 images par seconde.","Absolute send time":"Heure d’envoi absolue","When the packet was sent, so the receiver can tell when the network is filling up.":"Quand le paquet a été envoyé, pour que le destinataire voie quand le réseau se remplit.","1 byte":"1 octet","Part of a VP8 video frame, encrypted with keys from the DTLS handshake (AES-128-GCM).":"Une partie d’une image vidéo VP8, chiffrée avec des clés issues de la négociation DTLS (AES-128-GCM).","Marker set: the last packet of a video frame.":"Marker activé : le dernier paquet d’une image vidéo.",PLC:"Automate","8 ports":"8 ports","Frames and switches":"Trames et commutateurs","Broadband logins":"Connexion haut débit","The laptop sent it with 128; the router took 1 when it passed it on.":"L’ordinateur l’a envoyé avec 128 ; le routeur a retiré 1 en le relayant.","Frames & Switches":"Trames et commutateurs","To the NAS":"Vers le NAS","To the internet":"Vers Internet","Ethernet and Switches":"Ethernet et commutateurs","Ethernet carries almost every wired network, and Wi-Fi access points pass their traffic on to it. Every network card has a 48-bit MAC address. A frame says which card it is for and which card sent it, and a switch delivers it: it learns which port each address is behind from the frames it sees, and sends each frame only where it needs to go.":"Ethernet transporte presque tous les réseaux filaires, et les points d’accès Wi-Fi lui confient leur trafic. Chaque carte réseau a une adresse MAC de 48 bits. Une trame indique à quelle carte elle est destinée et quelle carte l’a envoyée, et un commutateur la livre : il apprend derrière quel port se trouve chaque adresse grâce aux trames qu’il voit, et n’envoie chaque trame que là où elle doit aller.","48-bit MAC":"MAC de 48 bits","14 bytes, plus a 4-byte FCS":"14 octets, plus un FCS de 4 octets","Frame size":"Taille de trame","64 to 1,518 bytes":"De 64 à 1 518 octets",Speeds:"Débits",Switched:"Commuté","Learned, flooded, forwarded":"Appris, inondé, transmis","The switch learned where the laptop and the NAS were from the frames they sent, flooded only the broadcast, and sent every other frame out of just the port it needed. MAC addresses carried each frame across one link; at the router the packet moved into a new frame. Press REPLAY to watch it again.":"Le commutateur a appris où se trouvaient l’ordinateur et le NAS grâce aux trames qu’ils ont envoyées, n’a inondé que la diffusion et a envoyé chacune des autres trames par le seul port nécessaire. Les adresses MAC ont porté chaque trame sur un seul lien ; au routeur, le paquet est passé dans une nouvelle trame. Appuyez sur REVOIR pour tout revoir.",Learned:"Appris","2 addresses, 2 ports":"2 adresses, 2 ports",Flooded:"Inondé","Only the broadcast":"La diffusion seulement",Frame:"Trame","14-byte header, 4-byte FCS":"En-tête de 14 octets, FCS de 4","Forgets after":"Oublie après","5 minutes unused":"5 minutes sans usage","Who Has the NAS?":"Qui a le NAS ?","A broadcast asks for a MAC address":"Une diffusion demande une adresse MAC","The laptop wants to reach the NAS at 192.168.1.20. On a local network, frames are delivered by MAC address, and the laptop doesn’t know the NAS’s yet. So it sends an ARP request to ff:ff:ff:ff:ff:ff, the broadcast address, into port 1 of the switch.":"L’ordinateur veut joindre le NAS en 192.168.1.20. Sur un réseau local, les trames sont livrées par adresse MAC, et l’ordinateur ne connaît pas encore celle du NAS. Il envoie donc une requête ARP à ff:ff:ff:ff:ff:ff, l’adresse de diffusion, par le port 1 du commutateur.","Looking for":"Cherche","ff:ff:ff:ff:ff:ff (all)":"ff:ff:ff:ff:ff:ff (tous)",Into:"Entre par","Switch port 1":"Port 1 du commutateur","who has 192.168.1.20?":"qui a 192.168.1.20 ?","Learn, Then Flood":"Apprendre, puis inonder","The switch notes where the laptop is":"Le commutateur note où est l’ordinateur","A switch reads each frame’s source address and notes it in its MAC table: 00:00:5e:00:53:10 is on port 1. A broadcast is for everyone, so it sends a copy out of every other port: to the NAS on port 2 and the router on port 8. Frames for unknown addresses are flooded too.":"Un commutateur lit l’adresse source de chaque trame et la note dans sa table MAC : 00:00:5e:00:53:10 est sur le port 1. Une diffusion s’adresse à tous, il en envoie donc une copie par chacun des autres ports : au NAS sur le port 2 et au routeur sur le port 8. Les trames pour des adresses inconnues sont aussi inondées.","…:53:10 is on port 1":"…:53:10 est sur le port 1",Copies:"Copies","Out of every other port":"Par tous les autres ports","Unknown address":"Adresse inconnue","Flooded the same way":"Inondée de la même façon","…:53:10 IS ON PORT 1":"…:53:10 EST SUR LE PORT 1","copies out of ports 2 and 8":"copies par les ports 2 et 8","Only the NAS Answers":"Seul le NAS répond","The reply goes to one port":"La réponse va vers un seul port","Every device reads the request, but only the NAS has 192.168.1.20, so only it answers, straight to the laptop’s MAC; the router ignores it. The switch learns that 00:00:5e:00:53:20 is on port 2. It already knows where the laptop is, so the reply leaves by port 1 alone.":"Tous les appareils lisent la requête, mais seul le NAS a 192.168.1.20, donc lui seul répond, directement à la MAC de l’ordinateur ; le routeur l’ignore. Le commutateur apprend que 00:00:5e:00:53:20 est sur le port 2. Il sait déjà où est l’ordinateur, donc la réponse sort par le seul port 1.","To the laptop only":"À l’ordinateur seulement","…:53:20 is on port 2":"…:53:20 est sur le port 2","Out of":"Sort par","Port 1":"Port 1","…:53:20 IS ON PORT 2":"…:53:20 EST SUR LE PORT 2","port 1 only":"port 1 seulement","Port to Port":"De port à port","Frames go only where they must":"Les trames ne vont que là où il faut","The laptop connects to the NAS. Each frame starts with the NAS’s MAC, then its own, then a type: 0x0800, an IPv4 packet. After the packet, the card adds a 4-byte checksum. The switch looks up the destination and sends each frame out of port 2 only. The router never sees them.":"L’ordinateur se connecte au NAS. Chaque trame commence par la MAC du NAS, puis la sienne, puis un type : 0x0800, un paquet IPv4. Après le paquet, la carte ajoute une somme de contrôle de 4 octets. Le commutateur cherche la destination et n’envoie chaque trame que par le port 2. Le routeur ne les voit jamais.","To, from, type: 14 bytes":"À, de, type : 14 octets","4 bytes, added by the card":"4 octets, ajoutés par la carte","Router sees":"Le routeur voit",Nothing:"Rien","type 0x0800 (IPv4)":"type 0x0800 (IPv4)","out of port 2 only":"par le port 2 seulement","Off the Network":"Hors du réseau","A frame for the router":"Une trame pour le routeur","Next the laptop opens a website at 203.0.113.10. That address isn’t on the local network, so the frame goes to the router: the router’s MAC, known from an earlier ARP, is the destination, while the packet inside still names 203.0.113.10. The switch sends it out of port 8.":"Ensuite l’ordinateur ouvre un site en 203.0.113.10. Cette adresse n’est pas sur le réseau local, donc la trame va au routeur : la MAC du routeur, connue grâce à un ARP précédent, est la destination, tandis que le paquet à l’intérieur indique toujours 203.0.113.10. Le commutateur l’envoie par le port 8.","Frame to":"Trame vers","The router’s MAC":"La MAC du routeur","Packet to":"Paquet vers","Port 8":"Port 8","IP packet to 203.0.113.10":"paquet IP vers 203.0.113.10","out of port 8":"par le port 8","A New Frame":"Une nouvelle trame","Every hop rewraps the packet":"Chaque saut remballe le paquet","The router takes the packet out of the frame, lowers its TTL and swaps in its public address (NAT). Then it puts the packet in a new frame for its next link: its internet-side MAC as the source, the provider’s router as the destination. MAC addresses only ever cross one link.":"Le routeur sort le paquet de la trame, baisse son TTL et y met son adresse publique (NAT). Puis il place le paquet dans une nouvelle trame pour le lien suivant : sa MAC côté Internet comme source, le routeur du fournisseur comme destination. Une adresse MAC ne franchit jamais plus d’un lien.","The router’s internet port":"Le port Internet du routeur","The provider’s router":"Le routeur du fournisseur","Still 203.0.113.10":"Toujours 203.0.113.10","NEW FRAME":"NOUVELLE TRAME","from the router’s internet port":"du port Internet du routeur","IP still to 203.0.113.10":"IP toujours vers 203.0.113.10","In port 1 · Who has 192.168.1.20? Tell 192.168.1.10":"Entre, port 1 · Who has 192.168.1.20? Tell 192.168.1.10","Out port 2 (flooded) · Who has 192.168.1.20?":"Sort, port 2 (inondée) · Who has 192.168.1.20?","Out port 8 (flooded) · Who has 192.168.1.20?":"Sort, port 8 (inondée) · Who has 192.168.1.20?","In port 2 · 192.168.1.20 is at 00:00:5e:00:53:20":"Entre, port 2 · 192.168.1.20 is at 00:00:5e:00:53:20","Out port 1 only · 192.168.1.20 is at 00:00:5e:00:53:20":"Sort par le seul port 1 · 192.168.1.20 is at 00:00:5e:00:53:20","In port 1 · 50532 → 445 [SYN]":"Entre, port 1 · 50532 → 445 [SYN]","Out port 2 · 50532 → 445 [SYN]":"Sort, port 2 · 50532 → 445 [SYN]","In port 2 · 445 → 50532 [SYN, ACK]":"Entre, port 2 · 445 → 50532 [SYN, ACK]","Out port 1 · 445 → 50532 [SYN, ACK]":"Sort, port 1 · 445 → 50532 [SYN, ACK]","In port 1 · 52344 → 443 [SYN] (frame to the router)":"Entre, port 1 · 52344 → 443 [SYN] (trame vers le routeur)","Out port 8 · 52344 → 443 [SYN]":"Sort, port 8 · 52344 → 443 [SYN]","TTL 127 · 40112 → 443 [SYN] (new frame, after NAT)":"TTL 127 · 40112 → 443 [SYN] (nouvelle trame, après NAT)","Seen going into the switch, port 1":"Vue en entrant dans le commutateur, port 1","Seen leaving the switch, port 2":"Vue en sortant du commutateur, port 2","Seen leaving the switch, port 8":"Vue en sortant du commutateur, port 8","Seen going into the switch, port 2":"Vue en entrant dans le commutateur, port 2","Seen leaving the switch, port 1":"Vue en sortant du commutateur, port 1","Broadband Logins":"Connexion haut débit",Discovery:"Découverte","PPP setup":"Mise en place de PPP","Home Router":"Box Internet","Access Server":"Serveur d’accès","Point-to-Point Protocol over Ethernet":"Protocole point à point sur Ethernet","Many DSL and fibre providers make the home router log in before it gets online. PPPoE is how: the router finds the provider’s access server and opens a session with it, then runs PPP inside, agreeing on the link’s settings, logging in with the username and password from the provider and receiving its public IP address. Every packet then carries an 8-byte PPPoE header.":"Beaucoup de fournisseurs DSL et fibre obligent la box à s’authentifier avant d’aller sur Internet. PPPoE sert à cela : la box trouve le serveur d’accès du fournisseur et ouvre une session avec lui, puis y fait tourner PPP pour convenir des réglages du lien, s’authentifier avec l’identifiant et le mot de passe du fournisseur et recevoir son adresse IP publique. Ensuite, chaque paquet porte un en-tête PPPoE de 8 octets.","CHAP or PAP":"CHAP ou PAP","From IPCP":"Par IPCP","8 bytes (MTU 1,492)":"8 octets (MTU 1 492)","Logged in":"Connectée","Found, agreed, checked, addressed":"Trouvé, convenu, vérifié, adressé","The router found the provider’s access server, got a session, agreed on the link’s settings, proved its password without sending it and was given its public address. Every packet now travels inside that session, until a PADT ends it. Press REPLAY to watch it again.":"La box a trouvé le serveur d’accès du fournisseur, obtenu une session, convenu des réglages du lien, prouvé son mot de passe sans l’envoyer et reçu son adresse publique. Désormais chaque paquet voyage dans cette session, jusqu’à ce qu’un PADT y mette fin. Appuyez sur REVOIR pour tout revoir.","17 to get online":"17 pour se connecter","Public IP":"IP publique","8 bytes per packet":"8 octets par paquet","Anyone There?":"Il y a quelqu’un ?","The router looks for an access server":"La box cherche un serveur d’accès","The home router is plugged into the provider’s fibre or DSL line. Before it can log in, it has to find the provider’s access server, so it broadcasts a PADI: “PPPoE Active Discovery Initiation”. An access server answers with a PADO, an offer that names it: bng-1.example.net.":"La box est branchée sur la ligne fibre ou DSL du fournisseur. Avant de s’authentifier, elle doit trouver le serveur d’accès du fournisseur ; elle diffuse donc un PADI : « PPPoE Active Discovery Initiation ». Un serveur d’accès répond par un PADO, une offre qui le nomme : bng-1.example.net.","PADI, to everyone":"PADI, à tous","PADO, from the server":"PADO, du serveur","Ethernet type":"Type Ethernet","0x8863 (discovery)":"0x8863 (découverte)","is there an access server?":"un serveur d’accès est là ?","and a cookie":"et un cookie","Pick a Server":"Choisir un serveur","A session number for the line":"Un numéro de session pour la ligne","If several servers answered, the router picks one and asks it directly with a PADR, sending back the cookie it was given. The server replies with a PADS carrying a session ID, 0x2f1c. From now on every frame between the two of them carries that number.":"Si plusieurs serveurs ont répondu, la box en choisit un et le sollicite directement par un PADR, en renvoyant le cookie reçu. Le serveur répond par un PADS portant un identifiant de session, 0x2f1c. Désormais, chaque trame entre les deux porte ce numéro.",Confirmed:"Confirmé","this server, please":"ce serveur, s’il vous plaît","with its cookie":"avec son cookie","session ID 0x2f1c":"session 0x2f1c","SESSION 0x2F1C":"SESSION 0x2F1C","Link Settings":"Réglages du lien","LCP agrees on size and login":"LCP convient de la taille et de l’authentification","Now PPP runs inside the session, starting with LCP. Each side asks for its settings: packets of at most 1,492 bytes, since PPPoE’s 8 bytes have to fit in Ethernet’s 1,500, and a random magic number to spot loops. The server also asks for a CHAP login. Both agree.":"PPP fonctionne maintenant dans la session, en commençant par LCP. Chaque côté demande ses réglages : des paquets de 1 492 octets au plus, car les 8 octets de PPPoE doivent tenir dans les 1 500 d’Ethernet, et un nombre magique aléatoire pour repérer les boucles. Le serveur demande aussi une authentification CHAP. Les deux acceptent.","Largest packet":"Plus gros paquet","1,492 bytes (MRU)":"1 492 octets (MRU)","CHAP with MD5":"CHAP avec MD5","0x8864 (session)":"0x8864 (session)","LCP REQUEST":"REQUÊTE LCP","magic number":"nombre magique","MRU 1492, log in with CHAP":"MRU 1492, connexion CHAP","LCP ACK":"LCP ACK","A password check without the password":"Vérifier le mot de passe sans l’envoyer","The server sends a random challenge. The router answers with its username, alex@fibre.example, and an MD5 hash of the challenge and its password, so the password itself never crosses the line. The server checks the answer with the provider’s RADIUS server, then says Success.":"Le serveur envoie un défi aléatoire. La box répond avec son identifiant, alex@fibre.example, et une empreinte MD5 du défi et de son mot de passe : le mot de passe lui-même ne traverse jamais la ligne. Le serveur vérifie la réponse auprès du serveur RADIUS du fournisseur, puis répond Success.",Username:"Identifiant","A hash, not the password":"Une empreinte, pas le mot de passe","The provider’s RADIUS":"Le RADIUS du fournisseur","MD5(id, password, challenge)":"MD5(id, mot de passe, défi)","CHECKED WITH RADIUS":"VÉRIFIÉ AUPRÈS DE RADIUS","Get an Address":"Obtenir une adresse","IPCP hands out the public IP":"IPCP attribue l’IP publique","The server first tells the router its own end, 198.51.100.1. The router asks for an address and DNS servers, offering 0.0.0.0: “anything”. The server says no and suggests 198.51.100.7 and two DNS servers. The router asks again with those, and the server agrees.":"Le serveur indique d’abord à la box sa propre extrémité, 198.51.100.1. La box demande une adresse et des serveurs DNS en proposant 0.0.0.0 : « n’importe laquelle ». Le serveur refuse et suggère 198.51.100.7 et deux serveurs DNS. La box redemande avec ces valeurs, et le serveur accepte.","Other end":"Autre extrémité","IPCP REQUEST":"REQUÊTE IPCP","my end: 198.51.100.1":"mon extrémité : 198.51.100.1","address? 0.0.0.0":"adresse ? 0.0.0.0","IPCP ACK":"IPCP ACK","IPCP NAK":"IPCP NAK","use 198.51.100.7":"utilise 198.51.100.7","198.51.100.7, please":"198.51.100.7, s’il vous plaît",agreed:"accepté","Every packet in an 8-byte wrapper":"Chaque paquet dans une enveloppe de 8 octets","The laptop opens a website. The router swaps in its public address (NAT) and sends the packet inside the session: a 6-byte PPPoE header, then 2 bytes saying “IPv4”. It also lowers the MSS the laptop offered from 1460 to 1452, so the replies fit in 1,492 bytes.":"L’ordinateur ouvre un site. La box y met son adresse publique (NAT) et envoie le paquet dans la session : un en-tête PPPoE de 6 octets, puis 2 octets qui disent « IPv4 ». Elle abaisse aussi le MSS proposé par l’ordinateur de 1460 à 1452, pour que les réponses tiennent dans 1 492 octets.",Wrapper:"Enveloppe","6 + 2 bytes":"6 + 2 octets","1460 → 1452 (clamped)":"1460 → 1452 (abaissé)","in session 0x2f1c":"dans la session 0x2f1c","MSS now 1452":"MSS désormais 1452","Seen on the router’s line to the provider":"Vue sur la ligne de la box vers le fournisseur","PPPoE PADI · 18 bytes":"PPPoE PADI · 18 octets","PADI, 2 tags":"PADI, 2 balises","Broadcast: everything on the line receives it.":"Diffusion : tout ce qui est sur la ligne la reçoit.","0x8863 (PPPoE discovery)":"0x8863 (découverte PPPoE)","Version, type":"Version, type","Active Discovery Initiation: is there an access server out there?":"Active Discovery Initiation : y a-t-il un serveur d’accès quelque part ?","0 (none yet)":"0 (aucun pour l’instant)","What follows this header.":"Ce qui suit cet en-tête.","The service the router wants; empty means any.":"Le service que veut la box ; vide signifie n’importe lequel.","Type, length":"Type, longueur","A value the router made up. Answers carry it back, so the router can match them to its request.":"Une valeur inventée par la box. Les réponses la renvoient, pour que la box puisse les relier à sa demande.","PPPoE PADO · 59 bytes":"PPPoE PADO · 59 octets","PADO, 4 tags":"PADO, 4 balises","The access server’s port.":"Le port du serveur d’accès.","Active Discovery Offer: an access server answers.":"Active Discovery Offer : un serveur d’accès répond.","The access server’s name.":"Le nom du serveur d’accès.","A value the server will recognise when the router asks for it again, so floods of fake requests cost it nothing.":"Une valeur que le serveur reconnaîtra quand la box la lui redemandera, si bien qu’un flot de fausses demandes ne lui coûte rien.","PPPoE PADR · 38 bytes":"PPPoE PADR · 38 octets","PADR, 3 tags":"PADR, 3 balises","The access server that answered.":"Le serveur d’accès qui a répondu.","Active Discovery Request: the router picks this server.":"Active Discovery Request : la box choisit ce serveur.","PPPoE PADS · 18 bytes":"PPPoE PADS · 18 octets","PADS, 2 tags":"PADS, 2 balises","Active Discovery Session-confirmation: here is the session ID.":"Active Discovery Session-confirmation : voici l’identifiant de session.","Given by the server in its PADS; every frame of the session carries it.":"Donné par le serveur dans son PADS ; chaque trame de la session le porte.","PPPoE · 6 bytes":"PPPoE · 6 octets","PPP LCP Configure-Request · 16 bytes":"PPP LCP Configure-Request · 16 octets","0x8864 (PPPoE session)":"0x8864 (session PPPoE)","0x00 (Session)":"0x00 (session)","Session data: one PPP packet.":"Données de session : un paquet PPP.","Link Control Protocol: the link’s settings.":"Link Control Protocol : les réglages du lien.","The settings this side wants.":"Les réglages que veut ce côté.","The answer carries the same number.":"La réponse porte le même numéro.","The largest packet this side will take: 1,500 bytes of Ethernet minus PPPoE’s 8.":"Le plus gros paquet que ce côté accepte : 1 500 octets d’Ethernet moins les 8 de PPPoE.","Random. Seeing its own number come back would mean the line loops back on itself.":"Aléatoire. Voir revenir son propre nombre voudrait dire que la ligne boucle sur elle-même.","PPP LCP Configure-Request · 21 bytes":"PPP LCP Configure-Request · 21 octets","How the server wants the router to log in.":"Comment le serveur veut que la box s’authentifie.","PPP LCP Configure-Ack · 16 bytes":"PPP LCP Configure-Ack · 16 octets","Every setting accepted, exactly as asked.":"Tous les réglages acceptés, exactement comme demandés.","The number of the request this answers.":"Le numéro de la demande à laquelle ceci répond.","PPP LCP Configure-Ack · 21 bytes":"PPP LCP Configure-Ack · 21 octets","PPP CHAP Challenge · 40 bytes":"PPP CHAP Challenge · 40 octets","Challenge Handshake Authentication Protocol: the login.":"Challenge Handshake Authentication Protocol : l’authentification.","A random value for the router to prove its password with.":"Une valeur aléatoire avec laquelle la box prouve son mot de passe.","The response must carry the same number.":"La réponse doit porter le même numéro.","Value size":"Taille de la valeur","Random, new for every login.":"Aléatoire, nouvelle à chaque connexion.","The server’s name.":"Le nom du serveur.","PPP CHAP Response · 41 bytes":"PPP CHAP Response · 41 octets","The proof, and who is logging in.":"La preuve, et qui se connecte.","The number of the challenge this answers.":"Le numéro du défi auquel ceci répond.","MD5 of the identifier, the password and the challenge: it proves the password without sending it.":"MD5 de l’identifiant, du mot de passe et du défi : il prouve le mot de passe sans l’envoyer.","The username the provider gave.":"L’identifiant fourni par le fournisseur.","PPP CHAP Success · 13 bytes":"PPP CHAP Success · 13 octets","The login worked.":"L’authentification a réussi.","Text for people to read; any words will do.":"Du texte à lire pour les humains ; n’importe quels mots conviennent.","PPP IPCP Configure-Request · 12 bytes":"PPP IPCP Configure-Request · 12 octets","IP Control Protocol: the IP address and DNS servers.":"IP Control Protocol : l’adresse IP et les serveurs DNS.","The address of the server’s end of the link.":"L’adresse de l’extrémité du serveur sur le lien.","PPP IPCP Configure-Request · 24 bytes":"PPP IPCP Configure-Request · 24 octets","Zero: “please give me an address”.":"Zéro : « donnez-moi une adresse, s’il vous plaît ».","Zero: “which DNS server should I use?”":"Zéro : « quel serveur DNS dois-je utiliser ? »","PPP IPCP Configure-Ack · 12 bytes":"PPP IPCP Configure-Ack · 12 octets","PPP IPCP Configure-Nak · 24 bytes":"PPP IPCP Configure-Nak · 24 octets","Not these values: here are ones that would be accepted.":"Pas ces valeurs : en voici qui seraient acceptées.","The address for the router.":"L’adresse pour la box.","PPP IPCP Configure-Ack · 24 bytes":"PPP IPCP Configure-Ack · 24 octets","PPP · 2 bytes":"PPP · 2 octets","An IPv4 packet follows.":"Un paquet IPv4 suit.","Lowered from 1460 by the router, so packets back fit in the 1,492 bytes PPPoE leaves.":"Abaissé depuis 1460 par la box, pour que les paquets de retour tiennent dans les 1 492 octets que laisse PPPoE.","Internet phone calls":"Appels par internet","IP camera streams":"Flux de caméras IP","Live streaming upload":"Envoi de directs","Multicast and TV channels":"Multicast et chaînes TV","IP Camera":"Caméra IP","TV Box":"Box TV",Camera:"Caméra","Internet Phone Calls":"Appels par internet","Voice (RTP)":"Voix (RTP)","SIP Server":"Serveur SIP","Bob’s Router":"Routeur de Bob","Session Initiation Protocol":"Protocole d’ouverture de session","SIP sets up phone calls over the internet: office desk phones, phone apps and the providers behind them. A phone signs in with its provider’s SIP server. To call someone it sends an INVITE; the other phone rings and answers, and the two agree on how to send the voice, which then flows as RTP. The messages are plain text, a lot like HTTP.":"SIP établit les appels téléphoniques par internet : téléphones de bureau, applis de téléphonie et les opérateurs derrière. Un téléphone se connecte au serveur SIP de son opérateur. Pour appeler quelqu’un, il envoie un INVITE ; l’autre téléphone sonne et décroche, et les deux s’accordent sur la façon d’envoyer la voix, qui circule ensuite en RTP. Les messages sont du texte brut, très proche de HTTP.","UDP or TCP 5060":"UDP ou TCP 5060","Call setup":"Établir l’appel",Voice:"Voix","RTP, described by SDP":"RTP, décrit par SDP","Codec here":"Codec ici","Call ended":"Appel terminé","Signed in, rang, talked, hung up":"Inscrit, sonné, parlé, raccroché","Alice’s phone signed in with a password it never sent, invited Bob’s phone through the SIP server, heard it ring, and talked over RTP until Bob hung up with a BYE. SIP only set the call up and took it down; the voice travelled as packets of its own. Press REPLAY to watch it again.":"Le téléphone d’Alice s’est inscrit avec un mot de passe qu’il n’a jamais envoyé, a invité le téléphone de Bob via le serveur SIP, l’a entendu sonner et a parlé en RTP jusqu’à ce que Bob raccroche avec un BYE. SIP n’a fait qu’établir puis terminer l’appel ; la voix a voyagé dans ses propres paquets. Appuyez sur REVOIR pour tout revoir.","50 packets a second each way":"50 paquets par seconde dans chaque sens",Through:"Passe par","The provider’s server":"Le serveur de l’opérateur","No (SIPS and SRTP add it)":"Non (SIPS et SRTP l’ajoutent)","Sign In":"Inscription","The phone tells the server where it is":"Le téléphone dit au serveur où il est","Alice’s phone, an app on her laptop, registers with her provider’s SIP server: alice@example.net can be reached here. The server answers 401 with a challenge, so the phone asks again with a hash made from the challenge and its password. 200 OK: registered for an hour.":"Le téléphone d’Alice, une appli sur son portable, s’inscrit auprès du serveur SIP de son opérateur : alice@example.net est joignable ici. Le serveur répond 401 avec un défi, alors le téléphone redemande avec un hash tiré du défi et de son mot de passe. 200 OK : inscrit pour une heure.","Good for":"Valable","3600 s, then again":"3600 s, puis à nouveau","is here":"est ici","with a challenge":"avec un défi","again, with a hash":"à nouveau, avec un hash",registered:"inscrit","Call Bob":"Appeler Bob","An INVITE, passed on by the server":"Un INVITE, relayé par le serveur","Alice calls bob@example.net. Her INVITE carries SDP: G.711 audio, sent to her phone. The server answers 100 Trying, finds where Bob’s phone registered and passes the INVITE on, with its own Via and Record-Route and its own address in the SDP: the voice will go through it.":"Alice appelle bob@example.net. Son INVITE porte du SDP : audio G.711, à envoyer à son téléphone. Le serveur répond 100 Trying, trouve où le téléphone de Bob s’est inscrit et relaie l’INVITE, avec son propre Via, son Record-Route et sa propre adresse dans le SDP : la voix passera par lui.","Offer (SDP)":"Offre (SDP)","G.711, port 49170":"G.711, port 49170","Stops Alice resending":"Alice ne renvoie plus","call bob@example.net":"appeler bob@example.net","SDP: G.711 audio":"SDP : audio G.711","passed on to Bob":"relayé à Bob","voice via the server":"voix via le serveur",Ringing:"Sonnerie","The answer retraces the route":"La réponse refait le chemin","Bob’s phone starts ringing and says so: 180 Ringing. Responses follow the Via headers back the way the request came, so it goes to the server, which removes its own Via and passes it on to Alice. Her phone plays the ringing tone.":"Le téléphone de Bob se met à sonner et le dit : 180 Ringing. Les réponses suivent les en-têtes Via en sens inverse de la requête, donc elle va au serveur, qui retire son propre Via et la relaie à Alice. Son téléphone joue la tonalité de retour d’appel.","Route back":"Chemin du retour","The Via headers, in reverse":"Les en-têtes Via, à l’envers","Alice hears":"Alice entend","The ringing tone":"La tonalité d’appel","Bob’s phone rings":"le téléphone de Bob sonne","to Alice":"vers Alice",Answered:"Décroché","200 OK, then ACK":"200 OK, puis ACK","Bob picks up. His 200 OK carries his SDP answer: G.711, sent to his phone. The server swaps in its own address again before passing it to Alice. Her phone confirms with an ACK, which the server passes to Bob. The call is set up.":"Bob décroche. Son 200 OK porte sa réponse SDP : G.711, à envoyer à son téléphone. Le serveur remet sa propre adresse avant de la relayer à Alice. Son téléphone confirme par un ACK, que le serveur relaie à Bob. L’appel est établi.","Answer (SDP)":"Réponse (SDP)","G.711, port 49172":"G.711, port 49172","Confirmed by":"Confirmé par","Voice goes to":"La voix va","The server, ports 40000, 40002":"Au serveur, ports 40000, 40002","Bob answers":"Bob décroche",answered:"décroché",Talking:"Conversation","Voice flows as RTP":"La voix circule en RTP","Now the voice: every 20 ms each phone sends an RTP packet with 160 bytes of G.711 sound, a sequence number and a timestamp, over UDP. They go to the server, which passes them on to the other phone. SIP stays quiet while they talk.":"Place à la voix : toutes les 20 ms, chaque téléphone envoie un paquet RTP avec 160 octets de son G.711, un numéro de séquence et un horodatage, en UDP. Ils vont au serveur, qui les relaie à l’autre téléphone. SIP se tait pendant qu’ils parlent.",Every:"Toutes les","20 ms, 160 bytes of sound":"20 ms, 160 octets de son","Carried by":"Transportée par","RTP over UDP":"RTP sur UDP","SIP meanwhile":"SIP pendant ce temps","Nothing to say":"Rien à dire",VOICE:"VOIX","20 ms of Alice":"20 ms d’Alice","20 ms of Bob":"20 ms de Bob","Hang Up":"Raccrocher","BYE, and 200 OK":"BYE, puis 200 OK","Bob hangs up: his phone sends BYE, routed through the server as the Record-Route asked, and Alice’s phone answers 200 OK. Both stop sending voice. The call took four kinds of request; the voice itself was never part of SIP.":"Bob raccroche : son téléphone envoie BYE, acheminé par le serveur comme le demandait le Record-Route, et le téléphone d’Alice répond 200 OK. Les deux arrêtent d’envoyer la voix. L’appel a pris quatre sortes de requêtes ; la voix elle-même n’a jamais fait partie de SIP.","No more RTP":"Fin du RTP","Bob hangs up":"Bob raccroche","1, 0 (PCMU: G.711 μ-law, the classic phone codec)":"1, 0 (PCMU : G.711 loi μ, le codec téléphonique classique)","Audio clock at 8,000 per second: +160 per 20 ms of sound.":"Horloge audio à 8000 par seconde : +160 par 20 ms de son.","160 bytes of G.711 audio (20 ms, one byte per sample)":"160 octets d’audio G.711 (20 ms, un octet par échantillon)","IP Camera Streams":"Flux de caméras IP","Video (RTP)":"Vidéo (RTP)","Real Time Streaming Protocol":"Protocole de streaming en temps réel","RTSP is how video players, recorders and security apps get live video from IP cameras. It works like a remote control: the player asks what the camera offers, sets up a stream, and says PLAY and later TEARDOWN, in text messages much like HTTP. The video itself doesn’t travel in RTSP: it flows separately as RTP, here over UDP.":"RTSP permet aux lecteurs vidéo, enregistreurs et applis de sécurité d’obtenir la vidéo en direct des caméras IP. Il fonctionne comme une télécommande : le lecteur demande ce que propose la caméra, prépare un flux, puis dit PLAY et plus tard TEARDOWN, dans des messages texte proches de HTTP. La vidéo elle-même ne passe pas par RTSP : elle circule à part en RTP, ici sur UDP.",Controls:"Commandes",Watched:"Regardé","Described, set up, played, stopped":"Décrit, préparé, lu, arrêté","VLC asked the camera what it had, logged in with a hash of its password, set up one video track and pressed PLAY. The video came as RTP packets on ports of its own, a key frame in three pieces, until TEARDOWN ended the session. Press REPLAY to watch it again.":"VLC a demandé à la caméra ce qu’elle avait, s’est connecté avec un hash de son mot de passe, a préparé une piste vidéo et a appuyé sur PLAY. La vidéo est arrivée en paquets RTP sur ses propres ports, une image clé en trois morceaux, jusqu’à ce que TEARDOWN ferme la session. Appuyez sur REVOIR pour tout revoir.","6 on one TCP connection":"6 sur une connexion TCP","Key frame":"Image clé","Split into 3 packets":"En 3 paquets","1185d200, 60 s timeout":"1185d200, expire après 60 s","What Can You Do?":"Que sais-tu faire ?","OPTIONS over a TCP connection":"OPTIONS sur une connexion TCP","VLC opens rtsp://192.168.1.64/stream1. It connects to the camera on TCP port 554 and starts with OPTIONS: which commands do you support? The camera lists them. As in HTTP, every request and reply is text; a CSeq header numbers them.":"VLC ouvre rtsp://192.168.1.64/stream1. Il se connecte à la caméra sur le port TCP 554 et commence par OPTIONS : quelles commandes acceptes-tu ? La caméra les énumère. Comme en HTTP, chaque requête et réponse est du texte ; un en-tête CSeq les numérote.","Numbered by":"Numérotées par","what can you do?":"que sais-tu faire ?","Describe the Stream":"Décrire le flux","SDP says what the video is":"Le SDP dit ce qu’est la vidéo","DESCRIBE asks for the stream’s description. The camera wants a login first: 401, with a digest challenge. VLC asks again with a hash of the password, and the reply carries SDP: one H.264 video track, RTP payload type 96, with a 90 kHz clock.":"DESCRIBE demande la description du flux. La caméra exige d’abord une connexion : 401, avec un défi digest. VLC redemande avec un hash du mot de passe, et la réponse porte du SDP : une piste vidéo H.264, type de charge RTP 96, avec une horloge à 90 kHz.","Digest: a hash":"Digest : un hash","H.264, payload type 96":"H.264, type de charge 96",Track:"Piste","describe stream1":"décris stream1","log in first":"connecte-toi d’abord","SDP: H.264 video":"SDP : vidéo H.264","track 1":"piste 1","Set Up":"Préparation","Agree on ports for the video":"S’accorder sur les ports de la vidéo","SETUP for trackID=1 says how to deliver it: RTP over UDP, to the laptop’s ports 50000 (video) and 50001 (RTCP reports). The camera agrees, picks its own ports, 6970 and 6971, and opens a session, 1185d200, that every later request names.":"SETUP pour trackID=1 dit comment la livrer : RTP sur UDP, vers les ports 50000 (vidéo) et 50001 (rapports RTCP) du portable. La caméra accepte, choisit ses propres ports, 6970 et 6971, et ouvre une session, 1185d200, que chaque requête suivante nomme.","Laptop ports":"Ports du portable","track 1, RTP over UDP":"piste 1, RTP sur UDP","to ports 50000-50001":"vers les ports 50000-50001","session 1185d200":"session 1185d200","from ports 6970-6971":"depuis les ports 6970-6971",Play:"Lecture","The remote control’s PLAY button":"Le bouton PLAY de la télécommande","PLAY starts the stream from now (npt=0.000-). The reply tells VLC which RTP sequence number and timestamp come first, so it can line the video up. From here on, the video doesn’t travel in RTSP at all.":"PLAY lance le flux à partir de maintenant (npt=0.000-). La réponse indique à VLC quel numéro de séquence et quel horodatage RTP arrivent en premier, pour caler la vidéo. Désormais, la vidéo ne passe plus du tout par RTSP.",Range:"Plage","From now":"À partir de maintenant","First packet":"Premier paquet","Video arrives":"La vidéo arrive","On the UDP ports":"Sur les ports UDP","play from now":"lis à partir de maintenant",playing:"lecture en cours","Video Arrives":"La vidéo arrive","A key frame in RTP packets":"Une image clé en paquets RTP","The camera sends a key frame, a whole picture, in three RTP packets: H.264 fragments marked first, middle and last, with the marker bit on the last. All three carry the same 90 kHz timestamp. Smaller frames holding only the changes follow, 25 a second.":"La caméra envoie une image clé, une image entière, en trois paquets RTP : des fragments H.264 marqués premier, milieu et dernier, avec le bit marqueur sur le dernier. Les trois portent le même horodatage à 90 kHz. Suivent des images plus petites qui ne contiennent que les changements, 25 par seconde.",Packets:"Paquets","3 for one key frame":"3 pour une image clé","Same for the whole frame":"Le même pour toute l’image",Frames:"Images","25 a second":"25 par seconde","a key frame in 3 packets":"une image clé en 3 paquets",Stop:"Arrêt","TEARDOWN ends the session":"TEARDOWN ferme la session","When the viewer closes the stream, VLC sends TEARDOWN with the session ID. The camera stops sending video and confirms. Had VLC simply vanished, the camera would stop anyway once 60 seconds passed without a word from it.":"Quand le spectateur ferme le flux, VLC envoie TEARDOWN avec l’ID de session. La caméra arrête d’envoyer la vidéo et confirme. Si VLC avait simplement disparu, la caméra s’arrêterait quand même après 60 secondes sans nouvelles de lui.",Ended:"Fermée",Otherwise:"Sinon","Timeout after 60 s":"Expire après 60 s","stop session 1185d200":"ferme la session 1185d200",stopped:"arrêté","The camera. It is on the same network, so the frame goes straight to it, not through the router.":"La caméra. Elle est sur le même réseau, donc la trame va directement à elle, sans passer par le routeur.","The camera’s network port.":"Le port réseau de la caméra.","RTP + video":"RTP + vidéo","0, 96 (H.264, as the camera’s description said)":"0, 96 (H.264, comme le disait la description de la caméra)","Marker clear: more of this frame follows.":"Marqueur à zéro : la suite de cette image arrive.","Video clock at 90,000 per second; every packet of one frame has the same value.":"Horloge vidéo à 90 000 par seconde ; tous les paquets d’une même image portent la même valeur.","Identifies this video stream.":"Identifie ce flux vidéo.","FU indicator":"Indicateur FU","0x7c (fragment of a frame)":"0x7c (fragment d’une image)","Fragmentation unit: one piece of a frame too big for one packet.":"Unité de fragmentation : un morceau d’une image trop grande pour un seul paquet.","FU header":"En-tête FU","0x85 (first piece of a key frame)":"0x85 (premier morceau d’une image clé)","Type 5: a key frame (IDR), a whole picture the decoder can start from.":"Type 5 : une image clé (IDR), une image entière à partir de laquelle le décodeur peut démarrer.","1398 bytes of the key frame":"1398 octets de l’image clé","0x05 (middle piece of a key frame)":"0x05 (morceau du milieu d’une image clé)","1, 96 (H.264, as the camera’s description said)":"1, 96 (H.264, comme le disait la description de la caméra)","Marker set: the last packet of a frame.":"Marqueur à un : le dernier paquet d’une image.","0x45 (last piece of a key frame)":"0x45 (dernier morceau d’une image clé)","900 bytes of the key frame":"900 octets de l’image clé","Multicast TV":"TV en multicast","Joins and leaves":"Abonnements et départs","Channel 1":"Chaîne 1","TV channels":"Chaînes TV","Internet Group Management Protocol":"Internet Group Management Protocol","Multicast sends one stream to a group address, and the network copies it only where it’s wanted: it’s how internet providers deliver live TV channels. IGMP is how a device tells its router which groups it wants. Switches listen in (IGMP snooping), so each stream reaches only the ports that asked for it.":"Le multicast envoie un seul flux vers une adresse de groupe, et le réseau ne le copie que là où on le veut : c’est ainsi que les fournisseurs d’accès diffusent les chaînes TV en direct. IGMP permet à un appareil de dire à son routeur quels groupes il veut. Les commutateurs écoutent (IGMP snooping), donc chaque flux n’atteint que les ports qui l’ont demandé.","IP protocol 2":"Protocole IP 2",Groups:"Groupes","Version here":"Version ici","Tuned In":"Branché","Joined, copied, checked, left":"Abonné, copié, vérifié, parti","The TV box and then the laptop joined channel 1 with IGMP reports. The router joined once for the whole home, and the switch, listening in, copied the channel only to the ports that wanted it. Queries kept it flowing, and when the laptop left, the TV box’s answer kept it on. Press REPLAY to watch it again.":"La box TV puis le portable ont rejoint la chaîne 1 avec des rapports IGMP. Le routeur s’est abonné une seule fois pour toute la maison, et le commutateur, à l’écoute, n’a copié la chaîne que vers les ports qui la voulaient. Les requêtes l’ont maintenue, et quand le portable est parti, la réponse de la box TV l’a gardée allumée. Appuyez sur REVOIR pour tout revoir.",Upstream:"Vers le fournisseur","One stream for the home":"Un seul flux pour la maison","Copies to ports that joined":"Copie vers les ports abonnés","Every 125 s":"Toutes les 125 s","Pick a Channel":"Choisir une chaîne","The TV box joins a group":"La box TV rejoint un groupe","The viewer picks channel 1. Each channel is a multicast group, here 233.252.0.1, and the TV box sends an IGMP Membership Report to that address: I want this group. The switch listens in (IGMP snooping), notes port 2, and passes the report to the router alone.":"Le spectateur choisit la chaîne 1. Chaque chaîne est un groupe multicast, ici 233.252.0.1, et la box TV envoie un IGMP Membership Report à cette adresse : je veux ce groupe. Le commutateur écoute (IGMP snooping), note le port 2 et ne transmet le rapport qu’au routeur.","Switch notes":"Le commutateur note","Port 2 wants it":"Le port 2 la veut","233.252.0.1, please":"233.252.0.1, s’il te plaît","to the router port only":"vers le port du routeur seulement","Ask the Provider":"Demander au fournisseur","The router joins for the home":"Le routeur s’abonne pour la maison","The router is an IGMP proxy: it joins the group on its internet side with a report of its own, from its public address, and the provider’s network starts sending channel 1 down the line. However many screens at home tune in, the router joins only once.":"Le routeur est un proxy IGMP : il rejoint le groupe côté internet avec son propre rapport, depuis son adresse publique, et le réseau du fournisseur commence à envoyer la chaîne 1 sur la ligne. Quel que soit le nombre d’écrans qui la regardent à la maison, le routeur ne s’abonne qu’une fois.","Router role":"Rôle du routeur","IGMP proxy":"Proxy IGMP",Joins:"S’abonne","Once for the whole home":"Une fois pour toute la maison","for the whole home":"pour toute la maison","The Channel Flows":"La chaîne arrive","Sent only where it was asked for":"Envoyée seulement là où on l’a demandée","The provider’s TV server sends channel 1 to 233.252.0.1: UDP datagrams holding seven 188-byte MPEG-TS packets of video and audio each. The router passes them in, and the switch sends them out of port 2 alone: only the TV box joined, so the laptop gets none.":"Le serveur TV du fournisseur envoie la chaîne 1 à 233.252.0.1 : des datagrammes UDP contenant chacun sept paquets MPEG-TS de 188 octets de vidéo et d’audio. Le routeur les fait entrer, et le commutateur ne les sort que par le port 2 : seule la box TV s’est abonnée, donc le portable n’en reçoit aucun.",Datagram:"Datagramme","UDP, 1,316 bytes of TV":"UDP, 1 316 octets de TV",Holds:"Contient","7 MPEG-TS packets":"7 paquets MPEG-TS","CHANNEL 1":"CHAÎNE 1","MPEG-TS over UDP":"MPEG-TS sur UDP","passed into the home":"transmis dans la maison","port 2 only":"port 2 seulement","A Second Screen":"Un deuxième écran","The laptop tunes in too":"Le portable s’y met aussi","The laptop opens channel 1 in VLC and sends its own report. The switch adds port 1 and now makes two copies of every datagram. The router already gets the channel, so it asks the provider for nothing: one stream still comes down the line.":"Le portable ouvre la chaîne 1 dans VLC et envoie son propre rapport. Le commutateur ajoute le port 1 et fait désormais deux copies de chaque datagramme. Le routeur reçoit déjà la chaîne, il ne demande donc rien au fournisseur : un seul flux arrive toujours par la ligne.","Switch sends to":"Le commutateur envoie à","Ports 1 and 2":"Ports 1 et 2","Still one stream":"Toujours un seul flux","Router asks":"Le routeur demande","Nothing new":"Rien de nouveau","the same one stream":"le même flux unique","copied to ports 1 and 2":"copié vers les ports 1 et 2","Still Watching?":"Toujours là ?","The router checks regularly":"Le routeur vérifie régulièrement","Every 125 seconds the router sends a General Query to 224.0.0.1, every device: which groups do you still want? The switch passes it to every port. Each member answers at a random moment within 10 seconds, so the router and the switch keep the channel coming.":"Toutes les 125 secondes, le routeur envoie une General Query à 224.0.0.1, tous les appareils : quels groupes voulez-vous encore ? Le commutateur la transmet à tous les ports. Chaque membre répond à un moment aléatoire dans les 10 secondes, donc le routeur et le commutateur continuent de faire venir la chaîne.","125 seconds":"125 secondes","224.0.0.1, all devices":"224.0.0.1, tous les appareils","Answer within":"Réponse sous","10 seconds":"10 secondes",QUERY:"REQUÊTE","any groups wanted?":"quels groupes voulez-vous ?","to every port":"vers tous les ports",REPORT:"RAPPORT","still watching":"toujours là",Leave:"Départ","The laptop stops watching":"Le portable arrête de regarder","Closing VLC sends a Leave Group to 224.0.0.2, all routers. Others may still watch, so the router asks about that group alone and waits 1 second. The TV box answers, so the channel stays; the switch just stops sending it to port 1.":"Fermer VLC envoie un Leave Group à 224.0.0.2, tous les routeurs. D’autres regardent peut-être encore, alors le routeur interroge sur ce seul groupe et attend 1 seconde. La box TV répond, donc la chaîne reste ; le commutateur arrête seulement de l’envoyer au port 1.","Leave sent to":"Départ envoyé à","224.0.0.2, all routers":"224.0.0.2, tous les routeurs","About that group alone":"Sur ce seul groupe","Stays: the TV box answered":"Reste : la box TV a répondu",LEAVE:"DÉPART","done with 233.252.0.1":"fini avec 233.252.0.1","anyone for 233.252.0.1?":"quelqu’un pour 233.252.0.1 ?","to the ports that joined":"vers les ports abonnés","Multicast: 01:00:5e, then the last 23 bits of the group address. Network cards listen for the groups their system has joined.":"Multicast : 01:00:5e, puis les 23 derniers bits de l’adresse du groupe. Les cartes réseau écoutent les groupes que leur système a rejoints.","The TV box’s network port.":"Le port réseau de la box TV.","4, 24 bytes":"4, 24 octets","IPv4, with one 4-byte option.":"IPv4, avec une option de 4 octets.","48 (network control), 0":"48 (contrôle réseau), 0","Marked as network control, so it is sent ahead of ordinary traffic.":"Marqué comme contrôle réseau, donc envoyé avant le trafic ordinaire.","Always 1: IGMP never goes past the first router.":"Toujours 1 : IGMP ne dépasse jamais le premier routeur.","A multicast group address.":"Une adresse de groupe multicast.","Router Alert option":"Option Router Alert","Asks every router on the way to look inside, though the packet isn’t addressed to it.":"Demande à chaque routeur du chemin de regarder dedans, même si le paquet ne lui est pas adressé.","This device wants the group’s traffic.":"Cet appareil veut le trafic du groupe.","Max response time":"Délai de réponse max","Only queries use it.":"Seules les requêtes l’utilisent.","Covers the IGMP message.":"Couvre le message IGMP.","Group address":"Adresse du groupe","The multicast group: one TV channel.":"Le groupe multicast : une chaîne TV.","Seen arriving on the router’s internet side":"Vue en arrivant côté internet du routeur","MPEG-TS · 7 packets":"MPEG-TS · 7 paquets","The provider’s router, passing the channel on.":"Le routeur du fournisseur, qui fait suivre la chaîne.","Sync byte":"Octet de synchro","Every transport stream packet starts with 0x47, so the receiver can find where packets begin.":"Tout paquet de transport stream commence par 0x47, pour que le récepteur trouve où commencent les paquets.","Flags, PID":"Drapeaux, PID","0x0100 (PID 256: video)":"0x0100 (PID 256 : vidéo)","Which stream the packet belongs to: the channel’s video, its audio, or the tables that list them.":"Le flux auquel appartient le paquet : la vidéo de la chaîne, son audio, ou les tables qui les répertorient.","Payload, counter":"Charge, compteur","0x14 (payload only, counter 4)":"0x14 (charge seule, compteur 4)","Counts 0 to 15 for each PID, so a lost packet shows up as a gap.":"Compte de 0 à 15 pour chaque PID, donc un paquet perdu se voit comme un trou.","184 bytes of the channel’s video":"184 octets de la vidéo de la chaîne","More packets":"Autres paquets","6 × 188 bytes: video and audio":"6 × 188 octets : vidéo et audio","Six more transport stream packets, each with its own 4-byte header.":"Six autres paquets de transport stream, chacun avec son propre en-tête de 4 octets.","Seen going into the switch, port 8":"Vue en entrant dans le commutateur, port 8","The router, passing the channel into the home.":"Le routeur, qui fait entrer la chaîne dans la maison.","0x19 (payload only, counter 9)":"0x19 (charge seule, compteur 9)","The router asks: which groups does anyone here still want?":"Le routeur demande : quels groupes quelqu’un ici veut-il encore ?","Members answer at a random moment within this time, so their answers don’t all arrive at once.":"Les membres répondent à un moment aléatoire dans ce délai, pour que leurs réponses n’arrivent pas toutes en même temps.","Zero in a general query: every group.":"Zéro dans une requête générale : tous les groupes.","This device no longer wants the group.":"Cet appareil ne veut plus du groupe.","The router asks: does anyone still want this group?":"Le routeur demande : quelqu’un veut-il encore ce groupe ?","Live Streaming Upload":"Envoi de directs","RTMP handshake":"Poignée de main RTMP","Video and audio":"Vidéo et audio","Ingest Server":"Serveur d’ingest","Real-Time Messaging Protocol":"Real-Time Messaging Protocol","RTMP is how most streamers send live video to a platform: OBS and other apps push it to an ingest server, which turns it into streams for viewers. Made for Flash, it outlived Flash as the way to upload. Everything shares one TCP connection: commands, audio and video, cut into chunks.":"RTMP est la façon dont la plupart des streamers envoient leur vidéo en direct à une plateforme : OBS et d’autres applis la poussent vers un serveur d’ingest, qui en fait des flux pour les spectateurs. Conçu pour Flash, il a survécu à Flash comme moyen d’envoi. Tout partage une seule connexion TCP : commandes, audio et vidéo, découpés en chunks.","H.264 video, AAC audio":"Vidéo H.264, audio AAC","Encoded in AMF0":"Encodées en AMF0","Secure version":"Version sécurisée","RTMPS, over TLS":"RTMPS, sur TLS","Adobe specification (2012)":"Spécification Adobe (2012)",Live:"En direct","Connected, published, streamed":"Connecté, publié, diffusé","OBS shook hands with the ingest server, connected to its live app, got stream 1 and published to it with the stream key. The video and audio then flowed in chunks over the same TCP connection until the streamer stopped. Press REPLAY to watch it again.":"OBS a fait la poignée de main avec le serveur d’ingest, s’est connecté à son appli live, a obtenu le stream 1 et y a publié avec la clé de stream. La vidéo et l’audio ont ensuite circulé en chunks sur la même connexion TCP jusqu’à l’arrêt du streamer. Appuyez sur REVOIR pour tout revoir.","One TCP, port 1935":"Une TCP, port 1935",Stream:"Stream",Chunks:"Chunks","Up to 4,096 bytes":"Jusqu’à 4 096 octets","None: RTMPS adds TLS":"Aucun : RTMPS ajoute TLS","TCP, then RTMP’s own":"TCP, puis celle de RTMP","The streamer clicks Start Streaming. OBS connects to the ingest server on TCP port 1935, then RTMP has its own handshake: version 3 and 1,536 random bytes each way, which each side sends back. It shows both ends speak RTMP; it encrypts nothing.":"Le streamer clique sur Démarrer le streaming. OBS se connecte au serveur d’ingest sur le port TCP 1935, puis RTMP fait sa propre poignée de main : version 3 et 1 536 octets aléatoires dans chaque sens, que chaque côté renvoie. Elle montre que les deux bouts parlent RTMP ; elle ne chiffre rien.","Each side":"Chaque côté","Sends 3,073 bytes":"Envoie 3 073 octets","version 3":"version 3","1,536 random bytes":"1 536 octets aléatoires","version 3, its own bytes":"version 3, ses propres octets","and C1 sent back":"et C1 renvoyé","S1 sent back":"S1 renvoyé",Connect:"Connexion","To the server’s live app":"À l’appli live du serveur","OBS raises its chunk size to 4,096 bytes and sends connect for the app called live, in AMF0, a compact binary format from Flash. The server sets its own window, bandwidth and chunk size, and answers _result: NetConnection.Connect.Success.":"OBS porte sa taille de chunk à 4 096 octets et envoie connect pour l’appli nommée live, en AMF0, un format binaire compact venu de Flash. Le serveur fixe sa propre fenêtre, sa bande passante et sa taille de chunk, et répond _result : NetConnection.Connect.Success.",App:"Appli",Encoding:"Encodage","chunk size 4,096":"chunks de 4 096","window, bandwidth, chunks":"fenêtre, bande passante, chunks","Make a Stream":"Créer un stream","createStream returns stream 1":"createStream renvoie le stream 1","Every message names a message stream; 0 is the connection itself. OBS releases and announces its stream key, then asks createStream for a stream to send on, all three commands in one packet. The server answers with stream ID 1.":"Chaque message nomme un stream de messages ; le 0 est la connexion elle-même. OBS libère et annonce sa clé de stream, puis demande avec createStream un stream sur lequel envoyer, les trois commandes dans un seul paquet. Le serveur répond avec le stream ID 1.","3 in one packet":"3 dans un paquet",Gets:"Obtient","Stream ID 1":"Stream ID 1","stream ID 1":"stream ID 1",Publish:"Publication","The stream key goes live":"La clé de stream passe en direct","publish names the stream key, the secret that says whose channel this is. RTMP has no encryption, so the key crosses in plain text; platforms prefer RTMPS, the same over TLS. The server checks the key and answers NetStream.Publish.Start.":"publish donne la clé de stream, le secret qui dit à qui est la chaîne. RTMP ne chiffre rien, donc la clé passe en clair ; les plateformes préfèrent RTMPS, la même chose sur TLS. Le serveur vérifie la clé et répond NetStream.Publish.Start.","The stream key":"La clé de stream","None (RTMPS adds TLS)":"Aucun (RTMPS ajoute TLS)","on stream 1":"sur le stream 1","stream key, live":"clé de stream, live","Video and Sound":"Image et son","Metadata, settings, then frames":"Métadonnées, réglages, puis images","OBS describes the stream: 1920×1080 at 30 frames a second, H.264 video, AAC audio. It sends the decoders’ settings, then a key frame, about 30 KB cut into 4,096-byte chunks. Frames follow non-stop, on the same TCP connection.":"OBS décrit le flux : 1920×1080 à 30 images par seconde, vidéo H.264, audio AAC. Il envoie les réglages des décodeurs, puis une image clé d’environ 30 Ko découpée en chunks de 4 096 octets. Les images suivent sans arrêt, sur la même connexion TCP.","AAC, 48 kHz stereo":"AAC, 48 kHz stéréo","30 KB in 8 chunks":"30 Ko en 8 chunks",METADATA:"MÉTADONNÉES","H.264 + AAC settings":"réglages H.264 et AAC","KEY FRAME":"IMAGE CLÉ","8 chunks":"8 chunks","Stop Streaming":"Arrêt du stream","FCUnpublish and deleteStream":"FCUnpublish et deleteStream","When the streamer clicks Stop Streaming, OBS sends FCUnpublish and deleteStream for stream 1. The server answers NetStream.Unpublish.Success and ends the broadcast for viewers. Then OBS closes the TCP connection.":"Quand le streamer clique sur Arrêter le streaming, OBS envoie FCUnpublish et deleteStream pour le stream 1. Le serveur répond NetStream.Unpublish.Success et met fin à la diffusion pour les spectateurs. Puis OBS ferme la connexion TCP.","C0: version":"C0 : version","RTMP version 3, the only one in use.":"RTMP version 3, la seule en usage.",Time:"Temps","A timestamp; zero is allowed.":"Un horodatage ; zéro est permis.",Zero:"Zéro","Random data":"Données aléatoires","Random bytes the server must send back.":"Des octets aléatoires que le serveur doit renvoyer.","S0: version":"S0 : version","Random bytes the client must send back.":"Des octets aléatoires que le client doit renvoyer.","1,536 bytes: C1 back":"1 536 octets : C1 renvoyé","The timestamp from the block it echoes.":"L’horodatage du bloc qu’il renvoie.","Time read":"Temps lu","C1’s random bytes, sent back unchanged.":"Les octets aléatoires de C1, renvoyés tels quels.","1,536 bytes: S1 back":"1 536 octets : S1 renvoyé","S1’s random bytes, sent back unchanged.":"Les octets aléatoires de S1, renvoyés tels quels.","RTMP · 2 messages":"RTMP · 2 messages","First message":"Premier message","Chunk header":"En-tête de chunk","type 0, chunk stream 2":"type 0, chunk stream 2","A full header follows: this chunk starts a message.":"Un en-tête complet suit : ce chunk commence un message.","Message stream":"Stream de messages","Stream 0: the connection itself. (This number alone is little-endian.)":"Stream 0 : la connexion elle-même. (Seul ce nombre est en little-endian.)","Chunk size":"Taille de chunk","From now on this side cuts messages into chunks of up to this size (128 until it says otherwise).":"Désormais, ce côté découpe les messages en chunks d’au plus cette taille (128 tant qu’il ne dit pas autre chose).","Second message":"Deuxième message","type 0, chunk stream 3":"type 0, chunk stream 3","Matches a reply to its request.":"Associe une réponse à sa requête.","Command object":"Objet de commande","object, 5 properties":"objet, 5 propriétés","Which app on the server, and the address OBS was given.":"Quelle appli du serveur, et l’adresse donnée à OBS.","End of object":"Fin de l’objet","RTMP · 4 messages":"RTMP · 4 messages","The other side should hear back after every this many bytes it sends.":"L’autre côté doit recevoir un retour après chaque tranche d’autant d’octets qu’il envoie.","Bandwidth, limit":"Bande passante, limite","5,000,000 bytes, dynamic":"5 000 000 octets, dynamique","How much the sender may have unacknowledged at once.":"Ce que l’émetteur peut avoir en attente d’accusé à la fois.","Third message":"Troisième message","Fourth message":"Quatrième message",Properties:"Propriétés","object, 2 properties":"objet, 2 propriétés",Information:"Informations","object, 4 properties":"objet, 4 propriétés","RTMP · 3 messages":"RTMP · 3 messages","Nothing: AMF0 null.":"Rien : null en AMF0.","Stream key":"Clé de stream","Which channel this is. It works like a password, and here it travels unencrypted.":"Quelle chaîne c’est. Elle sert de mot de passe, et ici elle voyage en clair.","Stream ID":"Stream ID","The new stream: video and audio will go on it.":"Le nouveau stream : la vidéo et l’audio passeront dessus.","type 0, chunk stream 4":"type 0, chunk stream 4","Stream 1, the one createStream made.":"Stream 1, celui créé par createStream.","Publishing type":"Type de publication","Live: not recorded by this request.":"Live : cette requête n’enregistre rien.","type 0, chunk stream 5":"type 0, chunk stream 5","object, 3 properties":"objet, 3 propriétés",Handler:"Gestionnaire",Event:"Événement",Metadata:"Métadonnées","array of 14":"tableau de 14","Codec IDs as in Flash video files: 7 is H.264, 10 is AAC.":"Identifiants de codec comme dans les fichiers vidéo Flash : 7 est H.264, 10 est AAC.","type 0, chunk stream 6":"type 0, chunk stream 6","Frame, codec":"Image, codec","0x17 (key frame, H.264)":"0x17 (image clé, H.264)","AVC packet type":"Type de paquet AVC","0 (decoder settings)":"0 (réglages du décodeur)","The sequence header: the settings a decoder needs before the first frame.":"L’en-tête de séquence : les réglages dont un décodeur a besoin avant la première image.","Composition time":"Temps de composition","The H.264 profile, level and parameter sets.":"Le profil, le niveau et les jeux de paramètres H.264.","AAC; the other bits are fixed for AAC.":"AAC ; les autres bits sont fixes pour AAC.","AAC packet type":"Type de paquet AAC","Sample rate and channels, for the decoder.":"Fréquence d’échantillonnage et canaux, pour le décodeur.","1 (video)":"1 (vidéo)","Compressed picture data.":"Données d’image compressées.","The key frame: a whole picture. Every 4,096 bytes a 1-byte chunk header continues it.":"L’image clé : une image entière. Tous les 4 096 octets, un en-tête de chunk d’1 octet la poursuit."},r=t=>`${t} ${t==="1"?"octet":"octets"}`,o=t=>`${t} ${t==="1"?"enregistrement":"enregistrements"}`,h={strings:{...c,...d,...l},patterns:[[/^([\d,]+) bytes$/,(t,e)=>r(e)],[/^(Ethernet II|IPv4|IPv6|UDP|TCP|802\.11|LLC\/SNAP|EAPOL) · (\d+) bytes$/,"$1 · $2 octets"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,(t,e,s)=>`${e}, ${r(s)}`],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 octets : report.pdf, octets $2"],[/^(.+) h later$/,"$1 h plus tard"],[/^(.+) min later$/,"$1 min plus tard"],[/^(.+) s later$/,"$1 s plus tard"],[/^(\S+) \(relative\)$/,"$1 (relatif)"],[/^(\d+) \(ephemeral\)$/,"$1 (éphémère)"],[/^(\d+) TCP segments$/,"$1 segments TCP"],[/^(\d+) segments$/,"$1 segments"],[/^(.*), (\d+) segments$/,"$1, $2 segments"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(t,e,s,a)=>`TLS 1.3 · ${o(e)} · octets ${s} sur ${a}`],[/^TLS 1\.3 · (\d+) records?$/,(t,e)=>`TLS 1.3 · ${o(e)}`],[/^Ethernet padding · (\d+) bytes$/,"Bourrage Ethernet · $1 octets"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 octets à zéro, jusqu’au minimum de 300 octets"],[/^(\d+) zero bytes$/,"$1 octets à zéro"],[/^(\d+) random bytes$/,"$1 octets aléatoires"],[/^Seen as it leaves (.+)$/,"Vu à la sortie de $1"],[/^Option (\d+)$/,"Option $1"],[/^value (\d+), echo (\d+)$/,"valeur $1, écho $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 octets, plus $1 d’options."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows démarre à $1. Réglé ici à $2 exprès."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(t,e,s)=>s==="1"?`Parti de ${e} ; le routeur sur le chemin a retiré 1.`:`Parti de ${e} ; chacun des ${s} routeurs sur le chemin a retiré 1.`],[/^all (\d+) bytes of it$/,"ses $1 octets en entier"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Le paquet qui a causé ceci, tel que l’appareil qui le signale l’a reçu (TTL $1), pour que l’émetteur sache de quel paquet il s’agit."],[/^Port (\d+), TLS from the start$/,"Port $1, TLS dès le départ"],[/^(\d+), TLS from the start$/,"$1, TLS dès le départ"],[/^type 79, (\d+) bytes$/,(t,e)=>`type 79, ${r(e)}`],[/^(\d+) of (\d+) bytes$/,(t,e,s)=>`${e} sur ${r(s)}`],[/^(\d+) more bytes$/,(t,e)=>`${r(e)} de plus`],[/^offset (\d+), (\d+) bytes$/,(t,e,s)=>`décalage ${e}, ${r(s)}`],[/^offset 0, (\d+) bytes \(all of it\)$/,(t,e)=>`décalage 0, ${r(e)} (en entier)`],[/^record, (\d+) bytes$/,(t,e)=>`enregistrement, ${r(e)}`],[/^EAPOL-Key · message (\d) of 4$/,"EAPOL-Key · message $1 sur 4"],[/^((?:SMB2|IKEv2) · )?([A-Z_]+) (request|response)$/,(t,e,s,a)=>{const n=a==="request"?"requête":"réponse";return e?`${e}${n} ${s}`:`${n[0].toUpperCase()}${n.slice(1)} ${s}`}],[/^(\d+) registers$/,"$1 registres"],[/^id 1: −(\d+) dBov, voice$/,"id 1: −$1 dBov, voix"],[/^"(.*)" \(([\d,]+) bytes\)$/,(t,e,s)=>`"${e}" (${r(s)})`],[/^(masked|not masked), (\d+) bytes?$/,(t,e,s)=>`${e==="masked"?"masqué":"non masqué"}, ${r(s)}`],[/^(\d+) \(disguised\)$/,"$1 (dissimulé)"],[/^(\d+) \((KE|Nonce|Notify|IDi|IDr)\), (\d+) bytes$/,(t,e,s,a)=>`${e} (${s}), ${r(a)}`],[/^0 \(none\), (\d+) bytes$/,(t,e)=>`0 (aucun), ${r(e)}`],[/^Microsoft \(311\), type (\d+)$/,"Microsoft (311), type $1"],[/^(\d+) \(register (\d+)\)$/,"$1 (registre $2)"],[/^yes, AS (\d+)$/,"oui, AS $1"],[/^id 2, (\d+) bytes$/,(t,e)=>`id 2, ${r(e)}`],[/^(\d), (\d+) \((Opus|VP8), as agreed in the SDP\)$/,"$1, $2 ($3, comme convenu dans le SDP)"]],post:t=>i(u(t))};export{h as default};
